/**
 * Lessons Data — all paths (fundamentals, sales, inventory, purchase, accounting, manufacturing, hr, technical, pos, project, integrations, labs)
 */
const LessonsData = [
  // PATH 1: Fundamentals (10)
  {id:'fundamentals-01',path:'fundamentals',order:1,title:{ar:'ما هو أودو؟',en:'What is Odoo?'},description:{ar:'مقدمة إلى نظام أودو',en:'Introduction to Odoo'},duration:8,xp:20,
    objectives:{ar:['فهم ما هو نظام ERP','معرفة مميزات أودو','تمييز أودو عن الأنظمة التقليدية','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Understand ERP','Know Odoo features','Distinguish Odoo','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'أودو (Odoo) نظام ERP متكامل: مبيعات، مخزون، محاسبة، موارد بشرية وتطبيقات أخرى في منصة واحدة. بدل عدة برامج منفصلة تعمل على بيانات موحّدة.',en:'Odoo is an integrated ERP: sales, inventory, accounting, HR and more in one platform. Instead of separate tools, you work on unified data.'}},
      {type:'visual',title:{ar:'شاشة التطبيقات في أودو',en:'Odoo apps screen'},content:{ar:'بعد تسجيل الدخول تظهر شبكة التطبيقات. كل أيقونة تطبيق (Sales، Inventory، CRM…). هذا هو مركز التنقل الرئيسي.',en:'After login you see the apps grid. Each icon is an app (Sales, Inventory, CRM…). This is the main navigation hub.'},image:'apps-menu.png',caption:{ar:'<strong>شبكة التطبيقات</strong> — كل أيقونة تفتح تطبيقاً مستقلاً (Sales، Inventory، CRM…). ابدأ من هنا دائماً.',en:'<strong>Apps grid</strong> — each icon opens an independent app (Sales, Inventory, CRM…). Always start here.'}},
      {type:'concept',title:{ar:'كيف يعمل أودو؟',en:'How Odoo works'},content:{ar:'• التطبيقات (Apps): تثبّت ما تحتاجه فقط.\n• السجلات (Records): عميل، منتج، عرض سعر…\n• المستندات: تنتقل من حالة إلى أخرى (مسودة → مؤكد → منجز).',en:'• Apps: install only what you need.\n• Records: customer, product, quotation…\n• Documents move through statuses (Draft → Confirmed → Done).'}},
      {type:'concept',title:{ar:'خطوات عملية — من أين تبدأ؟',en:'Practical steps — where to start'},content:{ar:'1) افهم الفكرة العامة (هذا الدرس).\n2) تعلّم الواجهة والتنقل.\n3) درّب على مسار بسيط: عميل → عرض سعر → أمر بيع.\n4) ثم المخزون والاستلام.',en:'1) Understand the big picture (this lesson).\n2) Learn the interface and navigation.\n3) Practice a simple flow: customer → quotation → sales order.\n4) Then inventory and receipts.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'شركة تجارة صغيرة: تثبّت Contacts + Sales + Inventory فقط، تتعلم مسار عميل → عرض → أمر بيع، ثم تضيف المحاسبة لاحقاً.',en:'A small trading company: installs only Contacts + Sales + Inventory, learns customer → quote → sales order, then adds accounting later.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح أودو (تجريبي إن أمكن) ولاحظ شاشة Apps: كل أيقونة تطبيق. لا تثبّت تطبيقات كثيرة دفعة واحدة — ابدأ بـ Contacts و Sales فقط.',en:'Open Odoo (trial if possible) and look at the Apps screen: each icon is an app. Do not install many apps at once — start with Contacts and Sales only.'}},
      {type:'why',title:{ar:'لماذا نبدأ بأودو؟',en:'Why start with Odoo?'},content:{ar:'لأن أودو يجمع العملاء والمبيعات والمخزون في شاشات مترابطة. تتعلم شاشة واحدة وتُعيد استخدامها في باقي التطبيقات.',en:'Because Odoo links customers, sales and stock across related screens. You learn one screen pattern and reuse it in other apps.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تثبت كل التطبيقات دفعة واحدة. ابدأ بـ Sales و Inventory و Contacts. راجعه على الشاشة قبل الانتقال.',en:'Do not install every app at once. Start with Sales, Inventory and Contacts. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'التعامل مع أودو كبرنامج واحد ضخم بدل مجموعة تطبيقات مترابطة — فيصعب التعلم. راجعه على الشاشة قبل الانتقال.',en:'Treating Odoo as one huge program instead of linked apps — learning becomes harder. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'أودو كنظام ERP يعني عملياً على الشاشة؟',en:'Odoo as an ERP means in practice on screen?'},options:{ar:['نظام بريد','نظام متكامل لإدارة موارد المؤسسة','برنامج محاسبة فقط','تصميم مواقع'],en:['Email system','Enterprise Resource Planning system','Accounting only','Website design']},answer:1,explanation:{ar:'ERP = Enterprise Resource Planning — نظام متكامل يدير موارد الشركة.',en:'ERP = Enterprise Resource Planning — integrated system managing company resources.'}}},
  {id:'fundamentals-02',path:'fundamentals',order:2,title:{ar:'فهم واجهة أودو',en:'Understanding the Odoo Interface'},description:{ar:'Control Panel و List و Form و Chatter من الشاشة إلى الطبقة التقنية',en:'Control Panel, List, Form and Chatter from screen to technical layer'},duration:18,xp:30,
    objectives:{ar:['تمييز مناطق الشاشة','فهم List مقابل Form','معرفة Action و View و Model','تطبيق Save والتنقل الآمن'],en:['Identify screen regions','Understand List vs Form','Know Action, View and Model','Apply Save and safe navigation']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'واجهة أودو إطار واحد لكل التطبيقات. ما تتعلمه في Contacts ينطبق على Sales و Inventory و Accounting. وظيفياً: أين أبحث وأحفظ وأؤكد. تقنياً: Menu يفتح Action فيفتح View على Model.',en:'The Odoo UI is one framework for every app. What you learn in Contacts applies to Sales, Inventory and Accounting. Functionally: where to search, save and confirm. Technically: Menu opens Action which opens View on a Model.'}},
      {type:'why',title:{ar:'لماذا الواجهة أولاً؟',en:'Why the interface first?'},content:{ar:'معظم أخطاء التشغيل ليست في الضريبة أو المسار المخزني، بل في عدم الحفظ، أو فلتر مخفي، أو شركة نشطة خاطئة، أو زر لا يظهر بسبب state. إتقان الشاشة يقلل نصف طلبات الدعم.',en:'Most operational errors are not tax or routes, but unsaved forms, hidden filters, wrong active company, or a button missing because of state. Mastering the screen cuts half of support tickets.'}},
      {type:'visual',title:{ar:'شبكة التطبيقات',en:'Apps grid'},content:{ar:'بعد الدخول: شبكة الأيقونات. كل أيقونة تطبيق مثبت ومصرّح به لمجموعتك. الشريط العلوي: الشركة، المستخدم، الرسائل.',en:'After login: icon grid. Each icon is an installed app allowed for your groups. Top bar: company, user, messages.'},image:'apps-menu.png',caption:{ar:'<strong>Apps / Home Menu</strong> — نقطة الدخول. تقنياً: قوائم ir.ui.menu تظهر حسب المجموعات.',en:'<strong>Apps / Home Menu</strong> — entry point. Technically: ir.ui.menu items shown per groups.'}},
      {type:'concept',title:{ar:'مناطق الشاشة داخل التطبيق',en:'Screen regions inside an app'},content:{ar:'1) Control Panel: عنوان القائمة، New، مبدّل List/Kanban/Graph/Pivot، البحث و Filters و Group By و Favorites.\\n2) List View: صفوف السجلات، أعمدة الحقول، تحديد جماعي.\\n3) Form View: Statusbar للحالة، أزرار Header (Confirm…)، Smart Buttons، Sheet الحقول، Notebook للتبويبات، Chatter للأسفل.\\n4) تقنياً: Window Action (ir.actions.act_window) يحدد res_model و view_mode و domain و context.\\n5) Model مثال: sale.order أو res.partner — الحقول types: Many2one, One2many, Monetary, Selection (state).',en:'1) Control Panel: list title, New, List/Kanban/Graph/Pivot switch, search, Filters, Group By, Favorites.\\n2) List View: record rows, field columns, mass actions.\\n3) Form View: statusbar, header buttons (Confirm…), smart buttons, sheet fields, notebook tabs, chatter below.\\n4) Technically: Window Action (ir.actions.act_window) sets res_model, view_mode, domain, context.\\n5) Model examples: sale.order or res.partner — field types: Many2one, One2many, Monetary, Selection (state).'}},
      {type:'visual',title:{ar:'List View',en:'List View'},content:{ar:'المسح اليومي يبدأ هنا. انقر الصف لفتح Form. لا تعدّل من القائمة إلا في التعديل الجماعي بحذر.',en:'Daily scanning starts here. Click a row to open Form. Do not edit from the list except careful mass edit.'},image:'list-view.png',caption:{ar:'<strong>List View</strong> — صف = سجل Model. الأعمدة = Fields. النقر → Form.',en:'<strong>List View</strong> — row = Model record. Columns = Fields. Click → Form.'}},
      {type:'visual',title:{ar:'Form View',en:'Form View'},content:{ar:'التفاصيل والإجراءات. Statusbar = حقل state غالباً. Smart Buttons تفتح سجلات مرتبطة بـ domain جاهز. Chatter = mail.thread.',en:'Details and actions. Statusbar = usually state field. Smart buttons open related records with a ready domain. Chatter = mail.thread.'},image:'form-view.png',caption:{ar:'<strong>Form View</strong> — Header + Sheet + Notebook + Chatter. احفظ قبل المغادرة.',en:'<strong>Form View</strong> — Header + Sheet + Notebook + Chatter. Save before leaving.'}},
      {type:'example',title:{ar:'سيناريو',en:'Scenario'},content:{ar:'Sales → Quotations (List) → فتح صف (Form) → تعديل العميل → Save → Confirm. الحالة تتغير على Statusbar وتظهر Smart Buttons لاحقاً بعد التأكيد.',en:'Sales → Quotations (List) → open row (Form) → change customer → Save → Confirm. Statusbar changes and smart buttons appear after confirm.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'في تجريبي: Contacts → List → New → املأ الاسم → Save → ارجع List → ابحث. ثم فعّل Developer Mode ومرّر على حقل لرؤية الاسم التقني إن ظهر.',en:'In trial: Contacts → List → New → fill name → Save → back to List → search. Then enable Developer Mode and hover a field for technical name if shown.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا ضعت: أزل الفلاتر، تحقق الشركة أعلى الشاشة، ثم List → Form → Save. هذه الثلاثية تحل معظم الحيرة.',en:'If lost: clear filters, check company on top, then List → Form → Save. This trio solves most confusion.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'التنقل بين السجلات قبل Save — ضياع التعديل. أو افتراض أن زر Confirm عطل بينما state ليس Draft أو لا صلاحية.',en:'Navigating records before Save — lost edits. Or assuming Confirm is broken while state is not Draft or rights are missing.'}}
    ],
    knowledgeCheck:{question:{ar:'ماذا يفتح Menu تقنياً في أودو؟',en:'What does a Menu open technically in Odoo?'},options:{ar:['ملف Excel فقط','Action ثم View على Model','قاعدة بيانات أخرى','لا شيء'],en:['Excel file only','Action then View on a Model','Another database','Nothing']},answer:1,explanation:{ar:'Menu → Action → View على Model.',en:'Menu → Action → View on Model.'}}},
  
  {id:'fundamentals-03',path:'fundamentals',order:3,title:{ar:'التطبيقات والوحدات',en:'Apps and Modules'},description:{ar:'كيف تُثبَّت التطبيقات وما الفرق بينها',en:'How apps are installed and how they differ'},duration:12,xp:20,
    objectives:{ar:['الفرق بين App و Module','تثبيت ما تحتاجه فقط','ترتيب التثبيت المنطقي','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['App vs Module difference','Install only what you need','Logical install order','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'أودو مبني على تطبيقات (Apps). تثبّت ما تحتاجه: Sales، Inventory، Accounting… كل تطبيق يضيف قوائم وشاشات وبيانات مرتبطة بالباقي.',en:'Odoo is built on apps. You install what you need: Sales, Inventory, Accounting… Each app adds menus, screens and data linked to the rest.'}},
      {type:'why',title:{ar:'لماذا لا نثبّت الكل؟',en:'Why not install everything?'},content:{ar:'كل تطبيق إضافي يزيد التعقيد والقوائم والصلاحيات. البدء بالقليل يسهّل التعلم ويقلّل الأخطاء.',en:'Each extra app increases complexity, menus and access rights. Starting small makes learning easier and reduces mistakes.'}},
      {type:'visual',title:{ar:'شبكة التطبيقات',en:'Apps grid'},content:{ar:'من Apps ترى المثبت (يظهر عادة بلون أو علامة) والمتاح للتثبيت. التثبيت يضيف التطبيق فوراً إلى الشاشة الرئيسية.',en:'From Apps you see installed (usually marked) and available to install. Installing adds the app to the home screen immediately.'},image:'apps-menu.png',caption:{ar:'<strong>المثبت والمتاح</strong> — من Apps ترى ما هو مثبّت وما يمكن تثبيته لاحقاً.',en:'<strong>Installed vs available</strong> — from Apps you see what is installed and what can be added later.'}},
      {type:'concept',title:{ar:'خطوات التثبيت المنطقي',en:'Logical install steps'},content:{ar:'1) ابدأ بـ Contacts (أساس العملاء والموردين).\n2) أضف Sales و Inventory معاً لمسار البيع الكامل.\n3) أضف Accounting / Invoicing عند الحاجة للفواتير.\n4) أضف CRM إذا كان فريق المبيعات يتابع فرصاً.\n5) بقية التطبيقات حسب الحاجة فقط.',en:'1) Start with Contacts (base for customers and vendors).\n2) Add Sales and Inventory together for a full sales flow.\n3) Add Accounting / Invoicing when you need invoices.\n4) Add CRM if the sales team tracks opportunities.\n5) Other apps only as needed.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'شركة تجارة بسيطة: Contacts + Sales + Inventory + Invoicing كافية في البداية. لا حاجة لـ Manufacturing أو Project فوراً.',en:'A simple trading company: Contacts + Sales + Inventory + Invoicing is enough at first. No need for Manufacturing or Project immediately.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من Apps افتح Contacts ثم أنشئ Contact تجريبي (Company). احفظ وارجع للقائمة. لا تستخدم بيانات عملاء حقيقيين في بيئة تدريب مشتركة.',en:'From Apps open Contacts then create a trial Contact (Company). Save and return to the list. Do not use real customer data on a shared training DB.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'بعد التثبيت راجع القوائم الجديدة وصلاحيات المستخدمين — قد تظهر قوائم لمن لا يحتاجها. راجعه على الشاشة قبل الانتقال.',en:'After install, review new menus and user access rights — menus may appear for people who do not need them. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تثبيت كل التطبيقات «للاستكشاف» ثم صعوبة في معرفة من أين تبدأ. ثبّت حسب مسار عمل واضح. راجعه على الشاشة قبل الانتقال.',en:'Installing every app “to explore” then struggling to know where to start. Install according to a clear workflow. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'من شاشة Apps، ما أفضل ممارسة عند البدء؟',en:'From the Apps screen, what is best practice when starting?'},options:{ar:['تثبيت كل التطبيقات','تثبيت ما تحتاجه فقط حسب المسار','عدم تثبيت شيء','تثبيت المحاسبة فقط'],en:['Install every app','Install only what you need by workflow','Install nothing','Install accounting only']},answer:1,explanation:{ar:'التثبيت حسب الحاجة يقلّل التعقيد ويسرّع التعلم.',en:'Installing by need reduces complexity and speeds learning.'}}},
  
  {id:'fundamentals-04',path:'fundamentals',order:4,title:{ar:'المستخدمون وصلاحيات الوصول',en:'Users and Access Rights'},description:{ar:'Groups و ACL و Record Rules من الشاشة إلى الأمن الحقيقي',en:'Groups, ACL and Record Rules from screen to real security'},duration:20,xp:35,
    objectives:{ar:['إنشاء مستخدم من الشاشة','تمييز User و Administrator للتطبيق','فهم Access Rights مقابل Record Rules','اختبار الدخول بدور الموظف'],en:['Create a user from screen','Distinguish app User vs Administrator','Understand Access Rights vs Record Rules','Test login as the employee role']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المستخدم (res.users) يُمنح مجموعات (res.groups). المجموعات تعطي Access Rights على Models و Record Rules على الصفوف وقوائم القوائم. لا تُبنى الصلاحية زرّاً زرّاً يدوياً كل صباح.',en:'A user (res.users) is given groups (res.groups). Groups grant Access Rights on Models, Record Rules on rows, and menus. Rights are not built button-by-button every morning.'}},
      {type:'why',title:{ar:'لماذا الأمن الطبقي؟',en:'Why layered security?'},content:{ar:'ACL يقول هل تقرأ sale.order أصلاً. Record Rule يقول أي أوامر ترى. بلا الطبقتين: إما حجب كامل أو تسريب كل بيانات الشركة.',en:'ACL says whether you can read sale.order at all. Record Rule says which orders you see. Without both layers: total block or leakage of all company data.'}},
      {type:'visual',title:{ar:'قائمة المستخدمين',en:'Users list'},content:{ar:'Settings → Users & Companies → Users. List ثم Form. لا تختبر الصلاحيات وأنت دائماً Admin فقط.',en:'Settings → Users & Companies → Users. List then Form. Do not test rights while always logged in as Admin only.'},image:'access-rights.svg',caption:{ar:'<strong>Settings → Users / Access Rights</strong> — Model: res.users. افتح البطاقة لضبط Access Rights والشركات.',en:'<strong>Settings → Users</strong> — Model: res.users. Open the form to set Access Rights and companies.'}},
      {type:'concept',title:{ar:'بطاقة المستخدم على الشاشة',en:'User form on screen'},content:{ar:'1) Name + Login/Email + كلمة المرور.\\n2) تبويب Access Rights: مستويات لكل تطبيق (Sales User / Sales Administrator، Inventory، Accounting…).\\n3) Allowed Companies و Default Company في Multi-company.\\n4) Preferences: لغة ومنطقة زمنية.\\n5) Administrator للنظام (Settings) أخطر من Administrator لمبيعات فقط.\\n6) بعد الحفظ: ادخل بحساب المستخدم واختبر القائمة والزر.',en:'1) Name + Login/Email + password.\\n2) Access Rights tab: levels per app (Sales User / Sales Administrator, Inventory, Accounting…).\\n3) Allowed Companies and Default Company in multi-company.\\n4) Preferences: language and timezone.\\n5) System Administration (Settings) is more dangerous than Sales Administrator only.\\n6) After save: log in as that user and test menus and buttons.'}},
      {type:'concept',title:{ar:'الطبقتان التقنيتان',en:'The two technical layers'},content:{ar:'Access Rights (ir.model.access): Read/Write/Create/Unlink على Model مثل sale.order.\nRecord Rules (ir.rule): Domain يقيّد الصفوف مثل user_id = المستخدم الحالي أو قيود company_id.\nالمسار التقني (Developer Mode): Settings → Technical → Security → Access Rights / Record Rules.\nالمجموعات: Settings → Users and Companies → Groups — Implied groups تورّث صلاحيات.',en:'Access Rights (ir.model.access): Read/Write/Create/Unlink on a Model such as sale.order.\nRecord Rules (ir.rule): Domain limits rows such as user_id = current user or company_id rules.\nTechnical path (Developer Mode): Settings → Technical → Security → Access Rights / Record Rules.\nGroups: Settings → Users and Companies → Groups — implied groups inherit rights.'}},
      {type:'example',title:{ar:'سيناريو مندوب',en:'Salesperson scenario'},content:{ar:'مستخدم sales.user: Sales=User، بلا Settings، شركة واحدة. يستطيع New Quotation و Confirm حسب الإعداد، ولا يفتح قيود النظام، وقد تُخفى التكلفة groups على الحقل standard_price.',en:'User sales.user: Sales=User, no Settings, one company. Can New Quotation and Confirm per setup, cannot open system config, and cost may be hidden via groups on standard_price.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'أنشئ مستخدماً تجريبياً بصلاحية Sales User فقط. اخرج من Admin وادخل به. هل Settings ظاهرة؟ هل Apps كاملة؟ سجّل ملاحظاتك.',en:'Create a trial user with Sales User only. Log out of Admin and in as them. Is Settings visible? Are all Apps visible? Note your findings.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'Least Privilege: أقل مجموعة كافية. واختبر بعد كل تغيير بمستخدم الدور وليس Admin.',en:'Least Privilege: the smallest sufficient group set. After every change test as the role user, not Admin.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'منح Administration / Settings لكل موظف «لتسهيل الشغل» — توسّع أمني خطير. أو نسيان Allowed Companies فيظهر أن «البيانات اختفت».',en:'Giving Administration / Settings to every employee “to make work easy” — serious security sprawl. Or forgetting Allowed Companies so data seems “missing”.'}}
    ],
    knowledgeCheck:{question:{ar:'Record Rules تتحكم في؟',en:'Record Rules control?'},options:{ar:['لون الواجهة فقط','أي صفوف/سجلات مسموحة (Domain)','تثبيت Apps فقط','حذف قاعدة البيانات'],en:['UI color only','Which rows/records are allowed (Domain)','Installing Apps only','Deleting the database']},answer:1,explanation:{ar:'القواعد تقيّد السجلات بـ Domain.',en:'Rules restrict records by Domain.'}}},
  
  {id:'fundamentals-05',path:'fundamentals',order:5,title:{ar:'التنقل في أودو',en:'Navigation'},description:{ar:'التنقل بكفاءة بين القوائم والسجلات',en:'Navigate efficiently between menus and records'},duration:10,xp:20,
    objectives:{ar:['الانتقال من القائمة إلى النموذج','استخدام الأزرار الذكية','العودة بسرعة'],en:['Go from list to form','Use smart buttons','Return quickly']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'التنقل في أودو يتبع نمطاً ثابتاً: قائمة (List) → نموذج (Form) → إجراءات وأزرار ذكية. إتقان هذا النمط يغني عن حفظ مسارات معقدة.',en:'Navigation in Odoo follows a fixed pattern: List → Form → actions and smart buttons. Mastering this pattern removes the need to memorize complex paths.'}},
      {type:'visual',title:{ar:'من القائمة إلى النموذج',en:'From list to form'},content:{ar:'القائمة تعرض عدة سجلات في صفوف. النقر على سطر يفتح النموذج بتفاصيل ذلك السجل. هذا النمط يتكرر في Sales و Inventory و CRM.',en:'The list shows many records in rows. Clicking a row opens the form with that record’s details. This pattern repeats in Sales, Inventory and CRM.'},image:'list-view.png',caption:{ar:'<strong>List View</strong> — صفوف للسجلات. انقر صفاً لفتح النموذج (Form).',en:'<strong>List View</strong> — rows of records. Click a row to open the form.'}},
      {type:'concept',title:{ar:'خطوات تنقل يومية',en:'Daily navigation steps'},content:{ar:'1) افتح التطبيق من الشاشة الرئيسية.\n2) اختر القائمة (مثل Quotations أو Receipts).\n3) استخدم البحث أو الفلاتر لتضييق النتائج.\n4) انقر السجل لفتح النموذج.\n5) نفّذ الإجراء (Confirm، Validate، Send…) من الشريط العلوي أو الأزرار الذكية.',en:'1) Open the app from the home screen.\n2) Choose the menu (e.g. Quotations or Receipts).\n3) Use search or filters to narrow results.\n4) Click the record to open the form.\n5) Run the action (Confirm, Validate, Send…) from the top bar or smart buttons.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'من أمر بيع مؤكد تظهر أزرار ذكية: Delivery، Invoice. الضغط عليها ينقلك مباشرة للعملية المرتبطة دون البحث في القوائم.',en:'From a confirmed sales order, smart buttons appear: Delivery, Invoice. Clicking them takes you straight to the linked operation without searching menus.'}},
      {type:'why',title:{ar:'لماذا جهات الاتصال مركزية؟',en:'Why are contacts central?'},content:{ar:'كل عملية بيع أو شراء تبدأ باختيار Partner. بطاقة واحدة تخدم العميل والمورد وتظهر في كل الشاشات اللاحقة.',en:'Every sales or purchase flow starts by picking a Partner. One card serves customer and vendor and appears on later screens.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'Contacts → New → Company. أدخل اسماً تجريبياً والعنوان. Save ثم ابحث عنه من القائمة.',en:'Contacts → New → Company. Enter a trial name and address. Save then find it from the list.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'breadcrumb أعلى النموذج يساعدك على معرفة أين أنت والعودة خطوة للخلف. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'The breadcrumb at the top of the form helps you know where you are and go one step back. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'البحث اليدوي الطويل بدل استخدام الفلاتر والمفضلات — يضيع الوقت يومياً. راجعه على الشاشة قبل الانتقال.',en:'Long manual searching instead of filters and favorites — wastes time every day. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'من شاشة List، كيف تفتح Form لسجل واحد؟',en:'From the List screen, how do you open Form for one record?'},options:{ar:['من الإعدادات فقط','النقر على السطر','حذف السطر','تصدير فقط'],en:['From settings only','Click the row','Delete the row','Export only']},answer:1,explanation:{ar:'النقر على السطر يفتح Form View. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Clicking the row opens Form View. Review the lesson screen to lock in the idea.'}}},
  
  {id:'fundamentals-06',path:'fundamentals',order:6,title:{ar:'السجلات والنماذج',en:'Records and Models'},description:{ar:'Model و Fields و Relations من Form إلى قاعدة البيانات',en:'Model, Fields and Relations from Form to database'},duration:16,xp:30,
    objectives:{ar:['ربط الشاشة بالـ Model','تمييز Many2one و One2many','فهم state والحفظ','قراءة الاسم التقني للحقل'],en:['Link the screen to the Model','Distinguish Many2one and One2many','Understand state and save','Read a field technical name']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'كل شاشة تعمل على Model: res.partner، sale.order، stock.picking، account.move… السجل = صف. الحقل = عمود + نوع. العلاقات تربط النماذج ببعضها على الشاشة كحقول قائمة منسدلة أو جداول بنود.',en:'Every screen works on a Model: res.partner, sale.order, stock.picking, account.move… A record is a row. A field is a column plus a type. Relations link models on screen as dropdowns or line tables.'}},
      {type:'why',title:{ar:'لماذا الأسماء التقنية؟',en:'Why technical names?'},content:{ar:'الدعم، Studio، التقارير، والتكامل API تستخدم الأسماء التقنية لا الترجمة العربية فقط. معرفة partner_id أسرع من وصف «حقل العميل» عند التصحيح.',en:'Support, Studio, reporting and API integrations use technical names, not only the Arabic label. Knowing partner_id is faster than describing “the customer field” when debugging.'}},
      {type:'visual',title:{ar:'النموذج = رأس + بنود',en:'Form = header + lines'},content:{ar:'عرض السعر: رأس (عميل، تاريخ) + جدول order_line. هذا One2many من sale.order إلى sale.order.line.',en:'Quotation: header (customer, date) + order_line table. That is a One2many from sale.order to sale.order.line.'},image:'quotation-form.png',caption:{ar:'<strong>sale.order Form</strong> — partner_id (Many2one) + order_line (One2many).',en:'<strong>sale.order Form</strong> — partner_id (Many2one) + order_line (One2many).'}},
      {type:'concept',title:{ar:'أنواع الحقول التي تراها يومياً',en:'Field types you see daily'},content:{ar:'Char/Text: أسماء وملاحظات.\\nMany2one: قائمة منسدلة لسجل آخر (partner_id → res.partner).\\nOne2many/Many2many: جداول أو علامات متعددة.\\nMonetary: مبالغ مع العملة.\\nSelection: state مثل draft/sale.\\nBoolean: خانات تفعيل.\\nComputed: قيمة تُحسب (قد تُخزَّن store=True) — لا تُكتب يدوياً إن كانت للقراءة.\\nOnchange: عند تغيير حقل تُحدَّث حقول أخرى على الشاشة قبل الحفظ.',en:'Char/Text: names and notes.\\nMany2one: dropdown to another record (partner_id → res.partner).\\nOne2many/Many2many: tables or multi tags.\\nMonetary: amounts with currency.\\nSelection: state such as draft/sale.\\nBoolean: toggles.\\nComputed: calculated value (may be stored) — do not type over read-only computes.\\nOnchange: changing a field updates others on screen before save.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'على sale.order: partner_id يختار العميل؛ عند اختياره قد يُملأ العنوان و pricelist عبر onchange. order_line تضيف منتج product_id وكمية price_unit.',en:'On sale.order: partner_id selects the customer; on change, address and pricelist may fill via onchange. order_line adds product_id and quantity price_unit.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'Developer Mode: افتح أي Form، مرّر على ثلاثة حقول وسجّل: الاسم الظاهر، الاسم التقني، هل Many2one أم رقم؟',en:'Developer Mode: open any Form, inspect three fields and note: label, technical name, Many2one or number?'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'الحقل الإلزامي يمنع Save — اقرأه قبل افتراض «النظام معطل».',en:'A required field blocks Save — read it before assuming “the system is broken”.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'محاولة تعديل حقل محسوب يدوياً، أو حذف بند من جدول دون فهم أنه سجل فرعي مرتبط.',en:'Trying to overwrite a computed field manually, or deleting a line without realizing it is a related child record.'}}
    ],
    knowledgeCheck:{question:{ar:'partner_id على أمر البيع عادة من نوع؟',en:'partner_id on a sales order is usually of type?'},options:{ar:['One2many','Many2one إلى res.partner','Binary فقط','HTML'],en:['One2many','Many2one to res.partner','Binary only','HTML']},answer:1,explanation:{ar:'عميل واحد لكل أمر: Many2one.',en:'One customer per order: Many2one.'}}},
  
  {id:'fundamentals-07',path:'fundamentals',order:7,title:{ar:'البحث والفلاتر',en:'Search and Filters'},description:{ar:'أدوات البحث المتقدمة',en:'Advanced search tools'},duration:10,xp:20,
    objectives:{ar:['البحث النصي','تطبيق الفلاتر','حفظ البحث','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Text search','Apply filters','Save searches','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'في أودو، كل قائمة تقريبًا تحتوي شريط بحث في الأعلى. منه تبحث بالنص، تطبّق فلاتر جاهزة، تجمّع النتائج (Group By)، وتحفظ البحث كمفضلة.',en:'In Odoo almost every list has a search bar at the top. From it you search by text, apply ready filters, group results (Group By), and save the search as a Favorite.'}},
      {type:'visual',title:{ar:'الفلاتر في أودو',en:'Filters in Odoo'},content:{ar:'قائمة Filters تضيّق النتائج بشروط جاهزة أو مخصصة. استخدمها بدل التمرير الطويل في القوائم الكبيرة.',en:'Filters menu narrows results with ready or custom conditions. Use it instead of long scrolling in large lists.'},image:'search-filters.png',caption:{ar:'<strong>Filters</strong> — اضغط أيقونة التصفية لاختيار شروط جاهزة أو بناء فلتر مخصص.',en:'<strong>Filters</strong> — click the filter icon to pick ready conditions or build a custom filter.'}},
      {type:'visual',title:{ar:'المفضلات (Favorites)',en:'Favorites'},content:{ar:'احفظ البحث المتكرر كـ Favorite للوصول بنقرة لاحقاً — مفيد لتقارير يومية مثل «عروض هذا الأسبوع».',en:'Save a frequent search as a Favorite for one-click access later — useful for daily views like “this week’s quotes”.'},image:'search-favorites.png',caption:{ar:'<strong>Favorites</strong> — احفظ البحث المتكرر كـ Favorite للوصول إليه بنقرة واحدة لاحقاً.',en:'<strong>Favorites</strong> — save a frequent search as a Favorite for one-click access later.'}},
      {type:'visual',title:{ar:'التجميع (Group By)',en:'Group By'},content:{ar:'Group By يجمع السجلات حسب حقل (مرحلة، مسؤول، عميل) لترى الصورة الإجمالية بسرعة من نفس القائمة.',en:'Group By groups records by a field (stage, salesperson, customer) so you see the big picture quickly from the same list.'},image:'search-groupby.png',caption:{ar:'<strong>Group By</strong> — جمّع السجلات حسب مرحلة، مسؤول، أو أي حقل لتحليل أسرع.',en:'<strong>Group By</strong> — group records by stage, salesperson, or any field for faster analysis.'}},
      {type:'concept',title:{ar:'خطوات عملية',en:'Practical steps'},content:{ar:'على شاشة أي قائمة:\n1) شريط البحث أعلى الصفحة — اكتب اسم عميل أو رقم.\n2) Filters: شروط جاهزة (مثل My Quotations) أو Add Custom Filter.\n3) Group By: مرحلة، مسؤول، عميل — لرؤية التجميع.\n4) Favorites → Save current search لاستخدامه يومياً بنقرة.\n5) انقر السطر دائماً لفتح Form عند الحاجة للتعديل.',en:'On any list screen:\n1) Search bar at the top — type a customer name or number.\n2) Filters: ready filters (e.g. My Quotations) or Add Custom Filter.\n3) Group By: stage, salesperson, customer — to see aggregates.\n4) Favorites → Save current search for one-click daily use.\n5) Always click the row to open Form when you need to edit.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'تريد عروض هذا الأسبوع للمسؤول أحمد: Filter بالتاريخ + Group By Salesperson أو Favorite محفوظ — بدل تصفح القائمة كاملة كل يوم.',en:'You want this week’s quotes for salesperson Ahmad: Filter by date + Group By Salesperson or a saved Favorite — instead of browsing the full list every day.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'1) من قائمة العروض أو الفرص افتح Filters.\n2) طبّق فلتراً جاهزاً ثم أزله.\n3) إن أمكن احفظ البحث كـ Favorite.\nالهدف: تقليل التمرير اليدوي الطويل.',en:'1) From quotations or opportunities open Filters.\n2) Apply a ready filter then clear it.\n3) If possible save the search as a Favorite.\nGoal: reduce long manual scrolling.'}},
      {type:'why',title:{ar:'لماذا البحث والفلاتر؟',en:'Why search and filters?'},content:{ar:'القوائم تطول بسرعة. Filters و Favorites يختصران دقائق كل يوم ويقلّلان أخطاء اختيار السجل الخاطئ.',en:'Lists grow quickly. Filters and Favorites save minutes every day and reduce picking the wrong record.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا ظهرت نتائج غريبة، تحقق من الفلاتر النشطة أعلى القائمة وأزل ما لا تحتاجه. راجعه على الشاشة قبل الانتقال.',en:'If results look wrong, check the active filters above the list and clear what you do not need. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك فلتر قديم مفعّلًا دون ملاحظة — فيبدو أن البيانات ناقصة. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Leaving an old filter on without noticing — data looks incomplete. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'على شاشة القائمة، ما فائدة حفظ البحث كـ Favorite؟',en:'On the list screen, what is saving a search as Favorite for?'},options:{ar:['حذف سجلات','حفظ عمليات البحث المتكررة','تغيير اللون','إنشاء مستخدمين'],en:['Delete records','Save frequent searches','Change color','Create users']},answer:1,explanation:{ar:'Favorites تحفظ الفلاتر للاستخدام لاحقًا.',en:'Favorites save filters for later reuse.'}}},
  {id:'fundamentals-08',path:'fundamentals',order:8,title:{ar:'عروض Kanban والقائمة والنموذج',en:'Kanban, List and Form Views'},description:{ar:'view_mode وكيف تختار العرض المناسب للعمل',en:'view_mode and choosing the right view for the job'},duration:14,xp:25,
    objectives:{ar:['متى List ومتى Kanban ومتى Form','فهم Statusbar و Smart Buttons','ربط Graph/Pivot بالتحليل'],en:['When List vs Kanban vs Form','Understand statusbar and smart buttons','Link Graph/Pivot to analysis']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'نفس الـ Model يمكن أن يُعرض List للمسح، Kanban للمراحل، Form للتفاصيل، Graph/Pivot للتحليل. الاختيار من Control Panel لا يغيّر البيانات — يغيّر زاوية النظر.',en:'The same Model can show as List for scanning, Kanban for stages, Form for details, Graph/Pivot for analysis. Switching in the Control Panel does not change data — it changes the angle of view.'}},
      {type:'visual',title:{ar:'Kanban المراحل',en:'Stage Kanban'},content:{ar:'CRM Pipeline: أعمدة = stages، بطاقة = فرصة. السحب يكتب stage_id. راقب الأنشطة على البطاقة.',en:'CRM Pipeline: columns = stages, card = opportunity. Drag writes stage_id. Watch activities on the card.'},image:'pipeline-kanban.png',caption:{ar:'<strong>Kanban</strong> — مثالي لـ CRM ومشاريع بمراحل. تقنياً غالباً stage_id.',en:'<strong>Kanban</strong> — ideal for CRM and staged projects. Technically often stage_id.'}},
      {type:'concept',title:{ar:'متى تستخدم ماذا؟',en:'When to use what?'},content:{ar:'List: بحث، تصدير، إجراءات جماعية، مقارنة أعمدة.\\nKanban: تدفق مراحل، سحب وإفلات، نظرة فريق.\\nForm: إنشاء، تأكيد، بنود، Chatter.\\nGraph/Pivot: أداء مبيعات، مخزون، فواتير — بعد أن تكون البيانات صحيحة.\\nSearch View يغذي الجميع: Filters و Group By و Favorites.',en:'List: search, export, mass actions, compare columns.\\nKanban: stage flow, drag and drop, team overview.\\nForm: create, confirm, lines, chatter.\\nGraph/Pivot: sales, stock, invoices performance — after data is correct.\\nSearch View feeds all: Filters, Group By, Favorites.'}},
      {type:'visual',title:{ar:'Form مع الحالة',en:'Form with status'},content:{ar:'Statusbar يعرض state. الأزرار تستدعي methods مثل action_confirm. Smart Buttons = إحصاء وعبر إلى نماذج أخرى.',en:'Statusbar shows state. Buttons call methods such as action_confirm. Smart buttons = counts and jump to other models.'},image:'sales-order.png',caption:{ar:'<strong>Form + Status + Smart Buttons</strong> — قلب التشغيل اليومي بعد اختيار السجل من List/Kanban.',en:'<strong>Form + Status + Smart Buttons</strong> — daily operations core after picking a record from List/Kanban.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مدير مبيعات يبدأ يومه Kanban للفرص، يفتح Form لفرصة، ينشئ Quotation من الزر، ثم List لمراجعة كل العروض المفتوحة بفلتر.',en:'A sales manager starts the day on opportunity Kanban, opens a Form, creates a Quotation from a button, then uses List to review all open quotes with a filter.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على نفس قائمة العروض: بدّل List ↔ Kanban إن وُجد، ثم افتح Form. لاحظ أن السجل هو نفسه والـ view_mode فقط تغيّر.',en:'On the same quotations menu: switch List ↔ Kanban if available, then open Form. Notice the record is the same; only view_mode changed.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تُدر التحليلات Graph قبل ضبط Filters — رقم جميل بفلتر خاطئ أخطر من لا رقم.',en:'Do not present Graph analytics before fixing Filters — a pretty number with a wrong filter is worse than no number.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إدارة كل شيء من Kanban فقط دون فتح Form للبنود والحقول الإلزامية — نقص بيانات وتأكيدات ناقصة.',en:'Managing everything from Kanban only without opening Form for lines and required fields — missing data and incomplete confirms.'}}
    ],
    knowledgeCheck:{question:{ar:'تبديل List إلى Kanban يغيّر؟',en:'Switching List to Kanban changes?'},options:{ar:['يحذف السجلات','زاوية العرض (view_mode) لا البيانات نفسها','العملة فقط','المستخدم'],en:['Deletes records','View angle (view_mode), not the data itself','Currency only','The user']},answer:1,explanation:{ar:'نفس الـ Model بس عرض مختلف.',en:'Same Model, different view.'}}},
  
  {id:'fundamentals-09',path:'fundamentals',order:9,title:{ar:'الإعدادات الأساسية',en:'Basic Configuration'},description:{ar:'أهم الإعدادات الأولية للشركة',en:'Key initial company settings'},duration:12,xp:20,
    objectives:{ar:['ضبط بيانات الشركة','اللغة والعملة','مراجعة المستخدمين','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Set company data','Language and currency','Review users','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'قبل إدخال بيانات كثيرة اضبط الإعدادات الأساسية: الشركة، العملة، اللغة، الضرائب. التغيير لاحقاً بعد فواتير كثيرة أصعب وأكثر خطراً.',en:'Before entering a lot of data, set basic configuration: company, currency, language, taxes. Changing later after many invoices is harder and riskier.'}},
      {type:'why',title:{ar:'لماذا الإعداد أولاً؟',en:'Why configure first?'},content:{ar:'العملة والضرائب والشركة تظهر على كل فاتورة وتقرير. ضبطها مبكراً يمنع إعادة العمل والأخطاء المحاسبية.',en:'Currency, taxes and company appear on every invoice and report. Setting them early prevents rework and accounting errors.'}},
      {type:'visual',title:{ar:'شاشات الإعدادات',en:'Settings screens'},content:{ar:'Form View يعرض سجلاً واحداً: حقول، تبويبات، وشريط علوي فيه Save والإجراءات (Confirm، Send…). احفظ دائماً قبل مغادرة الشاشة حتى لا تُفقد التعديلات.',en:'Form View shows one record: fields, tabs, and a top bar with Save and actions (Confirm, Send…). Always save before leaving the screen so edits are not lost.'},image:'form-view.png',caption:{ar:'<strong>Settings Form</strong> — الإعدادات تُعدَّل بنفس نمط النماذج: حقول ثم حفظ.',en:'<strong>Settings Form</strong> — configuration uses the same form pattern: fields then Save.'}},
      {type:'concept',title:{ar:'خطوات الإعداد الأولي',en:'Initial setup steps'},content:{ar:'1) Settings → Companies → عدّل اسم الشركة والعنوان والشعار.\n2) Settings → Languages / Currencies حسب السوق.\n3) من Invoicing أو Accounting اضبط الضرائب إن لزم.\n4) راجع Users والصلاحيات.\n5) لا تغيّر عملة الشركة بعد إدخال فواتير كثيرة.',en:'1) Settings → Companies → edit company name, address and logo.\n2) Settings → Languages / Currencies for your market.\n3) From Invoicing or Accounting set taxes if needed.\n4) Review Users and access rights.\n5) Do not change company currency after many invoices.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'شركة في السعودية: العملة SAR، الضريبة 15%، اللغة العربية والإنجليزية. تُضبط مرة في البداية وتظهر تلقائياً على العروض والفواتير.',en:'A company in Saudi Arabia: currency SAR, tax 15%, Arabic and English. Set once at the start and they appear automatically on quotes and invoices.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح أي نموذج (عميل أو منتج) وحاول الحفظ مع ترك حقل إلزامي فارغاً. اقرأ رسالة الخطأ على الشاشة ثم أكمل الحقل.',en:'Open any form (customer or product) and try saving with a required field empty. Read the on-screen error then complete the field.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'Developer Mode فقط عند الحاجة للتطوير ثم أوقفه حتى لا تظهر خيارات تربك المستخدمين. راجعه على الشاشة قبل الانتقال.',en:'Developer Mode only when needed for development, then turn it off so users are not confused by extra options. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تغيير إعدادات حرجة بعد بيانات كثيرة دون نسخ احتياطي. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Changing critical settings after lots of data without a backup. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'من أي شاشة/قائمة تضبط عادة بيانات الشركة والعملة؟',en:'From which screen/menu do you usually set company and currency?'},options:{ar:['المبيعات فقط','Settings','المخزون','لا يمكن'],en:['Sales only','Settings','Inventory','Cannot']},answer:1,explanation:{ar:'معظم الإعدادات في Settings. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Most settings are in Settings. Review the lesson screen to lock in the idea.'}}},
  
  {id:'fundamentals-10',path:'fundamentals',order:10,title:{ar:'ملخص الأساسيات وخريطة الشاشات',en:'Fundamentals Summary & Screen Map'},description:{ar:'ربط كل شاشات الأساس قبل الانتقال للمسارات المتقدمة',en:'Connect all foundation screens before advanced paths'},duration:12,xp:25,
    objectives:{ar:['تلخيص شاشات الأساس','بناء عادة List→Form','الاستعداد للمبيعات والمخزون'],en:['Summarize foundation screens','Build List→Form habit','Prepare for sales and inventory']},
    sections:[
      {type:'intro',title:{ar:'ماذا أتقنت؟',en:'What did you master?'},content:{ar:'الأساسيات ليست نظرية فقط: هي عادات شاشة. Apps، المستخدم والصلاحيات، Contact، List و Form، البحث والفلاتر، والحقول الإلزامية. كل تطبيق لاحق يعيد استخدام نفس العادات.',en:'Fundamentals are not theory only: they are screen habits. Apps, users and rights, Contact, List and Form, search and filters, and required fields. Every later app reuses the same habits.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) Apps — نقطة الدخول لكل تطبيق.\\n2) Settings → Users — Access Rights.\\n3) Contacts — Partner للعميل والمورد.\\n4) أي قائمة: بحث → Filters → Group By → Favorite.\\n5) List للمسح، Form للتعديل، Save دائماً.\\n6) الحقل الأحمر/الإلزامي يمنع الحفظ حتى يُملأ.\\nاحفظ هذه الخريطة قبل فتح Sales أو Inventory.',en:'1) Apps — entry point for every app.\\n2) Settings → Users — Access Rights.\\n3) Contacts — Partner for customer and vendor.\\n4) Any list: search → Filters → Group By → Favorite.\\n5) List to scan, Form to edit, always Save.\\n6) Required field blocks save until filled.\\nKeep this map before opening Sales or Inventory.'}},
      {type:'visual',title:{ar:'التذكير البصري',en:'Visual reminder'},content:{ar:'شبكة التطبيقات بعد الدخول هي بوصلتك. كل أيقونة = تطبيق بشاشاته. لا تثبّت كل شيء دفعة واحدة.',en:'The apps grid after login is your compass. Each icon = an app with its screens. Do not install everything at once.'},image:'apps-menu.png',caption:{ar:'<strong>Apps</strong> — ابدأ من هنا دائماً. الأساسيات تعلّمك كيف تتنقل قبل ماذا تبيع.',en:'<strong>Apps</strong> — always start here. Fundamentals teach how to navigate before what to sell.'}},
      {type:'example',title:{ar:'سيناريو ربط',en:'Linking scenario'},content:{ar:'موظف جديد: تنشئ User + مجموعات، ثم Contact للعميل، ثم من Sales تفتح List عروض وتستخدم Filter. نفس العادات بلا شاشات جديدة غريبة.',en:'New hire: you create User + groups, then a customer Contact, then from Sales open quotations List and use Filter. Same habits without strange new screens.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'راجع في أودو تجريبي: Apps → Contacts → List/Form → شريط البحث. كرّر التنقل 3 مرات حتى يصبح لاإرادياً.',en:'In trial Odoo review: Apps → Contacts → List/Form → search bar. Repeat navigation 3 times until it becomes automatic.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا ضعت في أي تطبيق لاحق: ارجع لعادات List و Form والبحث — 90٪ من أودو يُحل بهذه الثلاثة.',en:'If you get lost in any later app: return to List, Form and search habits — 90% of Odoo is solved with these three.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'القفز للمبيعات بلا إتقان الحفظ والصلاحيات — تظهر أخطاء «Access Error» وتعديلات ضائعة.',en:'Jumping to sales without mastering save and access rights — Access Error messages and lost edits appear.'}}
    ],
    knowledgeCheck:{question:{ar:'العادة الأساسية للتنقل على شاشات أودو؟',en:'Core navigation habit on Odoo screens?'},options:{ar:['Excel فقط','List للمسح و Form للتعديل مع Save','حذف كل السجلات','تجاهل البحث'],en:['Excel only','List to scan and Form to edit with Save','Delete all records','Ignore search']},answer:1,explanation:{ar:'List و Form و Save أساس كل تطبيق.',en:'List, Form and Save are the base of every app.'}}},
  
  {id:'sales-01',path:'sales',order:1,title:{ar:'نظرة عامة على إدارة العملاء',en:'CRM Overview'},description:{ar:'ما هو CRM في أودو',en:'What is CRM in Odoo'},duration:10,xp:20,
    objectives:{ar:['دور CRM','مراحل الخط','Lead vs Opportunity','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['CRM role','Pipeline stages','Lead vs Opportunity','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق CRM في أودو يتتبع العميل من أول اهتمام حتى إغلاق الصفقة، ثم يرتبط مباشرة بعروض الأسعار وأوامر البيع والفواتير.',en:'The CRM app in Odoo tracks the customer from first interest to closed deal, then links directly to quotations, sales orders and invoices.'}},
      {type:'visual',title:{ar:'لوحة CRM',en:'CRM dashboard'},content:{ar:'لوحة CRM تلخّص الفرص المفتوحة والأنشطة القادمة. ابدأ يومك من هنا ثم انتقل إلى Pipeline Kanban للتفاصيل.',en:'The CRM dashboard summarizes open opportunities and upcoming activities. Start your day here then move to Pipeline Kanban for details.'},image:'crm-dashboard.png',caption:{ar:'<strong>لوحة CRM</strong> — ملخص الفرص والأنشطة. نقطة انطلاق يومية لفريق المبيعات.',en:'<strong>CRM dashboard</strong> — summary of opportunities and activities. Daily starting point for the sales team.'}},
      {type:'visual',title:{ar:'خط الأنابيب (Kanban)',en:'Pipeline (Kanban)'},content:{ar:'Pipeline Kanban: أعمدة المراحل وبطاقات الفرص. اسحب البطاقة عند كل تقدم (اتصال، عرض سعر، فوز) حتى يبقى الخط مرآة للواقع.',en:'Pipeline Kanban: stage columns and opportunity cards. Drag the card on every advance (call, quote, win) so the pipeline mirrors reality.'},image:'pipeline-kanban.png',caption:{ar:'<strong>Pipeline (Kanban)</strong> — أعمدة المراحل. اسحب البطاقة بين الأعمدة مع تقدّم الصفقة.',en:'<strong>Pipeline (Kanban)</strong> — stage columns. Drag the card between columns as the deal progresses.'}},
      {type:'concept',title:{ar:'المسار الأساسي',en:'Core flow'},content:{ar:'المسار على الشاشات:\n1) CRM → Leads → New.\n2) تأهيل الاحتياج والميزانية.\n3) Convert to Opportunity → بطاقة في Pipeline Kanban.\n4) حدّث Stage و Expected Revenue بعد كل تفاعل.\n5) Won: أنشئ Quotation من الفرصة أو من Sales.\n6) Lost: سجّل سبب الخسارة من الشاشة.',en:'Flow on screens:\n1) CRM → Leads → New.\n2) Qualify need and budget.\n3) Convert to Opportunity → card on Pipeline Kanban.\n4) Update Stage and Expected Revenue after every interaction.\n5) Won: create Quotation from the opportunity or Sales.\n6) Lost: record the loss reason from the screen.'}},
      {type:'concept',title:{ar:'خطوات في أودو',en:'Steps in Odoo'},content:{ar:'1) افتح تطبيق CRM.\n2) راجع Pipeline (Kanban).\n3) أنشئ Lead أو Opportunity.\n4) حدّث المرحلة بعد كل تفاعل.\n5) عند الفوز: أنشئ Quotation من الفرصة.',en:'1) Open the CRM app.\n2) Review Pipeline (Kanban).\n3) Create a Lead or Opportunity.\n4) Update the stage after every interaction.\n5) On win: create a Quotation from the opportunity.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'استفسار من موقع → Lead → تأهيل → Opportunity في مرحلة Qualified → عند الفوز New Quotation من بطاقة الفرصة.',en:'Website inquiry → Lead → qualify → Opportunity in Qualified → on win New Quotation from the opportunity form.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح CRM → Pipeline. حدّد: أعمدة المراحل، البطاقات، وزر New. لا تُنشئ بيانات حقيقية في الإنتاج دون إذن.',en:'Open CRM → Pipeline. Identify: stage columns, cards, and the New button. Do not create real data in production without permission.'}},
      {type:'why',title:{ar:'لماذا CRM قبل الفاتورة؟',en:'Why CRM before the invoice?'},content:{ar:'لأن الفرصة ترتّب المتابعة قبل أن يتحول الحديث إلى عرض سعر ثم أمر بيع. بدون CRM تضيع المتابعات بين الإيميلات.',en:'Because the opportunity organizes follow-up before talk becomes a quotation then a sales order. Without CRM, follow-ups get lost in email.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اجعل تحديث المرحلة عادة يومية — الخط يصبح مرآة للواقع. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Make stage updates a daily habit — the pipeline becomes a mirror of reality. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك كل شيء كـ Lead دون تحويل المؤهلين — يضيع التوقع. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Keeping everything as Lead without converting qualified ones — forecasts are lost. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'على شاشات CRM، Lead غير مؤهل بينما Opportunity؟',en:'On CRM screens, a Lead is unqualified while an Opportunity is?'},options:{ar:['لا فرق','Lead غير مؤهل، Opportunity مؤهلة ولها قيمة','Opportunity قبل Lead','Lead للفواتير'],en:['No difference','Lead unqualified; Opportunity qualified with value','Opportunity before Lead','Lead for invoices']},answer:1,explanation:{ar:'Lead غير مؤهل. Opportunity مؤهلة في الخط.',en:'Lead is unqualified. Opportunity is qualified in the pipeline.'}}},
  {id:'sales-02',path:'sales',order:2,title:{ar:'العملاء المحتملون (Leads)',en:'Leads'},description:{ar:'إدارة وتأهيل العملاء المحتملين',en:'Managing and qualifying leads'},duration:12,xp:20,
    objectives:{ar:['إنشاء Lead','تأهيل وتحويل إلى Opportunity','معرفة متى تُستخدم Leads','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create a Lead','Qualify and convert to Opportunity','Know when to use Leads','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'Lead هو اهتمام أولي لم يُؤهَّل بعد: نموذج ويب، مكالمة، معرض. الهدف: جمع البيانات وتقرير هل يستحق المتابعة كفرصة (Opportunity).',en:'A Lead is early interest not yet qualified: web form, call, exhibition. Goal: collect data and decide if it deserves follow-up as an Opportunity.'}},
      {type:'why',title:{ar:'لماذا الفصل بين Lead و Opportunity؟',en:'Why separate Lead and Opportunity?'},content:{ar:'يفصل الضجيج عن الفرص الحقيقية. التقارير والتوقع يعتمدان على Opportunities المؤهلة فقط.',en:'It separates noise from real deals. Reports and forecasts rely on qualified Opportunities only.'}},
      {type:'visual',title:{ar:'إنشاء وتحويل الفرص',en:'Create and convert'},content:{ar:'إنشاء فرصة من Pipeline (New) أو بتحويل Lead مؤهل. املأ العميل والإيراد المتوقع ثم احفظ.',en:'Create an opportunity from Pipeline (New) or by converting a qualified Lead. Fill customer and expected revenue then save.'},image:'create-opportunities.png',caption:{ar:'<strong>تحويل Lead → Opportunity</strong> — بعد التأهيل حوّل العميل المحتمل إلى فرصة في الخط.',en:'<strong>Convert Lead → Opportunity</strong> — after qualifying, convert the lead into a pipeline opportunity.'}},
      {type:'concept',title:{ar:'خطوات التعامل مع Lead',en:'Steps for handling a Lead'},content:{ar:'1) CRM → Leads → New (أو راجع الوارد).\n2) املأ الاسم، الشركة، البريد، الهاتف، المصدر.\n3) تواصل وقيّم الجدية والميزانية والحاجة.\n4) إن كان مؤهلاً: Convert to Opportunity.\n5) إن لم يكن: ضع علامة Lost أو أرشفة مع السبب.',en:'1) CRM → Leads → New (or review inbound).\n2) Fill name, company, email, phone, source.\n3) Contact and assess seriousness, budget and need.\n4) If qualified: Convert to Opportunity.\n5) If not: mark Lost or archive with a reason.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'زائر ملأ نموذج «اطلب عرضاً» على الموقع → Lead جديد. بعد مكالمة تبيّن أنه جاهز للشراء خلال شهر → تحويل إلى Opportunity بمرحلة Qualification.',en:'A visitor fills “Request a quote” on the website → new Lead. After a call it is clear they will buy within a month → convert to Opportunity at Qualification stage.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'أنشئ Lead تجريبي من CRM → Leads → New. املأ الاسم والبريد. لا تحوّله إلى Opportunity إلا إذا فهمت الفرق على الشاشة.',en:'Create a trial Lead from CRM → Leads → New. Fill name and email. Convert to Opportunity only after you understand the difference on screen.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'فعّل Leads فقط إذا كان حجم الاستفسارات كبيراً. للشركات الصغيرة يمكن العمل بـ Opportunities مباشرة.',en:'Enable Leads only if inquiry volume is high. Small teams can work with Opportunities directly.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك كل شيء كـ Lead دون تحويل المؤهلين — يضيع التوقع ويختلط الضجيج بالفرص. راجعه على الشاشة قبل الانتقال.',en:'Keeping everything as Lead without converting qualified ones — forecasts are lost and noise mixes with real deals. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'من شاشة Lead، متى تستخدم Convert to Opportunity؟',en:'From the Lead screen, when do you use Convert to Opportunity?'},options:{ar:['فوراً دائماً','بعد التأهيل والتأكد من الجدية','لا نحوّل أبداً','عند إنشاء الفاتورة فقط'],en:['Always immediately','After qualifying and confirming seriousness','Never convert','Only when creating invoice']},answer:1,explanation:{ar:'التحويل بعد التأهيل يبقي الخط نظيفاً والتوقع دقيقاً.',en:'Convert after qualifying so the pipeline stays clean and forecasts accurate.'}}},
  
  {id:'sales-03',path:'sales',order:3,title:{ar:'الفرص (Opportunities)',en:'Opportunities'},description:{ar:'إدارة الفرص ومراحل الخط',en:'Managing opportunities and stages'},duration:12,xp:20,
    objectives:{ar:['إنشاء Opportunity','تحديث المراحل','تسجيل الأنشطة','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create Opportunity','Update stages','Log activities','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الفرصة (Opportunity) هي صفقة محتملة: لها عميل، قيمة متوقعة، مرحلة في الخط، وتاريخ إغلاق. في أودو تُدار غالبًا من عرض Kanban.',en:'An Opportunity is a potential deal: customer, expected value, pipeline stage, and close date. In Odoo it is usually managed in the Kanban view.'}},
      {type:'visual',title:{ar:'خط الفرص (Pipeline Kanban)',en:'Opportunities pipeline (Kanban)'},content:{ar:'Kanban Pipeline: كل عمود مرحلة وكل بطاقة فرصة. اسحب البطاقة بين الأعمدة لتحديث المرحلة فوراً — الخط يصبح مرآة لعمل الفريق.',en:'Kanban Pipeline: each column is a stage and each card an opportunity. Drag the card between columns to update the stage immediately — the pipeline mirrors the team’s work.'},image:'pipeline-kanban.png',caption:{ar:'<strong>Pipeline Kanban</strong> — الفرص كبطاقات. اسحب بين المراحل وحدّث التوقع.',en:'<strong>Pipeline Kanban</strong> — opportunities as cards. Drag between stages and update the forecast.'}},
      {type:'visual',title:{ar:'بطاقة الفرصة',en:'Opportunity form'},content:{ar:'نموذج Opportunity يجمع الإيراد المتوقع والمرحلة والمسؤول والأنشطة التالية. حدّثه بعد كل تفاعل مع العميل.',en:'The Opportunity form gathers expected revenue, stage, salesperson and next activities. Update it after every customer interaction.'},image:'opportunity.png',caption:{ar:'<strong>Opportunity form</strong> — الإيراد المتوقع، المرحلة، المسؤول، والأنشطة التالية في مكان واحد.',en:'<strong>Opportunity form</strong> — expected revenue, stage, salesperson, and next activities in one place.'}},
      {type:'visual',title:{ar:'إنشاء فرص جديدة',en:'Creating opportunities'},content:{ar:'إنشاء فرصة من Pipeline (New) أو بتحويل Lead مؤهل. املأ العميل والإيراد المتوقع ثم احفظ.',en:'Create an opportunity from Pipeline (New) or by converting a qualified Lead. Fill customer and expected revenue then save.'},image:'create-opportunities.png',caption:{ar:'<strong>New Opportunity</strong> — من Pipeline اضغط New واملأ العميل والإيراد المتوقع.',en:'<strong>New Opportunity</strong> — from Pipeline click New and fill customer and expected revenue.'}},
      {type:'concept',title:{ar:'خطوات عملية',en:'Practical steps'},content:{ar:'1) افتح CRM. 2) أنشئ Opportunity أو حوّل Lead. 3) املأ العميل والقيمة والمرحلة. 4) حدّد Next Activity. 5) اسحب البطاقة بين المراحل مع تقدّم الصفقة.',en:'1) Open CRM. 2) Create Opportunity or convert a Lead. 3) Fill customer, value, stage. 4) Set Next Activity. 5) Drag the card across stages as the deal progresses.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'فرصة بإيراد متوقع 50,000: حدّث المرحلة بعد كل اتصال، وعند الاتفاق اضغط New Quotation من نفس بطاقة Opportunity.',en:'Opportunity with expected revenue 50,000: update the stage after every call, and when agreed click New Quotation from the same Opportunity form.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'1) افتح CRM → Pipeline (Kanban).\n2) أنشئ Opportunity تجريبية أو افتح موجودة.\n3) اسحب البطاقة لمرحلة تالية.\n4) افتح النموذج وحدّث الإيراد المتوقع ثم Save.',en:'1) Open CRM → Pipeline (Kanban).\n2) Create a trial Opportunity or open an existing one.\n3) Drag the card to the next stage.\n4) Open the form, update expected revenue then Save.'}},
      {type:'why',title:{ar:'لماذا Pipeline؟',en:'Why Pipeline?'},content:{ar:'Pipeline يعرض كل الفرص وحالاتها في نظرة واحدة. المدير والموظف يريان الاختناق في نفس الشاشة دون جداول خارجية.',en:'The pipeline shows every opportunity and its stage at a glance. Manager and rep see bottlenecks on the same screen without external spreadsheets.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'حدّث المرحلة فور أي تغيّر حقيقي مع العميل — الخط يعكس الواقع فقط إذا حدّثته. راجعه على الشاشة قبل الانتقال.',en:'Update the stage as soon as something real changes with the customer — the pipeline only reflects reality if you maintain it. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك عشرات الفرص في مرحلة واحدة أسابيع دون نشاط — يصبح الخط غير موثوق. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Leaving dozens of opportunities in one stage for weeks with no activity — the pipeline becomes unreliable. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'على بطاقة Opportunity، من الحقول الأساسية؟',en:'On the Opportunity form, key fields include?'},options:{ar:['الاسم فقط','العميل والقيمة والمرحلة والتاريخ','رقم الفاتورة','عنوان المستودع'],en:['Name only','Customer, value, stage, date','Invoice number','Warehouse address']},answer:1,explanation:{ar:'العميل والقيمة والمرحلة وتاريخ الإغلاق كحد أدنى.',en:'Customer, value, stage and expected close date at minimum.'}}},
  {id:'sales-04',path:'sales',order:4,title:{ar:'العملاء (Customers)',en:'Customers'},description:{ar:'بطاقات العملاء والشركاء',en:'Customer cards and partners'},duration:10,xp:20,
    objectives:{ar:['إنشاء عميل','فهم Partner','ربط العميل بالمبيعات','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create a customer','Understand Partner','Link customer to sales','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'في أودو العميل هو Partner (جهة اتصال/شركة) يمكن أن يكون عميلاً أو مورداً أو الاثنين. بطاقة العميل مركز لكل العروض والأوامر والفواتير.',en:'In Odoo a customer is a Partner (contact/company) that can be a customer, vendor or both. The customer card is the hub for quotes, orders and invoices.'}},
      {type:'visual',title:{ar:'قائمة العملاء',en:'Customers list'},content:{ar:'List View: صفوف للسجلات مع بحث وفلاتر. انقر صفاً لفتح Form. هذا الزوج (قائمة→نموذج) يتكرر في Sales و Purchase و Inventory.',en:'List View: rows of records with search and filters. Click a row to open Form. This pair (list→form) repeats in Sales, Purchase and Inventory.'},image:'list-view.png',caption:{ar:'<strong>Customers list</strong> — نفس نمط List View: بحث، فلاتر، ثم فتح البطاقة للتفاصيل.',en:'<strong>Customers list</strong> — same List View pattern: search, filters, then open the card for details.'}},
      {type:'concept',title:{ar:'خطوات إنشاء عميل',en:'Steps to create a customer'},content:{ar:'1) Sales → Customers → New (أو Contacts).\n2) اختر Individual أو Company.\n3) أدخل الاسم، العنوان، البريد، الهاتف، الرقم الضريبي إن لزم.\n4) في تبويب Sales و Accounting راجع قائمة الأسعار وشروط الدفع.\n5) احفظ — يصبح متاحاً في عروض الأسعار فوراً.',en:'1) Sales → Customers → New (or Contacts).\n2) Choose Individual or Company.\n3) Enter name, address, email, phone, tax ID if needed.\n4) In Sales and Accounting tabs review pricelist and payment terms.\n5) Save — available on quotations immediately.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'عميل جديد طلب عرضاً هاتفياً: أنشئ البطاقة أولاً ثم New Quotation واختره من حقل Customer — لا تكتب الاسم كنص حر.',en:'A new customer requested a quote by phone: create the card first, then New Quotation and pick them in the Customer field — do not type the name as free text.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من Pipeline افتح Opportunity. حدّد حقول: Expected Revenue، Stage، Salesperson. حدّث المرحلة بعد تخيّل مكالمة مع العميل.',en:'From Pipeline open an Opportunity. Locate fields: Expected Revenue, Stage, Salesperson. Update the stage after imagining a customer call.'}},
      {type:'why',title:{ar:'لماذا بطاقة Opportunity؟',en:'Why the Opportunity form?'},content:{ar:'تجمع الإيراد المتوقع والمرحلة والأنشطة. تحديثها بعد كل تفاعل يبقي التقارير صادقة.',en:'It gathers expected revenue, stage and activities. Updating after every interaction keeps reports honest.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'تجنّب تكرار نفس العميل بتهجئة مختلفة. ابحث قبل الإنشاء. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Avoid duplicate customers with different spelling. Search before creating. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء عميل جديد لكل عرض بدل إعادة استخدام البطاقة — تتكسر التقارير والتاريخ. راجعه على الشاشة قبل الانتقال.',en:'Creating a new customer for every quote instead of reusing the card — reports and history break. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'حقل Customer على شاشة العرض يشير إلى سجل من نوع؟',en:'The Customer field on the quotation screen points to a record of type?'},options:{ar:['فاتورة فقط','Partner يمكن أن يكون عميلاً و/أو مورداً','منتج','مستودع'],en:['Invoice only','A Partner that can be customer and/or vendor','Product','Warehouse']},answer:1,explanation:{ar:'Partner كيان مرن للعميل والمورد. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Partner is a flexible entity for customer and vendor. Review the lesson screen to lock in the idea.'}}},
  
  {id:'sales-05',path:'sales',order:5,title:{ar:'عروض الأسعار أوامر البيع',en:'Quotations and Sales Orders'},description:{ar:'sale.order من الشاشة إلى Confirm workflow',en:'sale.order from screen to Confirm workflow'},duration:18,xp:30,
    objectives:{ar:['إنشاء Quotation على الشاشة','فهم state و Confirm','قراءة partner_id و order_line','ربط الأمر بالتسليم والفاتورة'],en:['Create Quotation on screen','Understand state and Confirm','Read partner_id and order_line','Link order to delivery and invoice']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'عرض السعر وأمر البيع في أودو نفس الـ Model: sale.order. الفرق الأساسي حقل state. بعد Confirm تتحول الوثيقة إلى أمر بيع تشغيلي وتظهر Smart Buttons للتسليم والفوترة.',en:'Quotation and sales order in Odoo share the same Model: sale.order. The main difference is the state field. After Confirm the document becomes an operational sales order and smart buttons for delivery and invoicing appear.'}},
      {type:'why',title:{ar:'لماذا Model واحد؟',en:'Why one Model?'},content:{ar:'لتجنب إعادة إدخال البنود عند التأكيد. تاريخ العرض والأمر سلسلة واحدة على الشاشة وفي التقارير.',en:'To avoid re-entering lines on confirm. Quote and order history stay one chain on screen and in reports.'}},
      {type:'visual',title:{ar:'نموذج العرض',en:'Quotation form'},content:{ar:'رأس: Customer (partner_id)، التاريخ، Pricelist. دفتر البنود: product_id، quantity، price_unit، taxes. Statusbar: Draft / Sent / Sales Order.',en:'Header: Customer (partner_id), date, pricelist. Lines: product_id, quantity, price_unit, taxes. Statusbar: Draft / Sent / Sales Order.'},image:'quotation-form.png',caption:{ar:'<strong>sale.order Form</strong> — partner_id + order_line. زر Confirm يستدعي action_confirm تقريباً.',en:'<strong>sale.order Form</strong> — partner_id + order_line. Confirm roughly calls action_confirm.'}},
      {type:'concept',title:{ar:'سير العمل على الشاشة والتقنية',en:'Workflow on screen and technically'},content:{ar:'1) Sales → Orders → Quotations → New.\\n2) partner_id + أسطر order_line → Save (state غالباً draft).\\n3) Send / Confirm حسب السياسة.\\n4) Confirm: state → sale؛ يُنشأ منطق المخزون/الفوترة حسب الإعداد.\\n5) Smart Buttons: Delivery (stock.picking)، Invoice (account.move).\\n6) تقنياً: sale.order و sale.order.line؛ methods مثل action_confirm؛ قيود صلاحيات group_sale_salesman.',en:'1) Sales → Orders → Quotations → New.\\n2) partner_id + order_line lines → Save (state usually draft).\\n3) Send / Confirm per policy.\\n4) Confirm: state → sale; stock/invoice logic runs per settings.\\n5) Smart buttons: Delivery (stock.picking), Invoice (account.move).\\n6) Technically: sale.order and sale.order.line; methods such as action_confirm; rights group_sale_salesman.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'عميل ABC، منتج Laptop × 3، Confirm. الحالة Sales Order. Delivery و Create Invoice يظهران دون إعادة كتابة البنود.',en:'Customer ABC, product Laptop × 3, Confirm. Status Sales Order. Delivery and Create Invoice appear without retyping lines.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'محاكي المبيعات أو تجريبي: أنشئ عرضاً، احفظ، أكد، وسمِّ على الشاشة: Statusbar، order lines، Smart Buttons.',en:'Sales simulator or trial: create a quote, save, confirm, and name on screen: statusbar, order lines, smart buttons.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'راجع الضريبة و pricelist قبل Confirm — التصحيح بعده أصعب تشغيلياً.',en:'Review tax and pricelist before Confirm — fixing afterward is operationally harder.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء فاتورة من المحاسبة مع تجاهل أمر البيع — ينكسر التتبع من الفرصة إلى التحصيل.',en:'Creating an invoice from accounting while ignoring the sales order — tracking from opportunity to payment breaks.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد Confirm على sale.order ماذا يحدث غالباً؟',en:'After Confirm on sale.order what often happens?'},options:{ar:['حذف الأمر','state يتحول وتظهر إجراءات التسليم/الفوترة','لا شيء','يتحول إلى BOM'],en:['Order deleted','state changes and delivery/invoice actions appear','Nothing','Becomes a BOM']},answer:1,explanation:{ar:'التأكيد يغيّر الحالة ويفتح المسار التشغيلي.',en:'Confirm changes status and opens the operational path.'}}},
  
  {id:'sales-06',path:'sales',order:6,title:{ar:'عروض الأسعار (Quotations)',en:'Quotations'},description:{ar:'إنشاء وإرسال العروض',en:'Creating and sending quotations'},duration:12,xp:20,
    objectives:{ar:['إنشاء عرض','إضافة منتجات','إرسال للعميل','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create quotation','Add products','Send to customer','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'visual',title:{ar:'قائمة عروض الأسعار',en:'Quotations list'},content:{ar:'قائمة Quotations تعرض Draft و Sent و Sales Order. ابحث باسم العميل أو أنشئ New — ثم افتح السطر لتعديل العرض.',en:'Quotations list shows Draft, Sent and Sales Order. Search by customer name or create New — then open the row to edit the quote.'},image:'quotations-list.png',caption:{ar:'<strong>Quotations list</strong> — مسودات وعروض مرسلة. انقر سطراً لفتح النموذج أو New لإنشاء عرض.',en:'<strong>Quotations list</strong> — drafts and sent quotes. Click a row to open the form or New to create one.'}},
{type:'visual',title:{ar:'نموذج عرض السعر',en:'Quotation form'},content:{ar:'نموذج العرض: العميل، جدول البنود (منتج، كمية، سعر، ضريبة)، ثم Send by Email أو Confirm. راجع البنود قبل الإرسال.',en:'Quotation form: customer, lines table (product, qty, price, tax), then Send by Email or Confirm. Review lines before sending.'},image:'quotation-form.png',caption:{ar:'<strong>Quotation form</strong> — العميل، البنود، الأسعار، والضرائب. أرسل بالبريد ثم Confirm عند القبول.',en:'<strong>Quotation form</strong> — customer, lines, prices, and taxes. Send by email then Confirm on acceptance.'}},
      {type:'visual',title:{ar:'معلومات إضافية في العرض',en:'Other info on the quotation'},content:{ar:'تبويب Other Info: فريق المبيعات والشروط والمراجع. أكمله قبل إرسال عرض رسمي للعميل.',en:'Other Info tab: sales team, terms and references. Complete it before sending a formal quote to the customer.'},image:'quotation-other-info.png',caption:{ar:'<strong>Other Info</strong> — فريق المبيعات، الشروط، والمراجع. لا تتجاهله في العروض الرسمية.',en:'<strong>Other Info</strong> — sales team, terms, and references. Do not ignore it on formal quotes.'}},
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'عرض السعر (Quotation) مستند تقدمه للعميل قبل تأكيد البيع. بعد قبول العميل تضغط Confirm Order فيتحول إلى أمر بيع.',en:'A Quotation is the document you send before confirming the sale. After the customer accepts, you click Confirm Order and it becomes a Sales Order.'}},
      {type:'concept',title:{ar:'خطوات في أودو',en:'Steps in Odoo'},content:{ar:'1) Sales → Orders → Quotations → New.\n2) اختر Customer.\n3) أضف بنود Order Lines (منتج، كمية، سعر).\n4) راجع الإجمالي والضرائب.\n5) Send by Email أو اطبع PDF.\n6) عند القبول: Confirm Order.',en:'1) Sales → Orders → Quotations → New.\n2) Select Customer.\n3) Add Order Lines (product, qty, price).\n4) Check totals and taxes.\n5) Send by Email or print PDF.\n6) On accept: Confirm Order.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'1) Sales → Orders → Quotations → New.\n2) اختر عميلاً وأضف بند منتج واحد.\n3) راجع السعر والضريبة على الشاشة.\n4) Save (لا Confirm إن كانت بيئة إنتاج حقيقية بلا إذن).',en:'1) Sales → Orders → Quotations → New.\n2) Pick a customer and add one product line.\n3) Review price and tax on screen.\n4) Save (do not Confirm on a real production DB without permission).'}},
      {type:'why',title:{ar:'لماذا العرض قبل التأكيد؟',en:'Why quote before confirm?'},content:{ar:'العرض مسودة قابلة للإرسال والتعديل. Confirm يحوّله إلى التزام بيع (Sales Order) وتتغير الحالة على الشاشة.',en:'A quotation is a draft you can send and edit. Confirm turns it into a sales commitment (Sales Order) and status changes on screen.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'أرسل عرضاً للعميل (Send by Email). بعد موافقته ارجع لنفس الشاشة واضغط Confirm — لا تنشئ أمراً من الصفر.',en:'Send a quote to the customer (Send by Email). After approval return to the same screen and Confirm — do not create an order from scratch.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ضع Validity Date واضحة حتى لا يبقى العرض مفتوحًا بلا نهاية. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Set a clear Validity Date so the offer does not stay open forever. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'الضغط على Confirm قبل موافقة العميل — فيبدأ النظام تجهيز التوصيل والفاتورة مبكرًا. راجعه على الشاشة قبل الانتقال.',en:'Clicking Confirm before customer acceptance — the system starts delivery and invoicing too early. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'شاشة Quotation قبل Confirm تُستخدم لـ؟',en:'The Quotation screen before Confirm is used to?'},options:{ar:['إنشاء موظف','إرسال عرض سعر قبل تأكيد البيع','تعديل المخزون','إنشاء مستودع'],en:['Create employee','Send price offer before confirming sale','Adjust inventory','Create warehouse']},answer:1,explanation:{ar:'يُستخدم لتقديم عرض قبل تأكيد البيع. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Used to present an offer before confirming the sale. Review the lesson screen to lock in the idea.'}}},
  {id:'sales-07',path:'sales',order:7,title:{ar:'أوامر البيع (Sales Orders)',en:'Sales Orders'},description:{ar:'تأكيد الطلبات',en:'Confirming orders'},duration:10,xp:20,
    objectives:{ar:['تأكيد أمر البيع','حالة الطلب','الربط بالتوصيل والفاتورة','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Confirm sales order','Order status','Link delivery and invoice','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'visual',title:{ar:'أمر البيع في أودو',en:'Sales Order in Odoo'},content:{ar:'بعد Confirm تظهر أزرار ذكية على أمر البيع: Delivery و Create Invoice. أكمل المسار من نفس الشاشة لا من قوائم منفصلة.',en:'After Confirm, smart buttons appear on the sales order: Delivery and Create Invoice. Continue the flow from the same screen, not separate menus.'},image:'sales-order.png',caption:{ar:'<strong>Sales Order</strong> — بعد Confirm تتحول الحالة ويُفعَّل الربط مع المخزون والفوترة.',en:'<strong>Sales Order</strong> — after Confirm the status changes and links to inventory and invoicing activate.'}},
      
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'أمر البيع (Sales Order) هو العرض بعد Confirm على الشاشة. تتغير الحالة وتظهر أزرار ذكية Delivery و Create Invoice. من هنا يبدأ التنفيذ: تسليم البضاعة ثم الفوترة ثم التحصيل — كل خطوة شاشة مربوطة بنفس الأمر.',en:'A Sales Order is the quotation after Confirm on screen. Status changes and smart buttons Delivery and Create Invoice appear. Execution starts here: deliver, invoice, then collect — each step a screen linked to the same order.'}},
      {type:'why',title:{ar:'لماذا هذا مهم؟',en:'Why it matters'},content:{ar:'أمر البيع على الشاشة هو الجسر: منه Delivery (مخزون) و Create Invoice (محاسبة). بدون هذا الربط تتفكك التقارير بين ما بِيع وما سُلّم وما فُوتر.',en:'The sales order on screen is the bridge: from it Delivery (inventory) and Create Invoice (accounting). Without this link, reports break between what was sold, delivered and invoiced.'}},
      {type:'concept',title:{ar:'المسار بعد التأكيد',en:'Flow after confirmation'},content:{ar:'بعد Confirm على شاشة العرض:\n1) الحالة → Sales Order.\n2) أزرار ذكية: Delivery و Create Invoice.\n3) Delivery → Validate ينقص On Hand.\n4) Invoice → Confirm → Posted.\n5) Register Payment → Paid.\n6) الأمر يظهر Fully Invoiced عند اكتمال الفوترة.\nكل خطوة شاشة مربوطة بنفس الأمر.',en:'After Confirm on the quotation screen:\n1) Status → Sales Order.\n2) Smart buttons: Delivery and Create Invoice.\n3) Delivery → Validate decreases On Hand.\n4) Invoice → Confirm → Posted.\n5) Register Payment → Paid.\n6) Order shows Fully Invoiced when invoicing is complete.\nEach step is a linked screen on the same order.'}},
      {type:'concept',title:{ar:'خطوات في أودو',en:'Steps in Odoo'},content:{ar:'1) من الـ Quotation اضغط Confirm.\n2) يتحول المستند إلى Sales Order.\n3) من الأزرار الذكية أنشئ Delivery و/أو Invoice.\n4) راجع حالة التوصيل والفوترة من نفس الشاشة.',en:'1) On the Quotation click Confirm.\n2) The document becomes a Sales Order.\n3) From the smart buttons create Delivery and/or Invoice.\n4) Track delivery and invoicing status from the same screen.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مثال على الشاشة: عرض لـ 3 Laptops → Confirm → الحالة Sales Order → Delivery → راجع الكمية 3 → Validate في بيئة تجريبية. افتح بطاقة المنتج وقارن On Hand قبل وبعد.',en:'On-screen example: quote for 3 Laptops → Confirm → status Sales Order → Delivery → review qty 3 → Validate in a trial DB. Open the product form and compare On Hand before and after.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أمر بيع مؤكد (أو في المحاكي): حدّد مكان أزرار Delivery و Create Invoice على الشاشة. لا تنفّذ في الإنتاج دون مراجعة.',en:'On a confirmed sales order (or in the simulator): locate the Delivery and Create Invoice buttons on screen. Do not run them in production without review.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'راجع الكميات المتاحة قبل التأكيد. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Check available quantities before confirming. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إلغاء أمر بعد بدء التوصيل دون التحقق. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Cancelling order after delivery started without checking impact. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد Confirm على شاشة Quotation تصبح الحالة؟',en:'After Confirm on the Quotation screen, status becomes?'},options:{ar:['يُحذف','يتحول إلى Sales Order','فاتورة مباشرة فقط','لا شيء'],en:['Deleted','Becomes Sales Order','Invoice only','Nothing']},answer:1,explanation:{ar:'يتحول إلى أمر بيع ويبدأ السير. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'It becomes a Sales Order and workflow starts. Review the lesson screen to lock in the idea.'}}},
  {id:'sales-08',path:'sales',order:8,title:{ar:'الفوترة (Invoicing)',en:'Invoicing'},description:{ar:'إنشاء الفواتير من أوامر البيع',en:'Creating invoices from sales orders'},duration:12,xp:20,
    objectives:{ar:['فاتورة من أمر بيع','حالات الفاتورة','تسجيل الدفع','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Invoice from order','Invoice statuses','Register payment','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الفاتورة تُطلب من العميل بعد البيع. في أودو تُنشأ غالباً من أمر البيع بنقرة فتنسخ البنود والكميات تلقائياً وتحافظ على الربط.',en:'An invoice requests payment after the sale. In Odoo it is usually created from the sales order in one click, copying lines and quantities and keeping the link.'}},
      {type:'why',title:{ar:'لماذا من أمر البيع؟',en:'Why from the sales order?'},content:{ar:'الربط يحفظ التتبع: أي فاتورة مرتبطة بأي أمر، ويمنع التكرار والأخطاء في الكميات.',en:'The link keeps traceability: which invoice belongs to which order, and prevents duplicate or wrong quantities.'}},
      {type:'visual',title:{ar:'من أمر البيع إلى الفاتورة',en:'From sales order to invoice'},content:{ar:'من شاشة أمر البيع المؤكد: Create Invoice ينسخ البنود، وDelivery يفتح أمر التسليم. ابدأ من هنا لا من قوائم منفصلة.',en:'From the confirmed sales order screen: Create Invoice copies lines, Delivery opens the delivery order. Start here, not from separate menus.'},image:'sales-order.png',caption:{ar:'<strong>Sales Order</strong> — بعد التأكيد تظهر أزرار ذكية: إنشاء فاتورة، توصيل، وغيرها من نفس الشاشة.',en:'<strong>Sales Order</strong> — after confirmation, smart buttons appear: Create Invoice, Delivery, and more from the same screen.'}},
      {type:'concept',title:{ar:'خطوات الفوترة',en:'Invoicing steps'},content:{ar:'1) افتح Sales Order المؤكد.\n2) Create Invoice (عادة الكمية إلى الفاتورة = المطلوب).\n3) راجع مسودة الفاتورة (البنود، الضرائب، الحسابات).\n4) Confirm (تصبح Posted).\n5) Register Payment عند استلام الدفع.',en:'1) Open the confirmed Sales Order.\n2) Create Invoice (usually qty to invoice = ordered).\n3) Review the draft invoice (lines, taxes, accounts).\n4) Confirm (becomes Posted).\n5) Register Payment when payment is received.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'طلبية 100 قطعة، تسليم على دفعتين: يمكن فوترة 50 أولاً ثم 50 لاحقاً (فوترة جزئية) مع بقاء الربط بأمر البيع.',en:'Order of 100 units, delivery in two batches: you can invoice 50 first then 50 later (partial invoicing) while keeping the link to the sales order.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من أمر بيع مؤكد (بيئة تجريبية): افتح Delivery إن وُجد وراجع الكميات قبل أي Validate.',en:'From a confirmed sales order (trial DB): open Delivery if present and review quantities before any Validate.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'يمكن الفوترة الجزئية إذا كان التسليم على دفعات — لا تنتظر اكتمال الكل إن كانت السياسة تسمح.',en:'You can invoice partially if delivery is in installments — do not wait for full completion if policy allows.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء فاتورة يدوية من Accounting مع تجاهل أمر البيع — ينكسر الربط والتقارير. راجعه على الشاشة قبل الانتقال.',en:'Creating a manual invoice from Accounting and ignoring the sales order — links and reports break. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'على شاشة الفاتورة، ما تسلسل الحالات الرئيسي؟',en:'On the invoice screen, what is the main status sequence?'},options:{ar:['Open فقط','Draft → Posted → Paid','New → Old','لا حالات'],en:['Open only','Draft → Posted → Paid','New → Old','No statuses']},answer:1,explanation:{ar:'Draft ثم Posted ثم Paid. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Draft then Posted then Paid. Review the lesson screen to lock in the idea.'}}},
  
  {id:'sales-09',path:'sales',order:9,title:{ar:'خط أنابيب المبيعات',en:'Sales Pipeline'},description:{ar:'إدارة ومتابعة الخط',en:'Managing the pipeline'},duration:10,xp:20,
    objectives:{ar:['قراءة اللوحة','تحليل التحويلات','تحسين الأداء','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Read the board','Analyze conversions','Improve performance','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'خط المبيعات على شاشة Pipeline Kanban يعرض الفرص أعمدةً حسب المرحلة. الهدف التعليمي: اكتشاف الاختناقات (صفقة عالقة طويلاً في Proposal) وتحديث المرحلة بعد كل نشاط حقيقي حتى تبقى الشاشة مرآة لعمل الفريق لا سجلاً قديماً.',en:'The sales pipeline on the Pipeline Kanban screen shows opportunities in stage columns. Learning goal: spot bottlenecks (a deal stuck long in Proposal) and update the stage after every real activity so the screen mirrors the team’s work, not a stale record.'}},
      {type:'visual',title:{ar:'تحليل الخط',en:'Pipeline analysis'},content:{ar:'تقارير Pipeline تجمع الإيراد المتوقع حسب المرحلة أو الفريق. راجعها أسبوعياً لضبط التوقعات والاختناقات.',en:'Pipeline reports aggregate expected revenue by stage or team. Review weekly to adjust forecasts and bottlenecks.'},image:'pipeline-analysis.png',caption:{ar:'<strong>Pipeline analysis</strong> — تقارير الإيراد المتوقع حسب المرحلة أو الفريق لاتخاذ قرارات أفضل.',en:'<strong>Pipeline analysis</strong> — expected revenue reports by stage or team for better decisions.'}},
      {type:'visual',title:{ar:'Kanban اليومي',en:'Daily Kanban'},content:{ar:'Kanban Pipeline: كل عمود مرحلة وكل بطاقة فرصة. اسحب البطاقة بين الأعمدة لتحديث المرحلة فوراً — الخط يصبح مرآة لعمل الفريق.',en:'Kanban Pipeline: each column is a stage and each card an opportunity. Drag the card between columns to update the stage immediately — the pipeline mirrors the team’s work.'},image:'pipeline-kanban.png',caption:{ar:'<strong>Pipeline Kanban</strong> — نظرة بصرية سريعة على صحة خط المبيعات.',en:'<strong>Pipeline Kanban</strong> — a quick visual health check of the sales pipeline.'}},
      {type:'concept',title:{ar:'خطوات عملية',en:'Practical steps'},content:{ar:'1) CRM → Pipeline.\n2) راجع البطاقات المتوقفة طويلاً في مرحلة واحدة.\n3) حدّث Next Activity.\n4) استخدم Group By أو Filters حسب البائع أو الفريق.\n5) أسبوعيًا: افتح Reporting لمراجعة التحويل.',en:'1) CRM → Pipeline.\n2) Review cards stuck long in one stage.\n3) Update Next Activity.\n4) Use Group By or Filters by salesperson or team.\n5) Weekly: open Reporting to review conversion.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'اجتماع أسبوعي: افتح Pipeline Analysis حسب المرحلة، حدّد الاختناقات (مثلاً عالق في Proposal)، ثم عد إلى Kanban وحدّث البطاقات.',en:'Weekly meeting: open Pipeline Analysis by stage, spot bottlenecks (e.g. stuck in Proposal), then return to Kanban and update cards.'}},
      {type:'why',title:{ar:'لماذا تحليل الخط؟',en:'Why pipeline analysis?'},content:{ar:'الأرقام المجمّعة حسب المرحلة تكشف أين يتوقف البيع. القرار يعتمد على الشاشة لا على الحدس فقط.',en:'Numbers grouped by stage reveal where sales stall. Decisions rely on the screen, not gut feel alone.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح تقرير Pipeline أو Group By Stage من القائمة. سجّل عدد الفرص في كل مرحلة.',en:'Open a Pipeline report or Group By Stage from the list. Note how many opportunities sit in each stage.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا علقت فرص كثيرة في Proposition راجع جودة العروض والمتابعة. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'If many opportunities stick in Proposition, review offer quality and follow-up. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'الاهتمام فقط بعدد الفرص دون القيمة أو احتمال الإغلاق. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Focusing only on opportunity count without value or win probability. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'شاشة Pipeline Kanban تفيد لأنها تعرض؟',en:'The Pipeline Kanban screen helps because it shows?'},options:{ar:['فواتير فقط','رؤية الفرص حسب المرحلة وتحليل الأداء','تعديل مخزون','رواتب'],en:['Invoices only','See opportunities by stage and analyze','Adjust inventory','Payroll']},answer:1,explanation:{ar:'يعرض الفرص في مراحلها ويساعد التحليل. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Shows opportunities in stages and helps analysis. Review the lesson screen to lock in the idea.'}}},
  {id:'sales-10',path:'sales',order:10,title:{ar:'ملخص المبيعات وخريطة الشاشات',en:'Sales Summary & Screen Map'},description:{ar:'من Lead إلى Payment على الشاشات',en:'From Lead to Payment on screens'},duration:12,xp:25,
    objectives:{ar:['تلخيص مسار البيع','ربط CRM بالمخزون والفوترة'],en:['Summarize the sales flow','Link CRM to inventory and invoicing']},
    sections:[
      {type:'intro',title:{ar:'المسار الكامل',en:'Full flow'},content:{ar:'CRM لا ينتهي عند Won: يمتد إلى Quotation ثم Sales Order ثم Delivery و Invoice و Payment. كل مرحلة شاشة، والحالة على الشاشة هي مصدر الحقيقة.',en:'CRM does not end at Won: it extends to Quotation then Sales Order then Delivery, Invoice and Payment. Each stage is a screen, and on-screen status is the source of truth.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) CRM → Leads → (تأهيل) → Opportunity في Pipeline Kanban.\\n2) من Opportunity أو Sales: Quotation (Form + بنود).\\n3) Confirm → Sales Order + أزرار ذكية.\\n4) Delivery → Validate → On Hand ينقص.\\n5) Create Invoice → Confirm → Posted.\\n6) Register Payment → Paid.\\nحدّث المرحلة في Pipeline بعد كل تقدم حقيقي.',en:'1) CRM → Leads → (qualify) → Opportunity on Pipeline Kanban.\\n2) From Opportunity or Sales: Quotation (Form + lines).\\n3) Confirm → Sales Order + smart buttons.\\n4) Delivery → Validate → On Hand decreases.\\n5) Create Invoice → Confirm → Posted.\\n6) Register Payment → Paid.\\nUpdate Pipeline stage after every real advance.'}},
      {type:'visual',title:{ar:'أمر البيع كنقطة ربط',en:'Sales order as the hub'},content:{ar:'بعد Confirm تظهر Delivery و Create Invoice على نفس الشاشة. لا تبدأ التسليم أو الفاتورة من قوائم منفصلة إن وُجد الأمر.',en:'After Confirm, Delivery and Create Invoice appear on the same screen. Do not start delivery or invoice from separate menus if the order exists.'},image:'sales-order.png',caption:{ar:'<strong>Sales Order</strong> — المحور بين CRM والمخزون والمحاسبة على الشاشة.',en:'<strong>Sales Order</strong> — the hub between CRM, inventory and accounting on screen.'}},
      {type:'example',title:{ar:'مثال نهاية المسار',en:'End-to-end example'},content:{ar:'فرصة Laptop → عرض 3 وحدات → Confirm → Delivery Validate → Invoice Posted → Payment. في Pipeline الحالة Won، وفي المخزون On Hand −3.',en:'Laptop opportunity → quote 3 units → Confirm → Delivery Validate → Invoice Posted → Payment. Pipeline shows Won; stock On Hand −3.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'ارسم على ورقة الشاشات الست بالترتيب، ثم افتح أودو تجريبي وطابق كل اسم قائمة مع رسمك.',en:'Draw the six screens in order on paper, then open trial Odoo and match each menu name to your sketch.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا اختفت الأزرار الذكية: تحقق أن الحالة Sales Order وليس Draft.',en:'If smart buttons are missing: check status is Sales Order, not Draft.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'فاتورة من المحاسبة دون أمر بيع — ينكسر الربط مع الفرصة والتسليم.',en:'Invoice from accounting without a sales order — the link to the opportunity and delivery breaks.'}}
    ],
    knowledgeCheck:{question:{ar:'المحور على الشاشة بين البيع والمخزون والفوترة؟',en:'On-screen hub between sales, stock and invoicing?'},options:{ar:['Lead فقط','Sales Order بعد Confirm','BOM','الإجازات'],en:['Lead only','Sales Order after Confirm','BOM','Time off']},answer:1,explanation:{ar:'أمر البيع بعد التأكيد يحمل الأزرار الذكية.',en:'Sales order after confirm carries the smart buttons.'}}},
  
  {id:'inventory-01',path:'inventory',order:1,title:{ar:'نظرة عامة على المخزون',en:'Inventory Overview'},description:{ar:'مقدمة إدارة المخزون',en:'Intro to inventory management'},duration:10,xp:20,
    objectives:{ar:['دور المخزون','العمليات الأساسية','استلام vs تسليم','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Inventory role','Basic operations','Receipt vs delivery','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق Inventory يتتبع الكميات: استلام، تسليم، تحويل بين المواقع، وجرد. يرتبط مباشرة بالمبيعات والمشتريات.',en:'The Inventory app tracks quantities: receipts, deliveries, internal transfers and adjustments. It links directly to sales and purchases.'}},
      {type:'visual',title:{ar:'مثال استلام في المخزون',en:'Example receipt in inventory'},content:{ar:'شاشة الاستلام: المصدر/المورد، موقع الوجهة، وجدول Demand مقابل Done. ضع الكمية الفعلية في Done ثم Validate.',en:'Receipt screen: source/vendor, destination location, and Demand vs Done table. Put actual quantity in Done then Validate.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt</strong> — من Inventory → Operations → Receipts. راجع الكميات ثم Validate.',en:'<strong>Receipt</strong> — from Inventory → Operations → Receipts. Review quantities then Validate.'}},
      {type:'concept',title:{ar:'المفاهيم الأساسية',en:'Core ideas'},content:{ar:'• On Hand: الكمية الموجودة.\n• Reserved: محجوزة لأوامر.\n• Available = On Hand − Reserved.\n• العمليات: Receipts، Deliveries، Internal Transfers، Adjustments.',en:'• On Hand: quantity in stock.\n• Reserved: reserved for orders.\n• Available = On Hand − Reserved.\n• Operations: Receipts, Deliveries, Internal Transfers, Adjustments.'}},
      {type:'concept',title:{ar:'خطوات عملية — من أين تبدأ؟',en:'Practical steps — where to start'},content:{ar:'1) Inventory → Overview لرؤية الملخص.\n2) Operations → Receipts للاستلام.\n3) Products لمراجعة الكميات.\n4) Configuration للمستودعات والمواقع (بعد فهم الأساسيات).',en:'1) Inventory → Overview for the summary.\n2) Operations → Receipts for receiving.\n3) Products to review quantities.\n4) Configuration for warehouses and locations (after the basics).'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'شراء Laptop: PO → Receipt → Validate (On Hand يزيد). بيع لنفس المنتج: Sales Order → Delivery → Validate (On Hand ينقص).',en:'Buy Laptop: PO → Receipt → Validate (On Hand increases). Sell the same product: Sales Order → Delivery → Validate (On Hand decreases).'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Inventory → Products. اختر منتجاً Storable ولاحظ On Hand و Reserved. اربط الرقم بفكرة: الاستلام يزيد، التسليم ينقص.',en:'Open Inventory → Products. Pick a Storable product and note On Hand and Reserved. Link the number to the idea: receipt increases, delivery decreases.'}},
      {type:'why',title:{ar:'لماذا المخزون في أودو؟',en:'Why inventory in Odoo?'},content:{ar:'لأن On Hand يتحدث من شاشات الاستلام والتسليم وليس من جداول يدوية. الربط مع البيع والشراء يمنع البيع من فراغ.',en:'Because On Hand updates from receipt and delivery screens, not manual spreadsheets. Links to sales and purchase prevent selling empty stock.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تعدّل الكميات يدويًا إلا عبر Adjustment مبرر — حتى تبقى الحركات قابلة للتتبع. راجعه على الشاشة قبل الانتقال.',en:'Do not change quantities by hand except via a justified Adjustment — so moves stay auditable. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'البيع من المخزون دون التحقق من Available — فيظهر نقص بعد التأكيد. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Selling from stock without checking Available — shortages appear after confirmation. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'أي شاشة بعد Validate تزيد On Hand عند الشراء؟',en:'Which screen after Validate increases On Hand when purchasing?'},options:{ar:['Delivery','Receipt','Sales Order فقط','Invoice'],en:['Delivery','Receipt','Sales Order only','Invoice']},answer:1,explanation:{ar:'Receipt يسجّل الدخول ويزيد الكمية. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Receipt records incoming and increases quantity. Review the lesson screen to lock in the idea.'}}},
  {id:'inventory-02',path:'inventory',order:2,title:{ar:'المستودعات (Warehouses)',en:'Warehouses'},description:{ar:'تعريف المستودعات وهيكل التخزين',en:'Defining warehouses and storage structure'},duration:12,xp:20,
    objectives:{ar:['تعريف المستودع','فهم المواقع الافتراضية','ربط المستودع بالعمليات','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Define a warehouse','Understand default locations','Link warehouse to operations','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المستودع (Warehouse) هو المكان المنطقي لتخزين المنتجات. كل عملية استلام أو تسليم تتم ضمن مستودع ومواقع داخله.',en:'A Warehouse is the logical place to store products. Every receipt or delivery happens within a warehouse and its locations.'}},
      {type:'why',title:{ar:'لماذا تعريف المستودع مهم؟',en:'Why defining the warehouse matters'},content:{ar:'بدون مستودع واضح تختلط الكميات ويصعب معرفة أين البضاعة فعلياً. المستودع أساس التقارير والحجوزات.',en:'Without a clear warehouse, quantities mix and you cannot tell where goods actually are. The warehouse underpins reports and reservations.'}},
      {type:'visual',title:{ar:'المستودع في عمليات الاستلام',en:'Warehouse on receipts'},content:{ar:'في أعلى أو تفاصيل الاستلام: المستودع وموقع الوجهة. تأكد أنهما صحيحان قبل Validate حتى تدخل الكمية المكان المقصود.',en:'At the top or in receipt details: warehouse and destination location. Confirm both before Validate so quantity enters the intended place.'},image:'receipt-form.png',caption:{ar:'<strong>المستودع والموقع</strong> — كل عملية استلام مرتبطة بمستودع وموقع وجهة محددين.',en:'<strong>Warehouse & location</strong> — every receipt is linked to a specific warehouse and destination location.'}},
      {type:'concept',title:{ar:'خطوات إعداد مستودع',en:'Steps to set up a warehouse'},content:{ar:'1) Inventory → Configuration → Warehouses → New.\n2) اسم المستودع والرمز القصير.\n3) أودو ينشئ مواقع افتراضية (Stock، Input، Output) تلقائياً.\n4) اربط المستودع بشركة إن كان لديك أكثر من شركة.\n5) احفظ واستخدمه في أوامر الشراء والبيع.',en:'1) Inventory → Configuration → Warehouses → New.\n2) Warehouse name and short code.\n3) Odoo creates default locations (Stock, Input, Output) automatically.\n4) Link the warehouse to a company if you have more than one.\n5) Save and use it on purchase and sales orders.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'فرع الرياض وفرع جدة = مستودعان. كل استلام يختار المستودع الصحيح حتى لا تختلط كميات الفرعين.',en:'Riyadh branch and Jeddah branch = two warehouses. Each receipt picks the correct warehouse so branch quantities do not mix.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Inventory → Configuration → Warehouses (أو Locations). اقرأ اسم المستودع الرئيسي دون تغيير الإعدادات في الإنتاج.',en:'Open Inventory → Configuration → Warehouses (or Locations). Read the main warehouse name without changing settings in production.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ابدأ بمستودع واحد حتى تستقر العمليات، ثم أضف فروعاً عند الحاجة. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Start with one warehouse until operations stabilize, then add branches when needed. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء مستودعات كثيرة بلا حاجة — تعقيد في التحويلات والتقارير. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Creating many warehouses without need — complexity in transfers and reports. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'في إعدادات المخزون على الشاشة، المستودع يحتوي عادة؟',en:'In inventory settings on screen, a warehouse typically contains?'},options:{ar:['موظفين فقط','مواقع فرعية للمنتجات (Stock, Input…)','فواتير','عملاء فقط'],en:['Employees only','Sub-locations for products (Stock, Input…)','Invoices','Customers only']},answer:1,explanation:{ar:'مواقع مثل Stock و Input لتنظيم التخزين. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Locations such as Stock and Input to organize storage. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-03',path:'inventory',order:3,title:{ar:'المواقع (Locations)',en:'Locations'},description:{ar:'المواقع داخل المستودع',en:'Locations inside the warehouse'},duration:12,xp:20,
    objectives:{ar:['فهم التسلسل الهرمي للمواقع','الفرق بين Internal و View','استخدام المواقع في التحويلات','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Understand location hierarchy','Internal vs View locations','Use locations in transfers','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الموقع (Location) يحدد أين توجد الكمية داخل المستودع أو خارجه (مورد، عميل). المواقع تُرتَّب هرمياً: WH/Stock/Shelf-A.',en:'A Location defines where quantity sits inside the warehouse or outside (vendor, customer). Locations are hierarchical: WH/Stock/Shelf-A.'}},
      {type:'visual',title:{ar:'الموقع في عملية المخزون',en:'Location on stock operation'},content:{ar:'شاشة الاستلام: المصدر/المورد، موقع الوجهة، وجدول Demand مقابل Done. ضع الكمية الفعلية في Done ثم Validate.',en:'Receipt screen: source/vendor, destination location, and Demand vs Done table. Put actual quantity in Done then Validate.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt</strong> — من Inventory → Operations → Receipts. راجع الكميات ثم Validate.',en:'<strong>Receipt</strong> — from Inventory → Operations → Receipts. Review quantities then Validate.'}},
      {type:'concept',title:{ar:'خطوات فهم المواقع',en:'Steps to understand locations'},content:{ar:'1) Inventory → Configuration → Locations.\n2) لاحظ الأنواع: Internal (تخزين)، View (تجميع فقط)، Customer/Vendor.\n3) المواقع الداخلية تحت المستودع هي التي تحمل On Hand.\n4) عند التحويل الداخلي حدد المصدر والوجهة بدقة.\n5) لا تحذف مواقع افتراضية يستخدمها النظام.',en:'1) Inventory → Configuration → Locations.\n2) Note types: Internal (storage), View (grouping only), Customer/Vendor.\n3) Internal locations under the warehouse hold On Hand.\n4) On internal transfer set source and destination precisely.\n5) Do not delete default locations the system uses.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مثال على الشاشة: Inventory → Operations → Internal Transfer. المصدر WH/Stock والوجهة WH/Stock/Shelf-B بعد ترتيب الرفوف. Validate ينقل الكمية بين المواقع دون شراء أو بيع ودون تغيير الملكية الخارجية.',en:'On-screen example: Inventory → Operations → Internal Transfer. Source WH/Stock, destination WH/Stock/Shelf-B after reorganizing shelves. Validate moves quantity between locations without buying or selling and without changing external ownership.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من قائمة المنتجات افتح منتجاً وحدد النوع: Storable / Consumable / Service. تأكد أن منتجات المخزون الحقيقي من نوع Storable.',en:'From the product list open a product and identify the type: Storable / Consumable / Service. Ensure real stock items are Storable.'}},
      {type:'why',title:{ar:'لماذا نوع المنتج مهم؟',en:'Why product type matters?'},content:{ar:'Storable يتحرك في المخزون. Consumable لا يُتتبّع كمية. Service بلا مخزون. الاختيار الخاطئ يفسد On Hand والتقارير.',en:'Storable moves in stock. Consumable is not quantity-tracked. Service has no stock. The wrong choice breaks On Hand and reports.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تفرّط في تفصيل المواقع في البداية. رفوف قليلة واضحة أفضل من مئات المواقع الفارغة. راجعه على الشاشة قبل الانتقال.',en:'Do not over-detail locations at the start. A few clear shelves beat hundreds of empty locations. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'وضع كل الكمية في موقع View — View لا يخزّن كمية فعلية. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Putting all quantity in a View location — View does not hold real quantity. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'في شجرة المواقع، أي نوع يخزّن كمية فعلية؟',en:'In the location tree, which type holds real quantity?'},options:{ar:['View فقط','Internal','Customer فقط','لا شيء'],en:['View only','Internal','Customer only','None']},answer:1,explanation:{ar:'Internal هو الذي يحمل On Hand. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Internal is what holds On Hand. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-04',path:'inventory',order:4,title:{ar:'المنتجات في المخزون',en:'Products in Inventory'},description:{ar:'أنواع المنتجات والكميات',en:'Product types and quantities'},duration:12,xp:20,
    objectives:{ar:['Storable vs Consumable vs Service','قراءة On Hand و Reserved','فتح بطاقة المنتج','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Storable vs Consumable vs Service','Read On Hand and Reserved','Open the product form','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'نوع المنتج يحدد سلوك المخزون: Storable يُتتبَّع كمية، Consumable يُستهلك دون تتبع دقيق، Service بلا مخزون.',en:'Product type controls inventory behavior: Storable tracks quantity, Consumable is used without precise tracking, Service has no stock.'}},
      {type:'visual',title:{ar:'قائمة المنتجات',en:'Product list'},content:{ar:'من قائمة المنتجات افتح البطاقة لمراجعة On Hand و Reserved والنوع (Storable). أي تسوية أو قاعدة إعادة طلب تبدأ من هنا.',en:'From the product list open the form to review On Hand, Reserved and type (Storable). Any adjustment or reordering rule starts here.'},image:'product-catalog.png',caption:{ar:'<strong>On Hand</strong> — من بطاقة المنتج راقب الكمية قبل أي تعديل أو قاعدة إعادة طلب.',en:'<strong>On Hand</strong> — from the product form monitor quantity before any adjustment or reordering rule.'}},
      {type:'concept',title:{ar:'خطوات قراءة كميات المنتج',en:'Steps to read product quantities'},content:{ar:'1) افتح المنتج (Storable).\n2) On Hand = الكمية الموجودة فعلياً في المواقع الداخلية.\n3) Reserved = محجوزة لأوامر تسليم أو تصنيع.\n4) المتاح غالباً = On Hand − Reserved.\n5) Forecast يعرض الوارد والصادر المتوقع.',en:'1) Open the product (Storable).\n2) On Hand = quantity physically in internal locations.\n3) Reserved = reserved for delivery or manufacturing orders.\n4) Available is usually On Hand − Reserved.\n5) Forecast shows expected incoming and outgoing.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'On Hand = 100، Reserved = 30 لأمر تسليم → المتاح للبيع الجديد ≈ 70. لا تبع 100 دون مراجعة الحجوزات.',en:'On Hand = 100, Reserved = 30 for a delivery order → available for new sales ≈ 70. Do not sell 100 without checking reservations.'}},
      {type:'why',title:{ar:'لماذا الوحدات والمستودع؟',en:'Why units and warehouse?'},content:{ar:'وحدة القياس الخاطئة أو المستودع الخطأ يجعل Validate يضع الكمية في مكان لا تبحث عنه لاحقاً.',en:'Wrong unit of measure or warehouse makes Validate put quantity where you will not look later.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على بطاقة منتج Storable راجع Unit of Measure وأي حقل للمستودع/المسارات إن ظهر. لا تعدّل في الإنتاج دون فهم.',en:'On a Storable product form review Unit of Measure and any warehouse/routes field if shown. Do not change production without understanding.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'استخدم Storable فقط للمنتجات التي تحتاج تتبع كمية. الخدمات والمواد البسيطة قد تكون Consumable أو Service.',en:'Use Storable only for products that need quantity tracking. Services and simple materials may be Consumable or Service.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'جعل كل شيء Storable دون حاجة — يزيد عمليات المخزون والتعقيد بلا فائدة. راجعه على الشاشة قبل الانتقال.',en:'Making everything Storable without need — increases stock operations and complexity with no benefit. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'على بطاقة المنتج، Available تقريباً تساوي؟',en:'On the product form, Available is roughly?'},options:{ar:['On Hand فقط','On Hand − Reserved','Reserved فقط','السعر'],en:['On Hand only','On Hand − Reserved','Reserved only','Price']},answer:1,explanation:{ar:'المتاح ≈ الموجود − المحجوز. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Available ≈ On Hand − Reserved. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-05',path:'inventory',order:5,title:{ar:'عمليات الاستلام (Receipts)',en:'Receipts'},description:{ar:'استلام البضائع',en:'Receiving goods'},duration:12,xp:20,
    objectives:{ar:['إنشاء Receipt','تسجيل الكميات','Validate','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create Receipt','Record quantities','Validate','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'visual',title:{ar:'شاشة استلام البضاعة',en:'Goods receipt screen'},content:{ar:'من Inventory → Operations → Receipts تفتح قائمة الاستلامات. عند فتح إيصال تظهر المنتجات والكميات المتوقع استلامها.',en:'From Inventory → Operations → Receipts you open the receipts list. Opening a receipt shows products and expected quantities.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt form</strong> — المنتجات والكميات المتوقع استلامها. راجع ثم Validate لإدخال المخزون.',en:'<strong>Receipt form</strong> — products and expected quantities. Review then Validate to enter stock.'}},
      {type:'concept',title:{ar:'خطوات الاستلام في أودو',en:'Receipt steps in Odoo'},content:{ar:'1) Inventory → Operations → Receipts.\n2) افتح الإيصال (أو أنشئ واحدًا من أمر شراء).\n3) أدخل الكميات الفعلية في Done.\n4) Validate.\n5) تتحدث كميات On Hand تلقائيًا.',en:'1) Inventory → Operations → Receipts.\n2) Open the receipt (or create one from a purchase order).\n3) Enter actual quantities in Done.\n4) Validate.\n5) On Hand quantities update automatically.'}},
      
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'شاشة Receipt تسجّل دخول المنتجات للمخزون (من مورد عبر PO أو تحويل). الأعمدة الحاسمة Demand و Done. Validate يرفع On Hand فقط بعد مطابقة البضاعة وإذن التسليم على الأرض — هذا أهم قرار تشغيلي على الشاشة.',en:'The Receipt screen records products entering stock (from a vendor via PO or a transfer). Critical columns: Demand and Done. Validate raises On Hand only after matching goods and the delivery note on the floor — the most important operational decision on the screen.'}},
      {type:'why',title:{ar:'لماذا هذا مهم؟',en:'Why it matters'},content:{ar:'بدون Validate على شاشة Receipt لا يزداد On Hand حتى لو وصلت البضاعة فعلياً. التوثيق على الشاشة هو ما يجعل المخزون في أودو يطابق الواقع.',en:'Without Validate on the Receipt screen On Hand does not increase even if goods physically arrived. Documentation on screen is what makes Odoo stock match reality.'}},
      {type:'concept',title:{ar:'المفهوم الأساسي',en:'Core Concept'},content:{ar:'على شاشة Receipt:\n1) من PO اضغط Receipt أو Inventory → Receipts → New.\n2) المورد/المصدر + موقع الوجهة.\n3) المنتجات و Demand.\n4) عند الوصول: الكمية الفعلية في Done.\n5) Validate → Done وارتفاع On Hand.\nلا Validate قبل مطابقة إذن التسليم الفعلي.',en:'On the Receipt screen:\n1) From the PO click Receipt or Inventory → Receipts → New.\n2) Vendor/source + destination location.\n3) Products and Demand.\n4) On arrival: actual qty in Done.\n5) Validate → Done and On Hand increases.\nDo not Validate before matching the physical delivery note.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مثال مسار على الشاشات: PO لـ 10 Laptop → Receipt من الأمر → ضع 10 في Done → Validate → افتح المنتج وتأكد On Hand +10. إن وصل 7 فقط: Done = 7 واترك 3 لاستلام لاحق (استلام جزئي).',en:'On-screen flow example: PO for 10 Laptop → Receipt from the order → put 10 in Done → Validate → open the product and confirm On Hand +10. If only 7 arrived: Done = 7 and leave 3 for a later receipt (partial receipt).'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'1) Inventory → Operations → Receipts (أو من أمر شراء).\n2) افتح إيصالاً وراجع Demand vs Done.\n3) في بيئة تجريبية فقط: ضع الكمية في Done و Validate.\n4) راجع On Hand على بطاقة المنتج.',en:'1) Inventory → Operations → Receipts (or from a PO).\n2) Open a receipt and review Demand vs Done.\n3) In a trial DB only: put qty in Done and Validate.\n4) Review On Hand on the product form.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'طابق الكمية الفعلية مع أمر الشراء قبل Validate. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Match physical quantity with purchase order before Validate. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Validate لكميات لم تصل — مخزون وهمي. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Validating quantities not yet arrived — phantom stock. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'على شاشة Receipt، ماذا يحدث بعد Validate؟',en:'On the Receipt screen, what happens after Validate?'},options:{ar:['حذف منتجات','زيادة كمية المخزون','فاتورة مبيعات','لا شيء'],en:['Delete products','Stock quantity increases','Sales invoice','Nothing']},answer:1,explanation:{ar:'ينقل الكمية إلى المخزون ويزيد On Hand. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Moves quantity into stock and increases On Hand. Review the lesson screen to lock in the idea.'}}},
  {id:'inventory-06',path:'inventory',order:6,title:{ar:'أوامر التسليم (Delivery Orders)',en:'Delivery Orders'},description:{ar:'تسليم البضائع للعملاء',en:'Delivering goods to customers'},duration:12,xp:20,
    objectives:{ar:['فهم Delivery','التحقق من الكميات','Validate وخفض المخزون','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Understand Delivery','Check quantities','Validate and reduce stock','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'التسليم للعميل هو العملية العكسية للاستلام: تخرج الكمية من المستودع. غالباً تُنشأ تلقائياً من أمر البيع المؤكد.',en:'Customer delivery is the reverse of receipt: quantity leaves the warehouse. It is often created automatically from a confirmed sales order.'}},
      {type:'why',title:{ar:'لماذا Validate مهم؟',en:'Why Validate matters'},content:{ar:'قبل Validate الكمية محجوزة فقط. بعد Validate تنقص On Hand فعلياً وتتحدّث حالة أمر البيع.',en:'Before Validate the quantity is only reserved. After Validate, On Hand actually decreases and the sales order status updates.'}},
      {type:'visual',title:{ar:'عملية مكتملة',en:'Completed operation'},content:{ar:'Validate يغيّر الحالة إلى Done ويحدّث On Hand. نفس الزر ونفس الفكرة في Receipt و Delivery و Internal Transfer.',en:'Validate changes status to Done and updates On Hand. Same button and idea on Receipt, Delivery and Internal Transfer.'},image:'receipt-done.png',caption:{ar:'<strong>Validate → Done</strong> — تتحدث الكميات في المصدر والوجهة تلقائياً.',en:'<strong>Validate → Done</strong> — quantities update automatically at source and destination.'}},
      {type:'concept',title:{ar:'خطوات التسليم',en:'Delivery steps'},content:{ar:'1) من أمر البيع أو Inventory → Deliveries.\n2) افتح أمر التسليم.\n3) تأكد من الكميات في عمود Done.\n4) Validate.\n5) تنقص On Hand وتُحدَّث حالة أمر البيع.',en:'1) From the sales order or Inventory → Deliveries.\n2) Open the delivery order.\n3) Confirm quantities in the Done column.\n4) Validate.\n5) On Hand decreases and the sales order status updates.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'أمر بيع لـ 10 وحدات: أودو ينشئ Delivery بـ 10. عند التجهيز تضع 10 في Done ثم Validate — المخزون ينقص 10.',en:'Sales order for 10 units: Odoo creates a Delivery for 10. When ready, put 10 in Done then Validate — stock decreases by 10.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'قارن على الشاشة: Receipt يزيد On Hand بعد Validate، وDelivery ينقصه. افتح منتجاً واحداً وراقب الرقم قبل/بعد في بيئة تجريبية.',en:'Compare on screen: Receipt increases On Hand after Validate, Delivery decreases it. Open one product and watch the number before/after in a trial DB.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'إذا ظهرت تحذيرة عدم توفر كمية، راجع الحجوزات أو انتظر استلام وارد قبل Validate. راجعه على الشاشة قبل الانتقال.',en:'If an availability warning appears, check reservations or wait for an incoming receipt before Validate. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Validate على كمية خاطئة ثم التصحيح اليدوي — الأفضل Reverse أو Adjustment موثّق. راجعه على الشاشة قبل الانتقال.',en:'Validating a wrong quantity then fixing by hand — better to Reverse or use a documented Adjustment. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد Validate على شاشة Delivery، ماذا يحدث لـ On Hand؟',en:'After Validate on the Delivery screen, what happens to On Hand?'},options:{ar:['تزداد','تنخفض','تبقى','تُصفَّر'],en:['Increases','Decreases','Stays','Becomes zero']},answer:1,explanation:{ar:'يخصم الكمية من المخزون (On Hand). راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Deducts the quantity from stock (On Hand). Review the lesson screen to lock in the idea.'}}
},
  
  {id:'inventory-07',path:'inventory',order:7,title:{ar:'التحويلات الداخلية',en:'Internal Transfers'},description:{ar:'نقل بين المواقع داخل الشركة',en:'Moving between locations inside the company'},duration:12,xp:20,
    objectives:{ar:['إنشاء تحويل داخلي','اختيار المصدر والوجهة','Validate','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create internal transfer','Select source and destination','Validate','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'التحويل الداخلي ينقل كمية من موقع إلى آخر دون بيع أو شراء: من رف إلى رف، أو من مستودع إلى مستودع تابع لنفس الشركة.',en:'An internal transfer moves quantity from one location to another without a sale or purchase: shelf to shelf, or warehouse to warehouse in the same company.'}},
      {type:'visual',title:{ar:'نموذج عملية المخزون',en:'Stock operation form'},content:{ar:'شاشة الاستلام: المصدر/المورد، موقع الوجهة، وجدول Demand مقابل Done. ضع الكمية الفعلية في Done ثم Validate.',en:'Receipt screen: source/vendor, destination location, and Demand vs Done table. Put actual quantity in Done then Validate.'},image:'receipt-form.png',caption:{ar:'<strong>Internal Transfer</strong> — نفس نموذج العمليات: مصدر، وجهة، كميات، ثم Validate.',en:'<strong>Internal Transfer</strong> — same operations form: source, destination, quantities, then Validate.'}},
      {type:'concept',title:{ar:'خطوات التحويل الداخلي',en:'Internal transfer steps'},content:{ar:'1) Inventory → Operations → Transfers → New (أو Internal Transfers).\n2) حدد Operation Type المناسب (Internal Transfer).\n3) اختر Source Location و Destination Location.\n4) أضف المنتجات والكميات.\n5) Validate عند التنفيذ الفعلي.',en:'1) Inventory → Operations → Transfers → New (or Internal Transfers).\n2) Set the appropriate Operation Type (Internal Transfer).\n3) Choose Source Location and Destination Location.\n4) Add products and quantities.\n5) Validate when physically done.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'نقل 20 وحدة من WH/Stock إلى WH/Stock/Packing لتجهيز شحنة — تحويل داخلي قبل إنشاء Delivery للعميل.',en:'Move 20 units from WH/Stock to WH/Stock/Packing to prepare a shipment — internal transfer before creating the customer Delivery.'}},
      {type:'why',title:{ar:'لماذا التحويل الداخلي؟',en:'Why internal transfers?'},content:{ar:'لنقل الكمية بين المواقع دون شراء أو بيع. الشاشة تشبه الاستلام لكن المصدر والوجهة داخل الشركة.',en:'To move quantity between locations without buying or selling. The screen is like a receipt but source and destination stay inside the company.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من Inventory → Operations ابحث عن Internal Transfers. افتح سجلاً (إن وُجد) ولاحظ مواقع المصدر والوجهة.',en:'From Inventory → Operations find Internal Transfers. Open a record (if any) and note source and destination locations.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'سمِّ المواقع بوضوح (Packing، Quarantine) ليسهل اختيار المصدر والوجهة دون أخطاء. راجعه على الشاشة قبل الانتقال.',en:'Name locations clearly (Packing, Quarantine) so source and destination are chosen without mistakes. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'استخدام Delivery أو Receipt بدل التحويل الداخلي بين مواقع الشركة — يفسد تقارير العملاء/الموردين.',en:'Using Delivery or Receipt instead of internal transfer between company locations — corrupts customer/vendor reports.'}}
    ],
    knowledgeCheck:{question:{ar:'متى تفتح شاشة Internal Transfer؟',en:'When do you open the Internal Transfer screen?'},options:{ar:['بيع للعميل','نقل بين مواقع داخل الشركة','شراء من مورد','إنشاء فاتورة'],en:['Sale to customer','Move between locations inside the company','Purchase from vendor','Create invoice']},answer:1,explanation:{ar:'للنقل الداخلي دون بيع أو شراء. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'For internal moves without sale or purchase. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-08',path:'inventory',order:8,title:{ar:'تعديلات المخزون',en:'Inventory Adjustments'},description:{ar:'تصحيح الفرق بين النظام والجرد الفعلي',en:'Correcting system vs physical count differences'},duration:12,xp:20,
    objectives:{ar:['متى تستخدم Adjustment','خطوات الجرد','أثر التسوية على On Hand','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['When to use Adjustment','Counting steps','Effect on On Hand','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تعديل المخزون (Inventory Adjustment) يطابق الكمية في النظام مع الجرد الفعلي. يُنشئ حركة موثّقة بدل تغيير الأرقام يدوياً بلا أثر.',en:'An Inventory Adjustment matches system quantity to the physical count. It creates a documented move instead of changing numbers with no trail.'}},
      {type:'visual',title:{ar:'مراجعة المنتج قبل التسوية',en:'Review product before adjustment'},content:{ar:'من قائمة المنتجات افتح البطاقة: سجّل On Hand قبل الجرد، نفّذ Adjustment، ثم راجع On Hand والحركة في التاريخ.',en:'From the product list open the form: note On Hand before the count, run Adjustment, then review On Hand and the move in history.'},image:'product-catalog.png',caption:{ar:'<strong>قائمة المنتجات</strong> — افتح المنتج وراجع On Hand قبل وبعد أي تسوية.',en:'<strong>Product list</strong> — open the product and review On Hand before and after any adjustment.'}},
      {type:'concept',title:{ar:'خطوات التعديل',en:'Adjustment steps'},content:{ar:'1) Inventory → Operations → Physical Inventory (أو Inventory Adjustments).\n2) اختر الموقع والمنتجات المراد جردها.\n3) أدخل الكمية الفعلية المعدودة.\n4) Apply / Validate التسوية.\n5) راجع حركة المخزون الناتجة في تاريخ المنتج.',en:'1) Inventory → Operations → Physical Inventory (or Inventory Adjustments).\n2) Choose location and products to count.\n3) Enter the actual counted quantity.\n4) Apply / Validate the adjustment.\n5) Review the resulting stock move on the product history.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'النظام يظهر 50، الجرد الفعلي 47 → Adjustment بـ 47. الفرق (3) يُسجَّل كخسارة/تسوية مع سبب إن أمكن.',en:'System shows 50, physical count 47 → Adjustment to 47. The difference (3) is recorded as loss/adjustment with a reason if possible.'}},
      {type:'why',title:{ar:'لماذا قواعد إعادة الطلب؟',en:'Why reordering rules?'},content:{ar:'حتى لا تعتمد على الذاكرة: عندما On Hand ينخفض تحت الحد يُقترح أو يُنشأ طلب شراء.',en:'So you do not rely on memory: when On Hand falls below a minimum, a purchase is suggested or created.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من منتج Storable ابحث عن Reordering Rules أو Min/Max إن وُجدت. اقرأ القيم فقط في بيئة الإنتاج.',en:'From a Storable product find Reordering Rules or Min/Max if present. Read values only in production.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اجرد بانتظام (شهري أو ربع سنوي) للمنتجات عالية القيمة حتى لا تتراكم الفروقات. راجعه على الشاشة قبل الانتقال.',en:'Count regularly (monthly or quarterly) for high-value products so differences do not accumulate. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تعديل الكميات من واجهات مخفية أو قيود يدوية بدل Adjustment — يضيع التتبع والمراجعة.',en:'Changing quantities from hidden screens or manual entries instead of Adjustment — loses traceability and audit.'}}
    ],
    knowledgeCheck:{question:{ar:'متى تفتح شاشة/عملية Inventory Adjustment؟',en:'When do you open an Inventory Adjustment screen/operation?'},options:{ar:['البيع فقط','تصحيح الفرق بين النظام والجرد الفعلي','إنشاء عميل','إرسال بريد'],en:['Selling only','Correct system vs physical difference','Create customer','Send email']},answer:1,explanation:{ar:'بعد الجرد لمطابقة الكميات مع أثر موثّق. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'After counting to match quantities with a documented trail. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-09',path:'inventory',order:9,title:{ar:'قواعد إعادة الطلب',en:'Reordering Rules'},description:{ar:'التجديد التلقائي عند انخفاض الكمية',en:'Automatic replenishment when quantity drops'},duration:12,xp:20,
    objectives:{ar:['تعريف Min و Max','ربط القاعدة بمنتج Storable','تشغيل المجدول','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Define Min and Max','Link rule to Storable product','Run the scheduler','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'قاعدة إعادة الطلب (Reordering Rule) تراقب On Hand وتقترح أو تنشئ تجديدًا (شراء أو تصنيع) عندما تنخفض الكمية عن الحد الأدنى.',en:'A Reordering Rule watches On Hand and suggests or creates replenishment (purchase or manufacture) when quantity falls below the minimum.'}},
      {type:'visual',title:{ar:'ربط القاعدة بالمنتج',en:'Linking the rule to the product'},content:{ar:'من قائمة المنتجات افتح البطاقة لمراجعة On Hand و Reserved والنوع (Storable). أي تسوية أو قاعدة إعادة طلب تبدأ من هنا.',en:'From the product list open the form to review On Hand, Reserved and type (Storable). Any adjustment or reordering rule starts here.'},image:'product-catalog.png',caption:{ar:'<strong>Storable products</strong> — قواعد إعادة الطلب تُعرَّف على منتجات من نوع Storable فقط.',en:'<strong>Storable products</strong> — reordering rules are defined only on Storable product types.'}},
      {type:'concept',title:{ar:'خطوات إعداد قاعدة',en:'Steps to set a rule'},content:{ar:'1) تأكد أن المنتج Storable.\n2) Inventory → Configuration → Reordering Rules (أو من بطاقة المنتج).\n3) Min Quantity و Max Quantity.\n4) اختر المسار (Buy أو Manufacture) إن لزم.\n5) احفظ ثم Run Scheduler أو انتظر التشغيل التلقائي.',en:'1) Ensure the product is Storable.\n2) Inventory → Configuration → Reordering Rules (or from the product form).\n3) Min Quantity and Max Quantity.\n4) Choose the route (Buy or Manufacture) if needed.\n5) Save then Run Scheduler or wait for the automatic run.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مثال: منتج حرج Min = 20 و Max = 80 على Reordering Rule. عندما On Hand على بطاقة المنتج يصل 18 يظهر مقترح شراء أو RFQ حتى 80 حسب الإعداد. افتح القاعدة من شاشة المنتج وتأكد من المستودع والمسار قبل الاعتماد في الإنتاج.',en:'Example: critical product Min = 20 and Max = 80 on a Reordering Rule. When On Hand on the product form hits 18 a purchase suggestion or RFQ up to 80 appears per settings. Open the rule from the product screen and verify warehouse and route before relying on it in production.'}},
      {type:'why',title:{ar:'لماذا الجرد؟',en:'Why inventory adjustments?'},content:{ar:'الفرق بين النظام والواقع يزداد مع الوقت. التسوية توثّق التصحيح بدل تغيير On Hand يدوياً بلا أثر.',en:'The gap between system and reality grows over time. An adjustment documents the fix instead of changing On Hand with no trail.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح منتجاً وسجّل On Hand. في بيئة تجريبية فقط جرّب Physical Inventory / Adjustment ثم راجع الرقم والحركة.',en:'Open a product and note On Hand. In a trial DB only try Physical Inventory / Adjustment then review the number and move.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ابدأ بمنتجات قليلة حرجة فقط حتى لا تمتلئ المسودات بطلبات غير ضرورية. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Start with a few critical products only so drafts are not filled with unnecessary orders. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Min أعلى من الاحتياج الفعلي — شراء زائد وتكاليف تخزين. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Min higher than real need — over-purchasing and storage cost. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'عند انخفاض On Hand تحت Min، ماذا يحدث غالباً؟',en:'When On Hand falls below Min, what often happens?'},options:{ar:['حذف منتج','اقتراح أو إنشاء تجديد','لا شيء','إغلاق مستودع'],en:['Delete product','Suggest or create replenishment','Nothing','Close warehouse']},answer:1,explanation:{ar:'يفعّل قاعدة التجديد تلقائياً. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Triggers the replenishment rule automatically. Review the lesson screen to lock in the idea.'}}},
  
  {id:'inventory-10',path:'inventory',order:10,title:{ar:'ملخص المخزون وخريطة الشاشات',en:'Inventory Summary & Screen Map'},description:{ar:'من المنتج إلى الحركات على الشاشات',en:'From product to moves on screens'},duration:12,xp:25,
    objectives:{ar:['تلخيص شاشات المخزون','ربط الاستلام والتسليم بـ On Hand'],en:['Summarize inventory screens','Link receipt and delivery to On Hand']},
    sections:[
      {type:'intro',title:{ar:'الفكرة الحاكمة',en:'Governing idea'},content:{ar:'On Hand لا يُعدَّل يدوياً في العمل اليومي: يتغيّر عبر Validate على شاشات Receipt و Delivery و Internal Transfer و Adjustment. الشاشة التي تضغط فيها Validate هي قرار المخزون.',en:'On Hand is not edited manually in daily work: it changes via Validate on Receipt, Delivery, Internal Transfer and Adjustment screens. The screen where you press Validate is the stock decision.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) Products — النوع Storable و On Hand و Reserved.\\n2) Receipt — Demand vs Done → Validate → On Hand +.\\n3) Delivery — من أمر البيع → Validate → On Hand −.\\n4) Internal Transfer — بين المواقع دون بيع/شراء.\\n5) Inventory Adjustment — عند فرق الجرد الفعلي.\\n6) Reordering Rules — Min/Max عند انخفاض الكمية.\\nالمستودع والموقع على رأس كل عملية يحددان أين تُحسب الكمية.',en:'1) Products — Storable type, On Hand and Reserved.\\n2) Receipt — Demand vs Done → Validate → On Hand +.\\n3) Delivery — from sales order → Validate → On Hand −.\\n4) Internal Transfer — between locations without buy/sell.\\n5) Inventory Adjustment — when physical count differs.\\n6) Reordering Rules — Min/Max when quantity drops.\\nWarehouse and location on each operation header decide where quantity is counted.'}},
      {type:'visual',title:{ar:'الاستلام كقرار',en:'Receipt as a decision'},content:{ar:'قبل Validate طابق البضاعة مع Done. بعده راجع On Hand على بطاقة المنتج فوراً.',en:'Before Validate match goods to Done. Afterwards review On Hand on the product form immediately.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt</strong> — Demand vs Done ثم Validate. هذا قلب المخزون التشغيلي.',en:'<strong>Receipt</strong> — Demand vs Done then Validate. This is the heart of operational inventory.'}},
      {type:'example',title:{ar:'مثال متكامل',en:'Integrated example'},content:{ar:'شراء 10 → Receipt Validate → On Hand 10. بيع 3 → Delivery Validate → On Hand 7. تحويل رف → المواقع تتغير دون تغيّر الإجمالي إن بقي في نفس المستودع حسب الإعداد.',en:'Buy 10 → Receipt Validate → On Hand 10. Sell 3 → Delivery Validate → On Hand 7. Shelf transfer → locations change without changing total if still in the same warehouse per settings.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'اكتب جدولًا: عملية | الشاشة | أثر On Hand. املأه من دروس المسار ثم طابقه مع أودو تجريبي.',en:'Write a table: operation | screen | On Hand effect. Fill it from path lessons then match with trial Odoo.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'أي رقم غريب في On Hand: ابحث عن آخر Receipt/Delivery/Adjustment على الشاشة قبل افتراض خطأ في المنتج.',en:'Any odd On Hand number: find the last Receipt/Delivery/Adjustment on screen before assuming a product error.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تعديل الكمية من بطاقة المنتج مباشرة في الإنتاج — تختفي أثر الحركات وتفشل المراجعة.',en:'Editing quantity directly on the product form in production — move history disappears and audits fail.'}}
    ],
    knowledgeCheck:{question:{ar:'ما الذي يغيّر On Hand في العمل اليومي؟',en:'What changes On Hand in daily work?'},options:{ar:['تعديل يدوي دائماً','Validate على شاشات الحركات','تغيير اسم المنتج','حذف العميل'],en:['Always manual edit','Validate on move screens','Rename product','Delete customer']},answer:1,explanation:{ar:'الحركات الموثّقة على الشاشة.',en:'Documented moves on screen.'}}},
  
  {id:'purchase-01',path:'purchase',order:1,title:{ar:'نظرة عامة على المشتريات',en:'Purchase Overview'},description:{ar:'دور تطبيق Purchase في أودو',en:'Role of the Purchase app in Odoo'},duration:12,xp:20,
    objectives:{ar:['فهم مسار الشراء الكامل','الربط مع المخزون والفواتير','التمييز بين RFQ و PO','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Understand the full purchase flow','Link to inventory and bills','Distinguish RFQ vs PO','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق Purchase يدير الطلب من المورد: طلب عرض سعر (RFQ) → أمر شراء (PO) → استلام → فاتورة مورد. كل خطوة تظهر في شاشة أودو مرتبطة بالخطوة السابقة.',en:'The Purchase app manages buying from vendors: Request for Quotation (RFQ) → Purchase Order (PO) → Receipt → Vendor Bill. Each step appears on an Odoo screen linked to the previous one.'}},
      {type:'why',title:{ar:'لماذا هذا المسار؟',en:'Why this flow?'},content:{ar:'بدون مسار منظم تضيع الطلبات ويصعب معرفة: هل طُلب؟ هل وصل؟ هل دُفع؟ الربط بين الشاشات يعطي إجابة واحدة لكل سؤال.',en:'Without a structured flow, orders get lost and it is hard to know: was it ordered? did it arrive? was it paid? Linking screens answers each question in one place.'}},
      {type:'visual',title:{ar:'نفس نمط القائمة في المشتريات',en:'Same list pattern in Purchase'},content:{ar:'قائمة أوامر الشراء تشبه قائمة عروض المبيعات: أعمدة للحالة والمورد والمبلغ. انقر سطراً لفتح النموذج. تعلّم List مرة واحدة واستخدمه في Purchase كما في Sales.',en:'The purchase order list looks like the sales quotations list: columns for status, vendor and amount. Click a row to open the form. Learn List once and use it in Purchase as in Sales.'},image:'list-view.png',caption:{ar:'<strong>List View</strong> — في Purchase أيضاً: صفوف، بحث، فلاتر، ثم فتح النموذج. لاحظ عمود الحالة (RFQ / Purchase Order).',en:'<strong>List View</strong> — in Purchase too: rows, search, filters, then open the form. Notice the status column (RFQ / Purchase Order).'}},
      {type:'concept',title:{ar:'المسار على الشاشات',en:'The flow on screens'},content:{ar:'1) Purchase → Orders → Requests for Quotation → New.\n2) اختر Vendor وأضف البنود → Save / Send.\n3) Confirm Order → تصبح Purchase Order.\n4) من الأمر أو Inventory → Receipt → Validate.\n5) من الأمر → Create Bill → Confirm → Register Payment.',en:'1) Purchase → Orders → Requests for Quotation → New.\n2) Select Vendor and add lines → Save / Send.\n3) Confirm Order → becomes Purchase Order.\n4) From the order or Inventory → Receipt → Validate.\n5) From the order → Create Bill → Confirm → Register Payment.'}},
      {type:'example',title:{ar:'مثال عملي',en:'Practical example'},content:{ar:'تحتاج 20 وحدة من منتج Storable: أنشئ RFQ لمورد واحد، أكّد، استلم عبر Receipt (On Hand +20)، ثم فاتورة مورد من نفس الأمر.',en:'You need 20 units of a Storable product: create an RFQ for one vendor, confirm, receive via Receipt (On Hand +20), then vendor bill from the same order.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Purchase → Orders → Requests for Quotation. لاحظ نفس نمط List View. حدّد عمود الحالة (RFQ / Purchase Order).',en:'Open Purchase → Orders → Requests for Quotation. Notice the same List View pattern. Identify the status column (RFQ / Purchase Order).'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ابدأ بمورد واحد ومنتج واحد حتى ترى كل الشاشات مترابطة قبل التوسع. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Start with one vendor and one product until you see all screens linked before scaling. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء استلام أو فاتورة مورد يدوياً دون أمر شراء — ينكسر الربط وتتقارير «ما طُلب مقابل ما وصل مقابل ما دُفع».',en:'Creating a receipt or vendor bill manually without a PO — links break and “ordered vs received vs paid” reports fail.'}}
    ],
    knowledgeCheck:{question:{ar:'ما ترتيب الشاشات الصحيح في مسار الشراء؟',en:'What is the correct screen order in the purchase flow?'},options:{ar:['فاتورة → استلام → RFQ','RFQ → PO → استلام → فاتورة مورد','بيع → شراء','مخزون فقط'],en:['Bill → Receipt → RFQ','RFQ → PO → Receipt → Vendor Bill','Sale → Purchase','Inventory only']},answer:1,explanation:{ar:'RFQ ثم أمر الشراء ثم الاستلام ثم فاتورة المورد.',en:'RFQ then PO then receipt then vendor bill.'}}},
  
  {id:'purchase-02',path:'purchase',order:2,title:{ar:'الموردون (Vendors)',en:'Vendors'},description:{ar:'بطاقات الموردين كـ Partners على الشاشة',en:'Vendor cards as Partners on screen'},duration:10,xp:20,
    objectives:{ar:['إنشاء مورد من القائمة','تفعيل Vendor على Partner','اختيار المورد في RFQ','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create vendor from the list','Enable Vendor on Partner','Select vendor on RFQ','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المورد Partner مثل العميل. من قائمة Vendors أو Contacts تنشئ البطاقة مرة واحدة ثم تختارها في كل RFQ — لا تكتب الاسم كنص حر.',en:'A vendor is a Partner like a customer. From the Vendors or Contacts list you create the card once then pick it on every RFQ — do not type the name as free text.'}},
      {type:'visual',title:{ar:'قائمة الموردين',en:'Vendors list'},content:{ar:'List View: صفوف للسجلات مع بحث وفلاتر. انقر صفاً لفتح Form. هذا الزوج (قائمة→نموذج) يتكرر في Sales و Purchase و Inventory.',en:'List View: rows of records with search and filters. Click a row to open Form. This pair (list→form) repeats in Sales, Purchase and Inventory.'},image:'list-view.png',caption:{ar:'<strong>Vendors list</strong> — ابحث قبل New لتفادي التكرار. البطاقة تُستخدم لاحقاً في حقل Vendor على RFQ.',en:'<strong>Vendors list</strong> — search before New to avoid duplicates. The card is later used in the Vendor field on the RFQ.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Purchase → Vendors → New (أو Contacts).\n2) Company أو Individual + الاسم والعنوان والبريد.\n3) تأكد أن Is a Vendor مفعّل.\n4) Save.\n5) عند New RFQ: اختر هذا المورد من حقل Vendor.',en:'1) Purchase → Vendors → New (or Contacts).\n2) Company or Individual + name, address, email.\n3) Ensure Is a Vendor is enabled.\n4) Save.\n5) On New RFQ: select this vendor in the Vendor field.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مورد «ABC Supplier»: أنشئ البطاقة، ثم في محاكي المشتريات أو RFQ حقيقي اختر ABC Supplier من القائمة المنسدلة.',en:'Vendor “ABC Supplier”: create the card, then in the Purchase simulator or a real RFQ pick ABC Supplier from the dropdown.'}},
      {type:'why',title:{ar:'لماذا بطاقة المورد؟',en:'Why a vendor card?'},content:{ar:'نفس فكرة العميل: بطاقة واحدة (Partner) تُختار في كل RFQ. التكرار بأسماء مختلفة يفسد تاريخ المشتريات.',en:'Same idea as the customer: one Partner card is picked on every RFQ. Duplicate names break purchase history.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'Purchase → Vendors → ابحث قبل New. إن لم يوجد المورد أنشئه مع تفعيل Is a Vendor.',en:'Purchase → Vendors → search before New. If missing, create the vendor with Is a Vendor enabled.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'بطاقة واحدة يمكن أن تكون Customer و Vendor معاً إن تعاملت مع نفس الجهة بيعاً وشراءً. راجعه على الشاشة قبل الانتقال.',en:'One card can be both Customer and Vendor if you buy from and sell to the same party. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء مورد جديد لكل طلب بنفس الاسم بتهجئة مختلفة — يتكسر تاريخ المشتريات. راجعه على الشاشة قبل الانتقال.',en:'Creating a new vendor for every order with slightly different spelling — purchase history breaks. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'حقل Vendor على شاشة RFQ يشير إلى؟',en:'The Vendor field on the RFQ screen refers to?'},options:{ar:['فاتورة فقط','Partner مع خيار Vendor','منتج','مستودع'],en:['Invoice only','Partner with Vendor option','Product','Warehouse']},answer:1,explanation:{ar:'Partner مرن للعميل والمورد. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'A flexible Partner for customer and vendor. Review the lesson screen to lock in the idea.'}}},
  
  {id:'purchase-03',path:'purchase',order:3,title:{ar:'طلب عرض السعر (RFQ)',en:'Request for Quotation (RFQ)'},description:{ar:'إنشاء وإرسال RFQ للمورد',en:'Creating and sending an RFQ to the vendor'},duration:12,xp:20,
    objectives:{ar:['إنشاء RFQ من الشاشة','إضافة بنود','Send أو Confirm'],en:['Create RFQ from the screen','Add lines','Send or Confirm']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'RFQ هو مسودة طلب شراء. شاشته تشبه عرض السعر في المبيعات: رأس (مورد، تواريخ) + بنود (منتج، كمية، سعر) + أزرار Send / Confirm.',en:'An RFQ is a draft purchase request. Its screen is like a sales quotation: header (vendor, dates) + lines (product, qty, price) + Send / Confirm buttons.'}},
      {type:'why',title:{ar:'لماذا RFQ قبل PO؟',en:'Why RFQ before PO?'},content:{ar:'عندما يكون السعر غير ثابت ترسل RFQ وتنتظر الرد. إذا كان السعر معروفاً من اتفاقية يمكنك Confirm مباشرة ليصبح أمر شراء.',en:'When the price is not fixed you send an RFQ and wait for a reply. If the price is known from an agreement you can Confirm directly to make a PO.'}},
      {type:'visual',title:{ar:'نموذج الطلب (Form)',en:'Order form'},content:{ar:'لاحظ في النموذج: حقل Vendor إلزامي، جدول البنود في الأسفل، وشريط الإجراءات أعلى الصفحة (Send by Email، Confirm Order). هذا نفس منطق Form View في كل أودو.',en:'On the form notice: required Vendor field, lines table at the bottom, and the action bar at the top (Send by Email, Confirm Order). Same Form View logic across Odoo.'},image:'quotation-form.png',caption:{ar:'<strong>Form View للطلب</strong> — رأس + بنود + إجراءات. في Purchase الحقل الرئيسي هو Vendor بدل Customer.',en:'<strong>Order Form View</strong> — header + lines + actions. In Purchase the main field is Vendor instead of Customer.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Purchase → Orders → Requests for Quotation → New.\n2) اختر Vendor من القائمة (Partner).\n3) أضف سطراً: Product، Quantity، و Unit Price إن عُرف.\n4) Save ثم Send by Email أو Print.\n5) عند الاتفاق: Confirm Order → الحالة تصبح Purchase Order.',en:'1) Purchase → Orders → Requests for Quotation → New.\n2) Select Vendor from the list (Partner).\n3) Add a line: Product, Quantity, and Unit Price if known.\n4) Save then Send by Email or Print.\n5) When agreed: Confirm Order → status becomes Purchase Order.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'50 وحدة Laptop من ABC Supplier: New RFQ → Vendor = ABC Supplier → سطر Laptop × 50 → Send. بعد الرد بالسعر Confirm.',en:'50 Laptop units from ABC Supplier: New RFQ → Vendor = ABC Supplier → line Laptop × 50 → Send. After price reply Confirm.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'استخدم محاكي المشتريات في المختبرات:\n1) Vendor = ABC Supplier\n2) Product = Laptop، Qty = 5\n3) Save ثم Confirm\nنفس التسلسل على شاشة RFQ الحقيقية.',en:'Use the Purchase simulator in Practice Labs:\n1) Vendor = ABC Supplier\n2) Product = Laptop, Qty = 5\n3) Save then Confirm\nSame sequence as on a real RFQ screen.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'استخدم محاكي المشتريات في المختبرات لتتمرن على نفس التسلسل: مورد → منتج → حفظ → تأكيد. راجعه على الشاشة قبل الانتقال.',en:'Use the Purchase simulator in Practice Labs to drill the same sequence: vendor → product → save → confirm. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Confirm بكميات أو أسعار خاطئة ثم استلام — التصحيح بعد Validate الاستلام أصعب. راجع البنود على الشاشة قبل التأكيد.',en:'Confirming with wrong quantities or prices then receiving — fixing after receipt Validate is harder. Review lines on screen before confirming.'}}
    ],
    knowledgeCheck:{question:{ar:'ماذا يحدث عند Confirm Order على RFQ؟',en:'What happens on Confirm Order for an RFQ?'},options:{ar:['يُحذف','يصبح Purchase Order','يصبح فاتورة مبيعات','لا شيء'],en:['It is deleted','It becomes a Purchase Order','It becomes a sales invoice','Nothing']},answer:1,explanation:{ar:'Confirm يحوّل RFQ إلى أمر شراء. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Confirm turns the RFQ into a purchase order. Review the lesson screen to lock in the idea.'}}},
  
  {id:'purchase-04',path:'purchase',order:4,title:{ar:'أمر الشراء والاستلام',en:'Purchase Order and Receipt'},description:{ar:'من تأكيد الأمر إلى استلام البضاعة على الشاشة',en:'From confirming the order to receiving goods on screen'},duration:14,xp:25,
    objectives:{ar:['فتح Receipt من أمر الشراء','قراءة الكميات على الشاشة','Validate وزيادة On Hand'],en:['Open Receipt from the PO','Read quantities on screen','Validate and increase On Hand']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'بعد Confirm على أمر الشراء ينشئ أودو غالباً إيصال استلام. شاشة الاستلام تعرض المنتجات والكميات المتوقع استلامها — Validate ينقل الكمية إلى On Hand.',en:'After Confirm on the purchase order, Odoo often creates a receipt. The receipt screen shows products and expected quantities — Validate moves quantity into On Hand.'}},
      {type:'why',title:{ar:'لماذا من أمر الشراء؟',en:'Why from the purchase order?'},content:{ar:'الزر الذكي Receipt على أمر الشراء يفتح الشاشة المرتبطة مباشرة. هكذا تعرف أن هذا الاستلام يتبع هذا الطلب وليس استلاماً يتيماً.',en:'The Receipt smart button on the purchase order opens the linked screen directly. You know this receipt belongs to this order, not an orphan receipt.'}},
      {type:'visual',title:{ar:'شاشة الاستلام',en:'Receipt screen'},content:{ar:'في النموذج: المورد/المصدر، موقع الوجهة، وجدول المنتجات مع أعمدة Demand و Done. قبل Validate ضع الكمية الفعلية في Done.',en:'On the form: vendor/source, destination location, and a product table with Demand and Done columns. Before Validate put the actual quantity in Done.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt form</strong> — راجع Demand مقابل Done. لا Validate لكمية لم تصل. بعد Validate تصبح الحالة Done.',en:'<strong>Receipt form</strong> — review Demand vs Done. Do not Validate a quantity that did not arrive. After Validate status becomes Done.'}},
      {type:'visual',title:{ar:'بعد Validate',en:'After Validate'},content:{ar:'بعد Validate تصبح العملية Done ويتحدّث On Hand. نفس المنطق في الاستلام والتسليم والتحويل الداخلي.',en:'After Validate the operation becomes Done and On Hand updates. Same logic for receipt, delivery and internal transfer.'},image:'receipt-done.png',caption:{ar:'<strong>Done</strong> — الاستلام المكتمل يحدّث On Hand ويرتبط بأمر الشراء في التاريخ.',en:'<strong>Done</strong> — completed receipt updates On Hand and stays linked to the PO in history.'}},
      {type:'concept',title:{ar:'خطوات على الشاشات',en:'On-screen steps'},content:{ar:'1) افتح Purchase Order المؤكد.\n2) اضغط Receipt (زر ذكي) أو Inventory → Operations → Receipts.\n3) راجع المنتجات؛ عدّل Done إن كان الاستلام جزئياً.\n4) Validate.\n5) ارجع لأمر الشراء: حالة الاستلام محدّثة، وOn Hand زاد.',en:'1) Open the confirmed Purchase Order.\n2) Click Receipt (smart button) or Inventory → Operations → Receipts.\n3) Review products; adjust Done if partial receipt.\n4) Validate.\n5) Return to the PO: receipt status updated, On Hand increased.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'PO لـ 10 وحدات، وصل 7 فقط: ضع 7 في Done و Validate. المتبقي 3 يبقى معلقاً لاستلام لاحق أو إلغاء.',en:'PO for 10 units, only 7 arrived: put 7 in Done and Validate. Remaining 3 stays pending for a later receipt or cancellation.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على شاشة Receipt: ابحث عن أعمدة Demand و Done وموقع الوجهة. في بيئة تجريبية فقط نفّذ Validate بعد مطابقة الكمية الفعلية.',en:'On the Receipt screen: find the Demand and Done columns and destination location. In a trial DB only, Validate after matching the physical quantity.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'طابق البضاعة على الشاشة مع إذن التسليم الفعلي قبل Validate — أسهل من Reverse لاحقاً.',en:'Match goods on screen with the physical delivery note before Validate — easier than Reverse later.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Validate لكامل الكمية قبل وصولها → مخزون وهمي وتقارير مضللة. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Validating the full quantity before arrival → phantom stock and misleading reports. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد Validate على Receipt مرتبط بـ PO، ماذا يحدث؟',en:'After Validate on a Receipt linked to a PO, what happens?'},options:{ar:['تنقص الكمية','تزداد On Hand','فاتورة مبيعات','لا شيء'],en:['Quantity decreases','On Hand increases','Sales invoice','Nothing']},answer:1,explanation:{ar:'الاستلام يزيد المخزون. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Receipt increases stock. Review the lesson screen to lock in the idea.'}}},
  
  {id:'purchase-05',path:'purchase',order:5,title:{ar:'فاتورة المورد (Vendor Bill)',en:'Vendor Bill'},description:{ar:'تسجيل فاتورة المورد من أمر الشراء',en:'Recording the vendor bill from the purchase order'},duration:12,xp:20,
    objectives:{ar:['إنشاء فاتورة مورد من PO','حالات الفاتورة','الربط مع الاستلام','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Create vendor bill from PO','Bill statuses','Link with receipt','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'فاتورة المورد (Vendor Bill) تسجّل ما يطالب به المورد. الأفضل إنشاؤها من أمر الشراء لتنسخ البنود وتحافظ على الربط.',en:'A Vendor Bill records what the vendor charges. Best created from the purchase order so lines are copied and the link is kept.'}},
      {type:'visual',title:{ar:'من الأمر إلى المستند المالي',en:'From order to financial document'},content:{ar:'بعد Confirm تظهر أزرار ذكية على أمر البيع: Delivery و Create Invoice. أكمل المسار من نفس الشاشة لا من قوائم منفصلة.',en:'After Confirm, smart buttons appear on the sales order: Delivery and Create Invoice. Continue the flow from the same screen, not separate menus.'},image:'sales-order.png',caption:{ar:'<strong>من الأمر</strong> — أنشئ الفاتورة من أمر الشراء لا يدوياً من الصفر.',en:'<strong>From the order</strong> — create the bill from the PO, not manually from scratch.'}},
      {type:'concept',title:{ar:'خطوات فاتورة المورد',en:'Vendor bill steps'},content:{ar:'خطوات على الشاشات:\n1) افتح Purchase Order المؤكد.\n2) Create Bill — تُنسخ البنود تلقائياً.\n3) راجع الكمية والسعر والضريبة على المسودة.\n4) يُفضَّل Validate الاستلام أولاً حسب السياسة.\n5) Confirm → Posted.\n6) Register Payment (المبلغ + Bank/Cash) حتى Paid.',en:'Steps across screens:\n1) Open the confirmed Purchase Order.\n2) Create Bill — lines are copied automatically.\n3) Review qty, price and tax on the draft.\n4) Prefer receipt Validate first per policy.\n5) Confirm → Posted.\n6) Register Payment (amount + Bank/Cash) until Paid.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'مثال مسار كامل على الشاشات: PO لـ 10 وحدات → Receipt Validate → من نفس PO: Create Bill → راجع الكمية والمبلغ → Confirm → Register Payment. لا إعادة إدخال للبنود — الربط يحفظ التتبع.',en:'Full on-screen flow example: PO for 10 units → Receipt Validate → from the same PO: Create Bill → review qty and amount → Confirm → Register Payment. No re-entry of lines — the link preserves traceability.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'تخيّل المسار على الشاشات: RFQ → Confirm → Receipt Validate → Create Bill. حدّد أين يظهر كل زر دون تنفيذ في الإنتاج.',en:'Imagine the flow on screens: RFQ → Confirm → Receipt Validate → Create Bill. Locate where each button appears without running it in production.'}},
      {type:'why',title:{ar:'لماذا فاتورة المورد من الأمر؟',en:'Why vendor bill from the order?'},content:{ar:'Create Bill من PO يحافظ على الكميات والأسعار والربط المحاسبي. الفاتورة المنفصلة تكرر الإدخال وتزيد الخطأ.',en:'Create Bill from the PO keeps quantities, prices and the accounting link. A standalone bill re-enters data and increases error.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'في سياسات بعض الشركات لا تُعتمد الفاتورة إلا بعد Validate الاستلام (3-way matching). راجعه على الشاشة قبل الانتقال.',en:'In some company policies the bill is approved only after receipt Validate (3-way matching). Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'فاتورة يدوية بمبالغ مختلفة عن أمر الشراء دون سبب — صعوبة المطابقة لاحقاً. راجعه على الشاشة قبل الانتقال.',en:'Manual bill with amounts different from the PO without reason — hard to match later. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'من أي شاشة يُفضَّل Create Bill للمورد؟',en:'From which screen is Create Bill preferred for the vendor?'},options:{ar:['من الصفر دائماً','من أمر الشراء (Create Bill)','من المبيعات','حذف الأمر'],en:['Always from scratch','From the purchase order (Create Bill)','From Sales','Delete the order']},answer:1,explanation:{ar:'من أمر الشراء يحافظ على الربط والكميات. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'From the PO keeps links and quantities. Review the lesson screen to lock in the idea.'}}},
  {id:'purchase-06',path:'purchase',order:6,title:{ar:'ملخص المشتريات وخريطة الشاشات',en:'Purchase Summary & Screen Map'},description:{ar:'من RFQ إلى الدفع على الشاشات',en:'From RFQ to payment on screens'},duration:10,xp:20,
    objectives:{ar:['تلخيص مسار الشراء','ربط PO بالاستلام والفاتورة'],en:['Summarize purchase flow','Link PO to receipt and bill']},
    sections:[
      {type:'intro',title:{ar:'المسار',en:'The flow'},content:{ar:'المشتريات في أودو سلسلة شاشات: Vendor → RFQ → Confirm (PO) → Receipt Validate → Vendor Bill → Payment. كل حلقة تُغلق على الشاشة لا في البريد فقط.',en:'Purchasing in Odoo is a chain of screens: Vendor → RFQ → Confirm (PO) → Receipt Validate → Vendor Bill → Payment. Each link closes on screen, not only in email.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) Vendors / Contacts — بطاقة المورد (Partner).\\n2) RFQ — Form: Vendor + بنود.\\n3) Confirm Order → Purchase Order.\\n4) Receipt من الأمر — Done ثم Validate → On Hand +.\\n5) Create Bill من PO → Confirm → Posted.\\n6) Register Payment → Paid.\\nلا تنشئ استلاماً أو فاتورة يتيمة إن وُجد الأمر.',en:'1) Vendors / Contacts — vendor card (Partner).\\n2) RFQ — Form: Vendor + lines.\\n3) Confirm Order → Purchase Order.\\n4) Receipt from the order — Done then Validate → On Hand +.\\n5) Create Bill from PO → Confirm → Posted.\\n6) Register Payment → Paid.\\nDo not create an orphan receipt or bill if the order exists.'}},
      {type:'visual',title:{ar:'الاستلام من الشراء',en:'Receipt from purchase'},content:{ar:'الزر الذكي Receipt على أمر الشراء يفتح الشاشة المرتبطة. Demand vs Done قبل Validate.',en:'The Receipt smart button on the purchase order opens the linked screen. Demand vs Done before Validate.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt من PO</strong> — الربط يحفظ تتبع «ما طُلب / ما وصل / ما دُفع».',en:'<strong>Receipt from PO</strong> — the link preserves “ordered / received / paid” tracking.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'RFQ لـ 20 وحدة → Confirm → استلام 20 → Bill → Payment. التقارير تطابق الكميات عبر الشاشات.',en:'RFQ for 20 units → Confirm → receive 20 → Bill → Payment. Reports match quantities across screens.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'استخدم محاكي المشتريات: Vendor → منتج → Save → Confirm. طابق الخطوات مع شاشة RFQ الحقيقية.',en:'Use the Purchase simulator: Vendor → product → Save → Confirm. Match the steps to a real RFQ screen.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'استلام جزئي: Done أقل من Demand ثم Validate — المتبقي يظهر لاستلام لاحق.',en:'Partial receipt: Done less than Demand then Validate — remainder stays for a later receipt.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'فاتورة مورد من قائمة الفواتير مع تجاهل PO — تتكرر البنود ويفقد الربط.',en:'Vendor bill from the bill list ignoring the PO — lines are retyped and the link is lost.'}}
    ],
    knowledgeCheck:{question:{ar:'ترتيب شاشات الشراء الصحيح؟',en:'Correct purchase screen order?'},options:{ar:['فاتورة → RFQ','RFQ → PO → Receipt → Bill → Payment','بيع → إجازة','BOM → HR'],en:['Bill → RFQ','RFQ → PO → Receipt → Bill → Payment','Sale → Time off','BOM → HR']},answer:1,explanation:{ar:'من الطلب إلى الدفع عبر الاستلام والفاتورة.',en:'From request to payment via receipt and bill.'}}},
  
  {id:'accounting-01',path:'accounting',order:1,title:{ar:'نظرة عامة على المحاسبة في أودو',en:'Accounting Overview in Odoo'},description:{ar:'دور الفوترة وربطها بشاشات المبيعات والشراء',en:'Role of invoicing linked to sales and purchase screens'},duration:12,xp:20,
    objectives:{ar:['تدفق المال على الشاشات','SO/PO → فاتورة','Draft → Posted → Paid','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Money flow on screens','SO/PO → invoice','Draft → Posted → Paid','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المحاسبة في أودو لا تبدأ من ورقة بيضاء: تبدأ من شاشة أمر بيع أو أمر شراء. الفاتورة امتداد لتلك الشاشة، والدفع يغلق حالتها.',en:'Accounting in Odoo does not start from a blank page: it starts from a sales or purchase order screen. The invoice extends that screen, and payment closes its status.'}},
      {type:'why',title:{ar:'لماذا الربط بالشاشات؟',en:'Why link the screens?'},content:{ar:'عندما تنشئ الفاتورة من الأمر، كل رقم على شاشة الفاتورة يمكن تتبعه إلى بند البيع أو الشراء. هذا أساس المراجعة والمطابقة.',en:'When you create the invoice from the order, every number on the invoice screen can be traced to a sales or purchase line. That is the basis of audit and matching.'}},
      {type:'visual',title:{ar:'أمر البيع كمصدر للفاتورة',en:'Sales order as invoice source'},content:{ar:'بعد تأكيد أمر البيع تظهر إجراءات الفاتورة والتوصيل على نفس الشاشة. المحاسبة هنا «زر» على شاشة العمليات وليست عالماً منفصلاً.',en:'After confirming the sales order, invoice and delivery actions appear on the same screen. Accounting here is a “button” on the operations screen, not a separate world.'},image:'sales-order.png',caption:{ar:'<strong>Sales Order</strong> — Create Invoice من هنا. نفس الفكرة في Purchase مع Create Bill.',en:'<strong>Sales Order</strong> — Create Invoice from here. Same idea in Purchase with Create Bill.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) مبيعات: Quotation → Sales Order → Customer Invoice → Payment.\n2) مشتريات: RFQ → PO → Vendor Bill → Payment.\n3) على شاشة الفاتورة راقب الحالة: Draft → Posted → Paid.\n4) لا Confirm (ترحيل) قبل مراجعة البنود والضرائب على الشاشة.',en:'1) Sales: Quotation → Sales Order → Customer Invoice → Payment.\n2) Purchases: RFQ → PO → Vendor Bill → Payment.\n3) On the invoice screen watch status: Draft → Posted → Paid.\n4) Do not Confirm (post) before reviewing lines and taxes on screen.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'بيع Laptop: أكّد أمر البيع من شاشة Sales، Create Invoice، راجع الضريبة، Confirm، ثم Register Payment عند التحويل البنكي.',en:'Laptop sale: confirm the sales order on the Sales screen, Create Invoice, review tax, Confirm, then Register Payment when the bank transfer arrives.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أمر بيع مؤكد (أو صورة sales-order): ابحث بصرياً عن Create Invoice و Delivery. المحاسبة تبدأ من هذه الأزرار الذكية.',en:'On a confirmed sales order (or the sales-order image): visually find Create Invoice and Delivery. Accounting starts from these smart buttons.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'أتقن شاشات Sales و Purchase أولاً؛ المحاسبة تصبح امتداداً طبيعياً لهما.',en:'Master Sales and Purchase screens first; accounting becomes a natural extension of them.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'فتح Accounting وإنشاء فاتورة من الصفر لكل عملية — تفقد الربط مع الأمر والشاشات السابقة.',en:'Opening Accounting and creating an invoice from scratch for every deal — you lose the link to the order and previous screens.'}}
    ],
    knowledgeCheck:{question:{ar:'على شاشة الفاتورة، ما تسلسل الحالات الرئيسي؟',en:'On the invoice screen, what is the main status sequence?'},options:{ar:['Open فقط','Draft → Posted → Paid','New → Old','لا حالات'],en:['Open only','Draft → Posted → Paid','New → Old','No statuses']},answer:1,explanation:{ar:'Draft ثم Posted ثم Paid. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'Draft then Posted then Paid. Review the lesson screen to lock in the idea.'}}},
  
  {id:'accounting-02',path:'accounting',order:2,title:{ar:'فاتورة العميل',en:'Customer Invoice'},description:{ar:'إنشاء وترحيل فاتورة العميل من أمر البيع على الشاشة',en:'Create and post a customer invoice from the sales order on screen'},duration:12,xp:20,
    objectives:{ar:['Create Invoice من أمر البيع','مراجعة المسودة على الشاشة','Confirm → Posted'],en:['Create Invoice from SO','Review draft on screen','Confirm → Posted']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'فاتورة العميل تُنشأ من شاشة أمر البيع المؤكد. أودو ينسخ البنود والكميات والضرائب — مهمتك المراجعة ثم Confirm.',en:'A customer invoice is created from the confirmed sales order screen. Odoo copies lines, quantities and taxes — your job is to review then Confirm.'}},
      {type:'why',title:{ar:'لماذا من أمر البيع؟',en:'Why from the sales order?'},content:{ar:'الزر الذكي Create Invoice يفتح مسودة مربوطة بالأمر. التقارير تعرف أي إيراد يتبع أي بيع، وتتجنب الفواتير المكررة.',en:'The Create Invoice smart button opens a draft linked to the order. Reports know which revenue follows which sale, and duplicate invoices are avoided.'}},
      {type:'visual',title:{ar:'أمر البيع — نقطة الإنشاء',en:'Sales order — creation point'},content:{ar:'بعد Confirm تظهر أزرار ذكية أعلى أو بجانب النموذج: Create Invoice، Delivery. اضغط Create Invoice وراجع المسودة قبل الترحيل.',en:'After Confirm, smart buttons appear on the form: Create Invoice, Delivery. Click Create Invoice and review the draft before posting.'},image:'sales-order.png',caption:{ar:'<strong>Sales Order</strong> — ابحث عن Create Invoice على نفس الشاشة. لا تبدأ فاتورة من Accounting من الصفر إن وُجد أمر بيع.',en:'<strong>Sales Order</strong> — look for Create Invoice on the same screen. Do not start an invoice from Accounting from scratch if a sales order exists.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) افتح Sales Order بحالة Sale Order / Confirmed.\n2) Create Invoice (اختر الكميات إلى الفاتورة إن طُلب).\n3) راجع المسودة: بنود، ضرائب، حسابات، عملة.\n4) Confirm → الحالة Posted.\n5) عند الدفع: Register Payment → حتى Paid.',en:'1) Open Sales Order in Sale Order / Confirmed status.\n2) Create Invoice (choose quantities to invoice if asked).\n3) Review the draft: lines, taxes, accounts, currency.\n4) Confirm → status Posted.\n5) On payment: Register Payment → until Paid.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'أمر 10 وحدات، سُلّم 5: من Create Invoice اختر 5 فقط (فوترة جزئية). الشاشة تعرض الكمية المتبقية للفوترة لاحقاً.',en:'Order of 10 units, 5 delivered: in Create Invoice choose only 5 (partial invoicing). The screen shows remaining quantity to invoice later.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أمر بيع مؤكد: اعثر على Create Invoice دون مغادرة الشاشة. في بيئة تجريبية أنشئ المسودة وراجع البنود والضريبة قبل Confirm.',en:'On a confirmed sales order: find Create Invoice without leaving the screen. In a trial DB create the draft and review lines and tax before Confirm.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'قبل Confirm راجع الضريبة والعملة على الشاشة — التعديل بعد Posted يتطلب قيود تسوية أو عكس.',en:'Before Confirm review tax and currency on screen — changes after Posted need adjustment entries or reverse.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'فاتورة يدوية من قائمة الفواتير مع تجاهل أمر البيع → بنود مختلفة وربط مفقود. راجعه على الشاشة قبل الانتقال.',en:'Manual invoice from the invoice list ignoring the sales order → different lines and missing link. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'من أي شاشة يُفضَّل إنشاء فاتورة العميل؟',en:'From which screen is it best to create a customer invoice?'},options:{ar:['من الصفر دائماً','من أمر البيع (Create Invoice)','من المخزون فقط','من CRM فقط'],en:['Always from scratch','From the sales order (Create Invoice)','From inventory only','From CRM only']},answer:1,explanation:{ar:'من أمر البيع يحافظ على الربط. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'From the sales order keeps the link. Review the lesson screen to lock in the idea.'}}},
  
  {id:'accounting-03',path:'accounting',order:3,title:{ar:'فاتورة المورد والمدفوعات',en:'Vendor Bill and Payments'},description:{ar:'من شاشة أمر الشراء إلى الدفع',en:'From the purchase order screen to payment'},duration:12,xp:20,
    objectives:{ar:['Create Bill من PO','Register Payment على الشاشة','الوصول لحالة Paid'],en:['Create Bill from PO','Register Payment on screen','Reach Paid status']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'فاتورة المورد تُنشأ من شاشة أمر الشراء (Create Bill) فتُنسخ البنود. بعد Confirm → Posted. الدفع من نفس الشاشة: Register Payment (مبلغ + دفتر يومية) حتى Paid. هذا التسلسل هو ما يجب أن تتقنه على الواجهة قبل أي قيد يدوي.',en:'The vendor bill is created from the purchase order screen (Create Bill) so lines are copied. After Confirm → Posted. Payment from the same screen: Register Payment (amount + journal) until Paid. Master this sequence on the UI before any manual journal entry.'}},
      {type:'visual',title:{ar:'الاستلام قبل اعتماد الفاتورة',en:'Receipt before approving the bill'},content:{ar:'في سياسات كثيرة يُفضَّل Validate الاستلام (شاشة Receipt) قبل Confirm على فاتورة المورد — مطابقة الكمية مع الفاتورة.',en:'In many policies, Validate the receipt (Receipt screen) before Confirm on the vendor bill — matching quantity to the bill.'},image:'receipt-form.png',caption:{ar:'<strong>Receipt</strong> — وثّق الوصول على الشاشة قبل دفع المورد. Demand vs Done يجب أن يطابقا الواقع.',en:'<strong>Receipt</strong> — document arrival on screen before paying the vendor. Demand vs Done must match reality.'}},
      {type:'concept',title:{ar:'خطوات الدفع على الشاشة',en:'Payment steps on screen'},content:{ar:'1) من Purchase Order → Create Bill (أو من فاتورة المورد المسودة).\n2) راجع البنود والمبالغ → Confirm (Posted).\n3) زر Register Payment على شاشة الفاتورة.\n4) المبلغ، التاريخ، دفتر اليومية (بنك/صندوق) → Validate.\n5) عند اكتمال المبلغ: الحالة Paid.',en:'1) From Purchase Order → Create Bill (or from the draft vendor bill).\n2) Review lines and amounts → Confirm (Posted).\n3) Register Payment button on the bill screen.\n4) Amount, date, journal (Bank/Cash) → Validate.\n5) When amount is complete: status Paid.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'فاتورة مورد 1000: دفعة 400 ثم 600 من شاشة Register Payment — الفاتورة تبقى Open/Partial ثم Paid.',en:'Vendor bill 1000: pay 400 then 600 from the Register Payment screen — bill stays Open/Partial then Paid.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'تسلسل الشاشات: PO → Receipt Validate → Create Bill → Register Payment. حدّد كل زر على الشاشة المناسبة قبل التنفيذ في الإنتاج.',en:'Screen sequence: PO → Receipt Validate → Create Bill → Register Payment. Locate each button on the right screen before running in production.'}},
      {type:'why',title:{ar:'لماذا الربط بأمر الشراء؟',en:'Why link to the purchase order?'},content:{ar:'Create Bill من PO ينسخ البنود ويربط الدفع بالطلب. الفاتورة المنفصلة تصعّب المطابقة عند المراجعة.',en:'Create Bill from the PO copies lines and links payment to the order. A standalone bill makes matching harder at audit time.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'سمِّ دفاتر اليومية بوضوح (Bank، Cash) لتظهر بشكل مفهوم في شاشة الدفع والتقارير.',en:'Name journals clearly (Bank, Cash) so they appear clearly on the payment screen and in reports.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تسجيل دفعة عامة دون فتح الفاتورة وربطها — التسوية البنكية تصبح صعبة. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Recording a generic payment without opening and linking the bill — bank reconciliation becomes hard. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'متى تصبح حالة الفاتورة Paid على الشاشة؟',en:'When does invoice status become Paid on screen?'},options:{ar:['عند الإنشاء','عند اكتمال تسجيل الدفع','عند الحذف','عند الاستلام فقط'],en:['On creation','When payment registration is complete','On delete','On receipt only']},answer:1,explanation:{ar:'بعد تسجيل الدفع بالكامل. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'After full payment is registered. Review the lesson screen to lock in the idea.'}}},
  
  {id:'accounting-04',path:'accounting',order:4,title:{ar:'الضرائب والتقارير الأساسية',en:'Taxes and Basic Reports'},description:{ar:'الضرائب على الفواتير وأهم ما تراجعه على الشاشة',en:'Taxes on invoices and what to review on screen'},duration:12,xp:20,
    objectives:{ar:['أين تُضبط الضريبة','قراءتها على بند الفاتورة','فكرة تقرير الفواتير','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Where tax is set','Reading it on invoice lines','Idea of invoice reports','Identify on-screen elements and apply the steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الضريبة تُعرَّف في الإعدادات أو على المنتج، ثم تظهر على كل بند في شاشة العرض/الأمر/الفاتورة. التقارير تلخّص الفواتير المرحّلة والمدفوعة.',en:'Tax is defined in settings or on the product, then appears on each line of the quotation/order/invoice screen. Reports summarize posted and paid invoices.'}},
      {type:'why',title:{ar:'لماذا المراجعة على الشاشة؟',en:'Why review on screen?'},content:{ar:'خطأ نسبة ضريبة واحد يتكرر على كل الفواتير. دقيقة واحدة على شاشة البند قبل Confirm أرخص من تصحيح إقرار ضريبي.',en:'One wrong tax rate repeats on every invoice. One minute on the line screen before Confirm is cheaper than fixing a tax return.'}},
      {type:'visual',title:{ar:'البنود والأسعار على النموذج',en:'Lines and prices on the form'},content:{ar:'في جدول البنود: المنتج، الكمية، السعر، وعمود أو حقل للضريبة. تأكد أن الضريبة الصحيحة مختارة قبل Send أو Confirm.',en:'In the lines table: product, quantity, price, and a tax column or field. Ensure the correct tax is selected before Send or Confirm.'},image:'quotation-form.png',caption:{ar:'<strong>جدول البنود</strong> — راجع Product، Quantity، Price، Tax على الشاشة قبل أي تأكيد.',en:'<strong>Lines table</strong> — review Product, Quantity, Price, Tax on screen before any confirmation.'}},
      {type:'concept',title:{ar:'خطوات عملية',en:'Practical steps'},content:{ar:'1) Accounting/Invoicing → Configuration → Taxes (تعريف النسب).\n2) على المنتج أو الشركة اضبط الضريبة الافتراضية.\n3) عند إنشاء عرض أو أمر راجع عمود الضريبة في البنود.\n4) بعد الفوترة استخدم تقارير الفواتير لمراجعة Posted / Paid.\n5) لا تغيّر نسب قديمة بأثر رجعي دون خطة محاسبية.',en:'1) Accounting/Invoicing → Configuration → Taxes (define rates).\n2) Set default tax on the product or company.\n3) When creating a quote or order review the tax column on lines.\n4) After invoicing use invoice reports to review Posted / Paid.\n5) Do not change old rates retroactively without an accounting plan.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'منتج بسعر 100 وضريبة 15%: على شاشة الفاتورة يظهر المبلغ قبل الضريبة 100 والضريبة 15 والإجمالي 115 — راجع هذه الأرقام قبل Confirm.',en:'Product price 100 with 15% tax: on the invoice screen subtotal 100, tax 15, total 115 — review these numbers before Confirm.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أي عرض سعر أو فاتورة مسودة: راجع عمود أو حقل Tax في البنود قبل Confirm. سجّل النسبة الظاهرة.',en:'On any quotation or draft invoice: review the Tax column or field on lines before Confirm. Note the rate shown.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اختبر فاتورة واحدة في قاعدة تجريبية بعد أي تغيير على الضرائب. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Test one invoice on a trial database after any tax change. Apply it directly on the screen before moving to the next lesson.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك حقل الضريبة فارغاً على المنتج ثم اكتشاف الفروقات عند الإقرار. طبّق ذلك مباشرة على الشاشة قبل الانتقال للدرس التالي.',en:'Leaving the tax field empty on the product then discovering differences at filing time. Apply it directly on the screen before moving to the next lesson.'}}
    ],
    knowledgeCheck:{question:{ar:'من أي شاشات تُعرَّف الضرائب عادة؟',en:'From which screens are taxes usually defined?'},options:{ar:['في CRM فقط','Configuration → Taxes أو على المنتج','في المستودع','لا تُعرَّف'],en:['In CRM only','Configuration → Taxes or on the product','In the warehouse','Not defined']},answer:1,explanation:{ar:'من الإعدادات أو بطاقة المنتج. راجع الشاشة في الدرس لتثبيت المفهوم.',en:'From settings or the product form. Review the lesson screen to lock in the idea.'}}},
  
  {id:'accounting-05',path:'accounting',order:5,title:{ar:'ملخص المحاسبة وخريطة الشاشات',en:'Accounting Summary & Screen Map'},description:{ar:'من الأمر إلى Paid على الشاشات',en:'From order to Paid on screens'},duration:10,xp:20,
    objectives:{ar:['تلخيص الفوترة','ربط SO/PO بالدفع'],en:['Summarize invoicing','Link SO/PO to payment']},
    sections:[
      {type:'intro',title:{ar:'المحاسبة من الشاشات التشغيلية',en:'Accounting from operational screens'},content:{ar:'في أودو التعليمي العملي: الفاتورة امتداد لأمر البيع أو الشراء. الحالات على شاشة الفاتورة: Draft → Posted → Paid. الدفع من Register Payment لا من ورقة خارجية.',en:'In practical Odoo learning: the invoice extends the sales or purchase order. Statuses on the invoice screen: Draft → Posted → Paid. Payment via Register Payment, not an external sheet.'}},
      {type:'concept',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) من Sales Order: Create Invoice → راجع البنود والضريبة → Confirm (Posted).\\n2) من Purchase Order: Create Bill → Confirm.\\n3) Register Payment: المبلغ + التاريخ + Journal (Bank/Cash).\\n4) عند اكتمال المبلغ: Paid.\\n5) الضرائب: Configuration → Taxes أو على المنتج — تظهر على البنود قبل Confirm.\\nلا ترحّل قبل مراجعة الشاشة.',en:'1) From Sales Order: Create Invoice → review lines and tax → Confirm (Posted).\\n2) From Purchase Order: Create Bill → Confirm.\\n3) Register Payment: amount + date + Journal (Bank/Cash).\\n4) When amount is complete: Paid.\\n5) Taxes: Configuration → Taxes or on the product — appear on lines before Confirm.\\nDo not post before reviewing the screen.'}},
      {type:'visual',title:{ar:'من أين تُنشأ الفاتورة؟',en:'Where is the invoice created?'},content:{ar:'الزر الذكي على أمر البيع/الشراء. المحاسبة هنا زر على شاشة العمليات.',en:'The smart button on the sales/purchase order. Accounting here is a button on the operations screen.'},image:'sales-order.png',caption:{ar:'<strong>Create Invoice</strong> — من أمر البيع. نفس الفكرة Create Bill من أمر الشراء.',en:'<strong>Create Invoice</strong> — from the sales order. Same idea: Create Bill from the purchase order.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'أمر بيع مؤكد → Create Invoice → Confirm → Register Payment كامل → Paid. الأمر يظهر مفوتراً بالكامل.',en:'Confirmed sales order → Create Invoice → Confirm → full Register Payment → Paid. The order shows fully invoiced.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أمر بيع تجريبي: حدد مكان Create Invoice دون ترحيل في الإنتاج. اقرأ الحالة Draft قبل أي Confirm.',en:'On a trial sales order: locate Create Invoice without posting in production. Read Draft status before any Confirm.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'دفعة جزئية مسموحة: سجل المبلغ المتاح؛ تبقى الفاتورة مفتوحة حتى اكتمال Paid.',en:'Partial payment is allowed: register the available amount; the invoice stays open until full Paid.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترحيل فاتورة بضريبة خاطئة ثم اكتشاف الخطأ عند الإقرار — صحّح على الشاشة قبل Confirm.',en:'Posting an invoice with wrong tax then discovering it at filing — correct on screen before Confirm.'}}
    ],
    knowledgeCheck:{question:{ar:'تسلسل حالات الفاتورة على الشاشة؟',en:'Invoice status sequence on screen?'},options:{ar:['Paid → Draft','Draft → Posted → Paid','BOM → Done','Lead → Won فقط'],en:['Paid → Draft','Draft → Posted → Paid','BOM → Done','Lead → Won only']},answer:1,explanation:{ar:'مسودة ثم مرحّلة ثم مدفوعة.',en:'Draft then posted then paid.'}}},
  
  {id:'manufacturing-01',path:'manufacturing',order:1,title:{ar:'نظرة عامة على التصنيع',en:'Manufacturing Overview'},description:{ar:'دور تطبيق Manufacturing وربطه بالمخزون على الشاشات',en:'Manufacturing app linked to inventory on screens'},duration:14,xp:25,
    objectives:{ar:['فهم مسار التصنيع على الشاشات','الربط مع المنتج والمخزون','تمييز BOM و أمر التصنيع','تمييز العناصر على الشاشة وتطبيق الخطوات'],en:['Understand manufacturing flow on screens','Link to product and inventory','Distinguish BOM and MO','Identify on-screen elements and apply steps']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق Manufacturing يحوّل المواد الخام إلى منتج نهائي مع توثيق على الشاشة. المسار الأساسي: قائمة مواد (BOM) → أمر تصنيع (MO) → استهلاك مكوّنات → إنتاج كمية تدخل On Hand للمنتج النهائي. كل خطوة شاشة مستقلة ومرتبطة بالتي قبلها.',en:'The Manufacturing app turns raw materials into finished goods with on-screen documentation. Core flow: Bill of Materials (BOM) → Manufacturing Order (MO) → consume components → produce quantity into finished On Hand. Each step is its own screen linked to the previous one.'}},
      {type:'why',title:{ar:'لماذا التصنيع داخل أودو؟',en:'Why manufacturing inside Odoo?'},content:{ar:'لأن الكمية المنتجة والمستهلكة تُسجَّل على الشاشة وترتبط بالمخزون تلقائياً. جداول Excel الخارجية لا تحدّث On Hand ولا تظهر نقص المواد قبل التنفيذ. الهدف التعليمي: أن ترى نفس الرقم في الأمر وفي بطاقة المنتج.',en:'Because produced and consumed quantities are recorded on screen and update stock automatically. External Excel sheets neither update On Hand nor show shortages before execution. Learning goal: see the same number on the order and on the product form.'}},
      {type:'visual',title:{ar:'قائمة أوامر التصنيع',en:'Manufacturing orders list'},content:{ar:'نفس نمط List في المبيعات والمشتريات: صفوف للأوامر، بحث، فلاتر، وعمود الحالة. انقر سطراً لفتح Form الأمر. تعلّم هذا الزوج مرة واحدة في التصنيع كما في Sales.',en:'Same List pattern as sales and purchase: order rows, search, filters, and a status column. Click a row to open the order Form. Learn this pair once in manufacturing as in Sales.'},image:'list-view.png',caption:{ar:'<strong>List View — Manufacturing Orders</strong> — الحالة (Draft / Confirmed / Done) في عمود. New لإنشاء أمر جديد.',en:'<strong>List View — Manufacturing Orders</strong> — status (Draft / Confirmed / Done) in a column. New to create an order.'}},
      {type:'concept',title:{ar:'المسار على الشاشات',en:'Flow on screens'},content:{ar:'1) عرّف منتجاً نهائياً ومكوّنات من نوع Storable.\\n2) Manufacturing → Bills of Materials → New: المنتج + أسطر المكونات والكميات.\\n3) Operations → Manufacturing Orders → New: المنتج والكمية.\\n4) Confirm — تظهر المكونات من الـ BOM.\\n5) عند التنفيذ: Produce / Mark as Done.\\n6) راجع On Hand: النهائي يزيد والمكونات تنقص.\\nلا تنتقل للخطوة التالية قبل أن ترى النتيجة على بطاقة المنتج.',en:'1) Define a finished product and Storable components.\\n2) Manufacturing → Bills of Materials → New: product + component lines and quantities.\\n3) Operations → Manufacturing Orders → New: product and quantity.\\n4) Confirm — components appear from the BOM.\\n5) On execution: Produce / Mark as Done.\\n6) Review On Hand: finished increases, components decrease.\\nDo not move to the next step before you see the result on the product form.'}},
      {type:'example',title:{ar:'مثال عملي',en:'Practical example'},content:{ar:'منتج «طاولة»: BOM = 4 أرجل + سطح واحد. أمر لـ 10 طاولات يستهلك 40 رجلاً و 10 أسطح. بعد Done: On Hand للطاولات +10 وللأرجل −40. تحقق من الرقمين على شاشتي المنتج.',en:'Product “Table”: BOM = 4 legs + 1 top. Order for 10 tables consumes 40 legs and 10 tops. After Done: tables On Hand +10 and legs −40. Verify both numbers on the product screens.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من Apps افتح Manufacturing (بيئة تجريبية). تصفّح: Products، Bills of Materials، Operations. لا تُنشئ أوامر إنتاج حقيقية قبل إكمال درس BOM.',en:'From Apps open Manufacturing (trial environment). Browse: Products, Bills of Materials, Operations. Do not create real production orders before finishing the BOM lesson.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ابدأ بـ BOM لمكوّنين فقط قبل مراكز العمل (Work Centers) والمسارات المعقدة — الوضوح على الشاشة أهم من التعقيد المبكر.',en:'Start with a two-component BOM before work centers and complex routings — clarity on screen matters more than early complexity.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء MO دون BOM أو بمكوّنات غير Storable. النتيجة على الشاشة: مكوّنات فارغة أو كميات لا تتحرك بعد Done.',en:'Creating an MO without a BOM or with non-Storable components. On-screen result: empty components or quantities that do not move after Done.'}}
    ],
    knowledgeCheck:{question:{ar:'ما الترتيب الصحيح للشاشات في التصنيع؟',en:'Correct screen order in manufacturing?'},options:{ar:['فاتورة → BOM → بيع','BOM → أمر تصنيع → Done → On Hand','CRM → فاتورة','استلام فقط'],en:['Invoice → BOM → Sale','BOM → MO → Done → On Hand','CRM → Invoice','Receipt only']},answer:1,explanation:{ar:'القائمة أولاً ثم الأمر ثم الإتمام لدخول المخزون.',en:'BOM first, then order, then done so stock updates.'}}},
  
  {id:'manufacturing-02',path:'manufacturing',order:2,title:{ar:'قائمة المواد (BOM)',en:'Bill of Materials (BOM)'},description:{ar:'بناء BOM وربط المكونات على الشاشة',en:'Build a BOM and link components on screen'},duration:14,xp:25,
    objectives:{ar:['إنشاء BOM','ربط المكونات بالمنتج النهائي','قراءة الكميات على الشاشة','تمييز العناصر على الشاشة'],en:['Create a BOM','Link components to finished product','Read quantities on screen','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'BOM هي وصفة المنتج على الشاشة: أي مكوّنات وبأي كمية لإنتاج وحدة (أو دفعة). الشكل مألوف: رأس (المنتج النهائي) + جدول بنود (كل سطر مكوّن + كمية) مثل عرض السعر أو أمر الشراء.',en:'A BOM is the product recipe on screen: which components and quantities make one unit (or batch). Familiar shape: header (finished product) + lines table (each line component + qty) like a quotation or purchase order.'}},
      {type:'why',title:{ar:'لماذا BOM قبل كل أمر؟',en:'Why a BOM before every order?'},content:{ar:'أمر التصنيع يسحب المكونات تلقائياً من الـ BOM. بدونها تكتب المكونات يدوياً في كل أمر، وتختلف الوصفة بين أمر وآخر، وتضيع دقة التخطيط على الشاشة.',en:'The manufacturing order pulls components automatically from the BOM. Without it you type components on every order, the recipe differs per order, and planning accuracy on screen is lost.'}},
      {type:'visual',title:{ar:'نموذج BOM',en:'BOM form'},content:{ar:'Form View: حقل Product في الرأس، ثم جدول Components. احفظ قبل إنشاء أي MO. راجع الوحدات (UoM) حتى لا تظهر كسور غير مفهومة.',en:'Form View: Product field in the header, then Components table. Save before creating any MO. Check units of measure (UoM) so odd fractions do not appear.'},image:'bom-list.svg',caption:{ar:'<strong>Bills of Materials</strong> — رأس المنتج النهائي + بنود المكونات. نفس منطق رأس/بنود في كل أودو.',en:'<strong>BOM Form</strong> — finished product header + component lines. Same header/lines logic across Odoo.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Manufacturing → Products → Bills of Materials → New.\\n2) Product = المنتج النهائي (Storable).\\n3) أضف أسطر Components: منتج مكوّن + Quantity لكل وحدة نهائية.\\n4) BoM Type: عادة Manufacture this product.\\n5) Save.\\n6) عند New MO لاحقاً ستظهر هذه الأسطر تلقائياً — لا تعِد إدخالها.',en:'1) Manufacturing → Products → Bills of Materials → New.\\n2) Product = finished product (Storable).\\n3) Add Component lines: component product + Quantity per finished unit.\\n4) BoM Type: usually Manufacture this product.\\n5) Save.\\n6) On New MO later these lines appear automatically — do not re-enter them.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'BOM لقهوة جاهزة: 1 كيس بن + 1 لتر ماء لكل وحدة. أمر لـ 50 وحدة يطلب على الشاشة 50 كيساً و 50 لتراً. إن غيّرت الـ BOM لاحقاً، الأوامر الجديدة تأخذ الوصفة الجديدة.',en:'BOM for ready coffee: 1 bag of beans + 1 liter water per unit. An order for 50 units demands 50 bags and 50 liters on screen. If you change the BOM later, new orders take the new recipe.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'في قاعدة تجريبية: أنشئ مكوّنين Storable ومنتجاً نهائياً، ثم BOM بسطرين. افتح الـ BOM بعد الحفظ وتأكد أن الكميات ظاهرة قبل أي Confirm لـ MO.',en:'On a trial database: create two Storable components and a finished product, then a two-line BOM. Reopen the BOM after save and confirm quantities show before any MO Confirm.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'وحّد وحدات القياس بين بطاقة المكوّن وسطر الـ BOM حتى تبقى الأرقام على الشاشة قابلة للقراءة في الورشة.',en:'Align units of measure between the component form and the BOM line so numbers on screen stay readable on the shop floor.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'BOM يشير لمنتج Service أو ينقص مكوّناً أساسياً — الأمر «ينتج» بلا استهلاك صحيح وOn Hand يكذب.',en:'BOM points to a Service product or misses a key component — the order “produces” without correct consumption and On Hand lies.'}}
    ],
    knowledgeCheck:{question:{ar:'شاشة BOM الأساسية تحتوي؟',en:'The main BOM screen contains?'},options:{ar:['فاتورة فقط','منتج نهائي + بنود مكونات','CRM','موظفين'],en:['Invoice only','Finished product + component lines','CRM','Employees']},answer:1,explanation:{ar:'رأس المنتج وجدول المكونات.',en:'Product header and components table.'}}},
  
  {id:'manufacturing-03',path:'manufacturing',order:3,title:{ar:'أمر التصنيع (MO)',en:'Manufacturing Order (MO)'},description:{ar:'إنشاء وتأكيد أمر التصنيع على الشاشة',en:'Create and confirm a manufacturing order on screen'},duration:14,xp:25,
    objectives:{ar:['إنشاء MO من الشاشة','Confirm وفهم الحالة','قراءة المكونات المطلوبة','تمييز العناصر على الشاشة'],en:['Create MO from screen','Confirm and understand status','Read required components','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'أمر التصنيع (Manufacturing Order) يطلب إنتاج كمية من منتج له BOM. شاشته: رأس (المنتج والكمية) + مكوّنات مسحوبة من القائمة + حالة (Draft → Confirmed → Done).',en:'A Manufacturing Order requests production of a quantity of a product that has a BOM. Its screen: header (product and qty) + components pulled from the BOM + status (Draft → Confirmed → Done).'}},
      {type:'why',title:{ar:'لماذا Confirm قبل التنفيذ؟',en:'Why Confirm before execution?'},content:{ar:'Confirm يثبت الطلب على الشاشة ويظهر نقص المواد مبكراً. التنفيذ بلا Confirm يترك التخطيط أعمى.',en:'Confirm locks the demand on screen and surfaces material shortages early. Executing without Confirm leaves planning blind.'}},
      {type:'visual',title:{ar:'قائمة أوامر التصنيع',en:'Manufacturing orders list'},content:{ar:'مثل List في المبيعات والمشتريات: صفوف، بحث، عمود الحالة. New ثم Form. راقب Draft مقابل Confirmed مقابل Done.',en:'Like List in sales and purchase: rows, search, status column. New then Form. Watch Draft vs Confirmed vs Done.'},image:'list-view.png',caption:{ar:'<strong>Manufacturing Orders (List)</strong> — الحالة في العمود. انقر السطر لفتح الأمر ومكوّناته.',en:'<strong>Manufacturing Orders (List)</strong> — status in the column. Click the row to open the order and its components.'}},
      {type:'visual',title:{ar:'تفاصيل الأمر (Form)',en:'Order details (Form)'},content:{ar:'بعد فتح السطر من القائمة يظهر Form: المنتج، الكمية، أسطر المكونات، وأزرار Confirm ثم Produce/Done. راجع المكونات قبل Confirm.',en:'After opening the row from the list the Form appears: product, quantity, component lines, and Confirm then Produce/Done buttons. Review components before Confirm.'},image:'mo-form.svg',caption:{ar:'<strong>Manufacturing Order</strong> — رأس الأمر + بنود المكونات + شريط الإجراءات أعلى الصفحة.',en:'<strong>MO Form</strong> — order header + component lines + action bar at the top.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Manufacturing → Operations → Manufacturing Orders → New.\\n2) Product + Quantity to produce.\\n3) تحقق أن Components ظهرت من الـ BOM.\\n4) Confirm — راقب تغيّر الحالة.\\n5) عند التنفيذ الفعلي: سجّل الكميات المنتجة/المستهلكة.\\n6) Mark as Done / Produce.\\n7) افتح بطاقة المنتج وراجع On Hand.',en:'1) Manufacturing → Operations → Manufacturing Orders → New.\\n2) Product + Quantity to produce.\\n3) Verify Components appeared from the BOM.\\n4) Confirm — watch status change.\\n5) On real execution: record produced/consumed quantities.\\n6) Mark as Done / Produce.\\n7) Open the product form and review On Hand.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'MO لـ 10 طاولات: بعد Confirm تظهر حاجة 40 رجلاً. إن On Hand للأرجل 30 تظهر الشاشة نقصاً قبل Done — عالج النقص (شراء/تحويل) أولاً.',en:'MO for 10 tables: after Confirm demand shows 40 legs. If On Hand for legs is 30 the screen shows a shortage before Done — fix shortage (buy/transfer) first.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'في بيئة تجريبية فقط: New MO لمنتج له BOM، راجع أسطر المكونات، ولاحظ الحالة قبل وبعد Confirm دون Mark as Done إن نقصت المواد.',en:'In a trial DB only: New MO for a product with BOM, review component lines, and notice status before and after Confirm without Mark as Done if materials are short.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اطبع أو صدّر مكوّنات الأمر من الشاشة لورشة العمل إن كان التنفيذ يدوياً.',en:'Print or export order components from the screen for the shop floor if execution is manual.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'Mark as Done مع نقص مكونات دون معالجة — On Hand غير متسق وتخطيط المواد ينهار. راجعه على الشاشة قبل الانتقال.',en:'Mark as Done with component shortages unresolved — On Hand becomes inconsistent and material planning breaks. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد Confirm على أمر التصنيع ماذا يحدث غالباً على الشاشة؟',en:'After Confirm on an MO what often happens on screen?'},options:{ar:['حذف الأمر','ظهور/تأكيد المكونات من BOM','فاتورة عميل','لا شيء'],en:['Order deleted','Components from BOM appear/confirm','Customer invoice','Nothing']},answer:1,explanation:{ar:'الأمر يعتمد على BOM لعرض المكونات.',en:'The order relies on the BOM to show components.'}}},
  
  {id:'manufacturing-04',path:'manufacturing',order:4,title:{ar:'الاستهلاك والإنتاج والمخزون',en:'Consumption, Production and Stock'},description:{ar:'أثر إتمام التصنيع على On Hand على الشاشة',en:'Effect of finishing production on On Hand on screen'},duration:14,xp:25,
    objectives:{ar:['ربط Done بالمخزون','نقص المكونات وزيادة النهائي','مراجعة الشاشات بعد الإتمام'],en:['Link Done to stock','Component decrease and finished increase','Review screens after done']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'عند Mark as Done / Produce: تنقص On Hand للمكونات وتزيد للمنتج النهائي. الفكرة نفس Validate في الاستلام والتسليم، لكن الاتجاهين داخل أمر تصنيع واحد على الشاشة.',en:'On Mark as Done / Produce: On Hand decreases for components and increases for the finished product. Same idea as Validate on receipt and delivery, but both directions inside one manufacturing order on screen.'}},
      {type:'why',title:{ar:'لماذا مراجعة On Hand بعد Done؟',en:'Why review On Hand after Done?'},content:{ar:'للتأكد أن الشاشة تعكس المصنع الحقيقي. إتمام خاطئ يفسد تخطيط المواد والأوامر التالية ويظهر نقصاً وهمياً أو فائضاً وهمياً.',en:'To ensure the screen mirrors the real shop floor. A wrong completion breaks material planning and later orders and shows phantom shortage or surplus.'}},
      {type:'visual',title:{ar:'بطاقة المنتج بعد الإتمام',en:'Product form after completion'},content:{ar:'افتح المنتج النهائي ومكوّناً واحداً من قائمة المنتجات. سجّل On Hand قبل Done، نفّذ في التجريبي، ثم قارن. هذا أهم تمرين تحقق في المسار.',en:'Open the finished product and one component from the product list. Note On Hand before Done, run in trial, then compare. This is the most important verification drill in the path.'},image:'product-catalog.png',caption:{ar:'<strong>Product — On Hand</strong> — ميزان الحقيقة بعد كل أمر تصنيع مكتمل.',en:'<strong>Product — On Hand</strong> — source of truth after every completed manufacturing order.'}},
      {type:'concept',title:{ar:'ما راقبه على الشاشات',en:'What to watch on screens'},content:{ar:'1) قبل الإتمام: On Hand للمكونات وللمنتج النهائي.\\n2) على أمر التصنيع: Mark as Done / Produce.\\n3) بعد الإتمام: المكونات − الكمية المستهلكة، النهائي + الكمية المنتجة.\\n4) إن وُجدت حركات مخزون (Stock Moves) افتحها من الأمر أو من Inventory.\\n5) لا تعتمد على الذاكرة — الرقم على بطاقة المنتج هو المرجع.',en:'1) Before completion: On Hand for components and finished product.\\n2) On the manufacturing order: Mark as Done / Produce.\\n3) After completion: components − consumed qty, finished + produced qty.\\n4) If stock moves exist, open them from the order or Inventory.\\n5) Do not rely on memory — the number on the product form is the reference.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'قبل: أرجل = 100، طاولة = 5. بعد إنتاج 10 طاولات (BOM: 4 أرجل/طاولة): أرجل = 60، طاولة = 15. إن لم تتطابق الأرقام على الشاشة، لا تُنشئ الأمر التالي قبل التحقيق.',en:'Before: legs = 100, table = 5. After producing 10 tables (BOM: 4 legs/table): legs = 60, table = 15. If numbers on screen do not match, do not create the next order before investigating.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'اكتب On Hand على ورقة قبل إتمام أي MO تجريبي، ثم بعد Done قارن بطاقة المنتج. إن اختلف الرقم عن توقّعك راجع مكوّنات الأمر على الشاشة.',en:'Write On Hand on paper before completing any trial MO, then after Done compare the product form. If the number differs from your expectation, review order components on screen.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'نفس انضباط Receipt: لا Done قبل التنفيذ الفعلي في الورشة. الشاشة تتبع الواقع لا العكس.',en:'Same discipline as Receipt: no Done before real shop-floor execution. The screen follows reality, not the other way around.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إتمام أوامر بأثر رجعي دون مطابقة المكونات الفعلية — On Hand يبتعد عن المستودع يوماً بعد يوم.',en:'Backdating completion without matching components actually used — On Hand drifts from the warehouse day after day.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد إتمام MO صحيح ماذا يحدث لـ On Hand على الشاشة؟',en:'After a correct MO completion what happens to On Hand on screen?'},options:{ar:['لا يتغير','المكونات تنقص والنهائي يزيد','كل شيء يزيد','كل شيء ينقص'],en:['No change','Components decrease and finished increases','Everything increases','Everything decreases']},answer:1,explanation:{ar:'استهلاك مكونات وإنتاج تام.',en:'Consume components and produce finished goods.'}}},
  
  {id:'manufacturing-05',path:'manufacturing',order:5,title:{ar:'ملخص مسار التصنيع',en:'Manufacturing Path Summary'},description:{ar:'خريطة الشاشات من BOM إلى On Hand',en:'Screen map from BOM to On Hand'},duration:8,xp:15,
    objectives:{ar:['تلخيص المسار','ربط التصنيع بالمخزون'],en:['Summarize the flow','Link manufacturing to inventory']},
    sections:[
      {type:'intro',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) BOM (وصفة المكونات).\\n2) Manufacturing Order → Confirm.\\n3) Produce / Mark as Done.\\n4) On Hand: النهائي + والمكونات −.\\nراجع دائماً List و Form وبطاقة المنتج بعد كل أمر.',en:'1) BOM (component recipe).\\n2) Manufacturing Order → Confirm.\\n3) Produce / Mark as Done.\\n4) On Hand: finished + and components −.\\nAlways review List, Form and product form after every order.'}},
      {type:'visual',title:{ar:'المرجع بعد الإتمام',en:'Reference after completion'},content:{ar:'بطاقة المنتج هي ميزان الحقيقة بعد Done: قارن On Hand مع ما خططته في الأمر.',en:'The product form is the source of truth after Done: compare On Hand with what you planned on the order.'},image:'product-catalog.png',caption:{ar:'<strong>Product On Hand</strong> — آخر محطة للتحقق بعد إتمام التصنيع.',en:'<strong>Product On Hand</strong> — last verification stop after finishing manufacturing.'}},
      {type:'tip',title:{ar:'الخطوة التالية',en:'Next step'},content:{ar:'بعد ثبات BOM والأوامر البسيطة: Work Centers وجدولة العمليات على الشاشة.',en:'After solid BOMs and simple orders: Work Centers and operation scheduling on screen.'}},
      {type:'mistake',title:{ar:'تذكير',en:'Reminder'},content:{ar:'لا تنتقل للتعقيد قبل أن يصبح مسار BOM → MO → Done واضحاً على الشاشات.',en:'Do not move to complexity before BOM → MO → Done is clear on the screens.'}}
    ],
    knowledgeCheck:null},
  
  {id:'hr-01',path:'hr',order:1,title:{ar:'نظرة عامة على الموارد البشرية',en:'HR Overview'},description:{ar:'شاشات الموظفين والتطبيقات المرتبطة',en:'Employee screens and related apps'},duration:12,xp:20,
    objectives:{ar:['التعرف على تطبيق Employees','بطاقة الموظف كشاشة مركزية','ربط HR بباقي أودو','تمييز العناصر على الشاشة'],en:['Know the Employees app','Employee form as central screen','Link HR to the rest of Odoo','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق Employees (مع Attendances و Time Off) يدير بيانات الموظف من بطاقة Form تشبه Contact مع حقول وظيفية: القسم، المنصب، المدير، معلومات العمل. باقي شاشات HR تشير إلى هذا السجل.',en:'The Employees app (with Attendances and Time Off) manages employee data from a Form similar to a Contact with job fields: department, position, manager, work info. Other HR screens point to this record.'}},
      {type:'why',title:{ar:'لماذا البطاقة أولاً؟',en:'Why the card first?'},content:{ar:'الإجازات والحضور والعقود تختار الموظف من قائمة. بطاقة ناقصة أو مكررة تعني أخطاء على كل الشاشات التابعة وتقارير حضور فارغة أو مزدوجة.',en:'Time off, attendance and contracts pick the employee from a list. An incomplete or duplicate card means errors on every related screen and empty or double attendance reports.'}},
      {type:'visual',title:{ar:'قائمة الموظفين',en:'Employees list'},content:{ar:'List → بحث بالاسم → فتح الصف للبطاقة. New لموظف جديد. نفس عادة التنقل في Sales و Purchase.',en:'List → search by name → open the row for the form. New for a new employee. Same navigation habit as Sales and Purchase.'},image:'list-view.png',caption:{ar:'<strong>Employees List</strong> — ابحث قبل New لتفادي التكرار. البطاقة تُستخدم لاحقاً في الحضور والإجازات.',en:'<strong>Employees List</strong> — search before New to avoid duplicates. The card is reused later in attendance and time off.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Apps → Employees.\\n2) New أو افتح موظفاً موجوداً.\\n3) الاسم، القسم، المنصب، المدير، بريد العمل.\\n4) Save.\\n5) لاحقاً في Time Off / Attendances: اختر هذا الموظف من القائمة المنسدلة — لا تكتب اسماً حراً.',en:'1) Apps → Employees.\\n2) New or open an existing employee.\\n3) Name, department, job position, manager, work email.\\n4) Save.\\n5) Later in Time Off / Attendances: pick this employee from the dropdown — do not type a free-text name.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'موظف مبيعات: Department = Sales، Job = Salesperson، Manager = مدير المبيعات. يظهر عند تعيين Salesperson على Opportunity في CRM.',en:'Sales employee: Department = Sales, Job = Salesperson, Manager = sales manager. Appears when assigning Salesperson on an Opportunity in CRM.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Employees من Apps. تصفّح القائمة دون تعديل إنتاجي. افتح بطاقة واحدة وحدد حقول القسم والمنصب إن وُجدت.',en:'Open Employees from Apps. Browse the list without production edits. Open one form and locate department and job fields if present.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اربط User بالموظف عند الحاجة لتسجيل الحضور الذاتي من نفس المستخدم. راجعه على الشاشة قبل الانتقال.',en:'Link User to the employee when self-service attendance from the same user is needed. Review it on screen before moving on.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'موظف مكرر بأسماء متقاربة — تاريخ الإجازات والحضور يتوزع على سجلين ويصعب إصلاحه لاحقاً. راجعه على الشاشة قبل الانتقال.',en:'Duplicate employees with similar names — time-off and attendance history splits across two records and is hard to fix later. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'الشاشة المركزية في HR غالباً هي؟',en:'The central screen in HR is often?'},options:{ar:['فاتورة','بطاقة الموظف (Form)','BOM','RFQ'],en:['Invoice','Employee form','BOM','RFQ']},answer:1,explanation:{ar:'بطاقة الموظف مرجع الإجازات والحضور.',en:'Employee form is the reference for time off and attendance.'}}},
  
  {id:'hr-02',path:'hr',order:2,title:{ar:'الحضور (Attendances)',en:'Attendances'},description:{ar:'تسجيل الدخول والخروج على الشاشة',en:'Check in/out on screen'},duration:10,xp:20,
    objectives:{ar:['فهم شاشة الحضور','Check In / Check Out','مراجعة السجلات','تمييز العناصر على الشاشة'],en:['Understand attendance screen','Check in / Check out','Review records','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'شاشة Attendances تسجّل وقت الحضور والانصراف. قد تكون كيوسك أو تسجيلاً ذاتياً من المستخدم. كل حركة تظهر كسجل في List يمكن البحث فيه بالتاريخ أو الموظف.',en:'The Attendances screen records check-in and check-out times. It may be a kiosk or user self-service. Each move appears as a list record searchable by date or employee.'}},
      {type:'why',title:{ar:'لماذا التسجيل على الشاشة؟',en:'Why record on screen?'},content:{ar:'التقارير والكشوف تعتمد على ما هو موثّق في أودو. الحضور الشفهي أو في جدول خارجي لا يدخل التقارير.',en:'Reports and payroll rely on what is documented in Odoo. Verbal attendance or an external sheet never enters the reports.'}},
      {type:'visual',title:{ar:'قائمة سجلات الحضور',en:'Attendance records list'},content:{ar:'List: الموظف، وقت الدخول، وقت الخروج. ابحث وفلتر قبل أي تصحيح يدوي.',en:'List: employee, check-in time, check-out time. Search and filter before any manual correction.'},image:'list-view.png',caption:{ar:'<strong>Attendances List</strong> — كل سطر حركة حضور. افتح السطر للتفاصيل إن لزم.',en:'<strong>Attendances List</strong> — each row is an attendance move. Open the row for details if needed.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Apps → Attendances.\\n2) Check In عند بدء العمل.\\n3) Check Out عند الانتهاء (أو من الكيوسك).\\n4) راجع السجلات في القائمة.\\n5) أي تصحيح يدوي: بصلاحية + سبب موثّق فقط.',en:'1) Apps → Attendances.\\n2) Check In at start of work.\\n3) Check Out at end (or from kiosk).\\n4) Review records in the list.\\n5) Any manual correction: with rights + documented reason only.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'موظف Check In 09:00 ثم Check Out 17:00 — يظهر السجل في القائمة ويمكن تجميعه في تقرير الحضور الأسبوعي.',en:'Employee Check In 09:00 then Check Out 17:00 — the record appears in the list and can be grouped in a weekly attendance report.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'إن كان التطبيق مثبتاً: افتح Attendances وحدد موقع أزرار Check In/Out دون تعديل سجلات زملاء في الإنتاج.',en:'If the app is installed: open Attendances and locate Check In/Out buttons without editing colleagues’ production records.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'وحّد السياسة (كيوسك أو ذاتي) حتى لا تختلف الشاشة بين الموظفين.',en:'Unify the policy (kiosk or self-service) so the screen is not different between employees.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تعديل الأوقات بلا صلاحية أو أثر — تضعف ثقة التقارير. راجعه على الشاشة قبل الانتقال.',en:'Editing times without rights or audit trail — trust in reports weakens. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'شاشة Attendances تُستخدم لـ؟',en:'The Attendances screen is used for?'},options:{ar:['BOM','تسجيل الحضور والانصراف','فاتورة مورد','فرصة بيع'],en:['BOM','Check-in and check-out','Vendor bill','Sales opportunity']},answer:1,explanation:{ar:'حضور وانصراف الموظفين.',en:'Employee check-in and check-out.'}}},
  
  {id:'hr-03',path:'hr',order:3,title:{ar:'الإجازات (Time Off)',en:'Time Off'},description:{ar:'طلب الإجازة والموافقة على الشاشة',en:'Time off request and approval on screen'},duration:14,xp:25,
    objectives:{ar:['إنشاء طلب إجازة','فهم الحالات على الشاشة','الموافقة من الواجهة','تمييز العناصر على الشاشة'],en:['Create a time off request','Understand on-screen statuses','Approve from the UI','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'Time Off: الموظف ينشئ طلباً من الشاشة، والمدير يوافق أو يرفض من قائمة الموافقات. الحالات تشبه مستندات أودو الأخرى: مسودة/للإعتماد → موافق / مرفوض.',en:'Time Off: the employee creates a request on screen, the manager approves or refuses from the approvals list. Statuses mirror other Odoo documents: draft/to approve → approved / refused.'}},
      {type:'why',title:{ar:'لماذا الطلب على الشاشة؟',en:'Why request on screen?'},content:{ar:'حتى يظهر الرصيد والتعارض مع طلبات أخرى على الشاشة. مجموعات واتساب لا تُراجع عند الكشوف ولا تحفظ تاريخ الموافقة.',en:'So balance and conflicts with other requests show on screen. WhatsApp groups are not audited at payroll time and do not keep approval history.'}},
      {type:'visual',title:{ar:'قائمة طلبات الإجازة',en:'Time off requests list'},content:{ar:'List بالطلبات مع عمود الحالة. New لطلب جديد. المدير يفتح الطلب من قائمة To Approve.',en:'List of requests with a status column. New for a new request. The manager opens the request from the To Approve list.'},image:'list-view.png',caption:{ar:'<strong>Time Off List</strong> — راقب To Approve / Approved / Refused قبل أي قرار.',en:'<strong>Time Off List</strong> — watch To Approve / Approved / Refused before any decision.'}},
      {type:'visual',title:{ar:'نموذج طلب الإجازة',en:'Time off request form'},content:{ar:'نموذج الطلب: الموظف، نوع الإجازة، من تاريخ وإلى تاريخ. بعد Submit راقب الحالة في أعلى أو جانب النموذج.',en:'Request form: employee, time off type, date from and to. After Submit watch status at the top or side of the form.'},image:'form-view.png',caption:{ar:'<strong>Time Off Form</strong> — الحقول الأساسية ثم Submit. الحالة تنتقل إلى To Approve.',en:'<strong>Time Off Form</strong> — core fields then Submit. Status moves to To Approve.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Time Off → New.\\n2) الموظف (إن لم يُملأ تلقائياً)، نوع الإجازة، من تاريخ → إلى تاريخ.\\n3) Save / Submit — الحالة غالباً To Approve.\\n4) المدير: Approve أو Refuse من الشاشة.\\n5) راجع الرصيد إن ظهر بعد الموافقة.\\n6) لا تعتمد موافقة شفهية دون تحديث الحالة.',en:'1) Time Off → New.\\n2) Employee (if not auto-filled), time off type, date from → to.\\n3) Save / Submit — status often To Approve.\\n4) Manager: Approve or Refuse on screen.\\n5) Review balance if shown after approval.\\n6) Do not rely on verbal approval without updating status.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'طلب يومين Annual Leave → To Approve → المدير Approve من الشاشة → يُخصم الرصيد. إن رُفض الطلب تبقى الحالة Refused بلا خصم.',en:'Request two days Annual Leave → To Approve → manager Approve on screen → balance decreases. If refused, status stays Refused with no deduction.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Time Off إن وُجد. لاحظ أنواع الإجازة وحقول التواريخ. لا ترسل طلباً على بيانات إنتاج حقيقية للتدريب.',en:'Open Time Off if present. Notice leave types and date fields. Do not submit a request on real production data for training.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'عرّف أنواع الإجازة (سنوية، مرضية…) من الإعداد قبل فتح الباب للموظفين على الشاشة.',en:'Define time off types (annual, sick…) in settings before opening the screen to employees.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'موافقة شفوية دون Approve — الكشوف والتقارير تختلف عن ما يعتقده الفريق. راجعه على الشاشة قبل الانتقال.',en:'Verbal approval without Approve — payroll and reports differ from what the team believes. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'بعد تقديم طلب إجازة على الشاشة ما الحالة الشائعة؟',en:'After submitting a time off request on screen, common status?'},options:{ar:['Paid','To Approve','BOM','RFQ'],en:['Paid','To Approve','BOM','RFQ']},answer:1,explanation:{ar:'بانتظار موافقة المدير.',en:'Waiting for manager approval.'}}},
  
  {id:'hr-04',path:'hr',order:4,title:{ar:'الأقسام والمناصب',en:'Departments and Job Positions'},description:{ar:'هيكل التنظيم على الشاشات',en:'Org structure on screens'},duration:10,xp:15,
    objectives:{ar:['إنشاء قسم','ربط منصب بالموظف','Group By على القائمة','تمييز العناصر على الشاشة'],en:['Create a department','Link job to employee','Group By on the list','Identify on-screen elements']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الأقسام (Departments) والمناصب (Job Positions) حقول على بطاقة الموظف وفي قوائم الإعداد. تظهر لاحقاً في التصفية والتقارير ومسار الموافقات.',en:'Departments and Job Positions are fields on the employee form and in configuration lists. They later appear in filters, reports and approval flows.'}},
      {type:'why',title:{ar:'لماذا الهيكل على الشاشة؟',en:'Why structure on screen?'},content:{ar:'بدون Department يصبح Group By والتقارير حسب القسم فارغة، ويصعب تعيين مدير للموافقات.',en:'Without Department, Group By and per-department reports are empty, and assigning a manager for approvals is harder.'}},
      {type:'visual',title:{ar:'قائمة الموظفين بعد الهيكل',en:'Employees list after structure'},content:{ar:'بعد تعبئة القسم على البطاقات: من List استخدم Group By Department لرؤية التجميع فوراً.',en:'After filling department on the forms: from List use Group By Department to see grouping immediately.'},image:'list-view.png',caption:{ar:'<strong>Employees + Group By</strong> — نفس أداة التصفية في باقي أودو؛ هنا للهيكل التنظيمي.',en:'<strong>Employees + Group By</strong> — same filter tool as elsewhere in Odoo; here for org structure.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Employees → Configuration → Departments / Job Positions.\\n2) New: اسم القسم أو المنصب → Save.\\n3) افتح بطاقة موظف → اختر Department و Job Position.\\n4) Save.\\n5) ارجع للقائمة → Group By Department.',en:'1) Employees → Configuration → Departments / Job Positions.\\n2) New: department or job name → Save.\\n3) Open an employee form → select Department and Job Position.\\n4) Save.\\n5) Return to the list → Group By Department.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'قسم Inventory ومنصب Warehouse Operator — عند تقرير الحضور تفلتر بسهولة من نفس القائمة.',en:'Inventory department and Warehouse Operator job — on an attendance report you filter easily from the same list.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من قائمة الموظفين جرّب Group By إن وُجد دون تعديل بيانات الإنتاج.',en:'From the employees list try Group By if available without editing production data.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'هيكل بسيط أوضح على الشاشة من عشرات الأقسام الفارغة.',en:'A simple structure is clearer on screen than dozens of empty departments.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك Department فارغاً للجميع — تفقد التصفية والتقارير. راجعه على الشاشة قبل الانتقال.',en:'Leaving Department empty for everyone — you lose filtering and reports. Review it on screen before moving on.'}}
    ],
    knowledgeCheck:{question:{ar:'Department على بطاقة الموظف يفيد في؟',en:'Department on the employee form helps with?'},options:{ar:['BOM فقط','التنظيم والتقارير والموافقات','فاتورة العميل فقط','لا شيء'],en:['BOM only','Organization, reports and approvals','Customer invoice only','Nothing']},answer:1,explanation:{ar:'هيكل وتنظيم على الشاشة.',en:'Structure and organization on screen.'}}},
  
  {id:'hr-05',path:'hr',order:5,title:{ar:'ملخص مسار الموارد البشرية',en:'HR Path Summary'},description:{ar:'خريطة شاشات HR',en:'HR screens map'},duration:6,xp:10,
    objectives:{ar:['تلخيص شاشات HR'],en:['Summarize HR screens']},
    sections:[
      {type:'intro',title:{ar:'خريطة الشاشات',en:'Screen map'},content:{ar:'1) Employees — البطاقة المركزية.\\n2) Attendances — Check In/Out.\\n3) Time Off — طلب ثم Approve.\\n4) Departments / Jobs — هيكل.\\nابدأ دائماً ببطاقة موظف نظيفة غير مكررة.',en:'1) Employees — central form.\\n2) Attendances — Check In/Out.\\n3) Time Off — request then Approve.\\n4) Departments / Jobs — structure.\\nAlways start with a clean, non-duplicate employee form.'}},
      {type:'visual',title:{ar:'العودة للقائمة',en:'Back to the list'},content:{ar:'كل تطبيقات HR تعتمد List → Form. أتقن هذا الزوج مرة واحدة واستخدمه في الموظفين والحضور والإجازات.',en:'All HR apps rely on List → Form. Master this pair once and use it for employees, attendance and time off.'},image:'list-view.png',caption:{ar:'<strong>List → Form</strong> — العادة المشتركة في كل شاشات HR.',en:'<strong>List → Form</strong> — the shared habit across all HR screens.'}},
      {type:'tip',title:{ar:'الخطوة التالية',en:'Next step'},content:{ar:'لاحقاً: العقود وPayroll بعد إتقان الحضور والإجازات على الشاشة.',en:'Later: contracts and payroll after mastering attendance and time off on screen.'}}
    ],
    knowledgeCheck:null},
  
  {id:'manufacturing-quiz',path:'manufacturing',order:6,title:{ar:'اختبار التصنيع',en:'Manufacturing Quiz'},description:{ar:'اختبر مسار BOM والأوامر',en:'Test BOM and orders path'},duration:15,xp:50,isQuiz:true,quizId:'quiz-manufacturing',
    sections:[{type:'intro',title:{ar:'اختبار',en:'Quiz'},content:{ar:'أجب عن أسئلة شاشات التصنيع.',en:'Answer manufacturing screen questions.'}},{type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'راجع BOM و MO قبل البدء. راجعه على الشاشة قبل الانتقال.',en:'Review BOM and MO before starting. Review it on screen before moving on.'}}],
    knowledgeCheck:null},
  {id:'hr-quiz',path:'hr',order:6,title:{ar:'اختبار الموارد البشرية',en:'HR Quiz'},description:{ar:'اختبر شاشات الموظف والحضور والإجازات',en:'Test employee, attendance and time off screens'},duration:15,xp:50,isQuiz:true,quizId:'quiz-hr',
    sections:[{type:'intro',title:{ar:'اختبار',en:'Quiz'},content:{ar:'أجب عن أسئلة شاشات HR.',en:'Answer HR screen questions.'}},{type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'راجع بطاقة الموظف والإجازات. راجعه على الشاشة قبل الانتقال.',en:'Review employee form and time off. Review it on screen before moving on.'}}],
    knowledgeCheck:null}

,

  ,
  {id:'accounting-06',path:'accounting',order:6,title:{ar:'دليل الحسابات واليوميات',en:'Chart of Accounts and Journals'},description:{ar:'CoA و Journals على الشاشة',en:'CoA and Journals on screen'},duration:16,xp:30,
    objectives:{ar:['فتح دليل الحسابات','تمييز أنواع اليوميات','ربط الفاتورة باليومية'],en:['Open chart of accounts','Distinguish journal types','Link invoice to journal']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'دليل الحسابات (Chart of Accounts) قائمة الحسابات التي تُرحَّل إليها القيود. اليومية (Journal) تصنّف القيد: مبيعات، مشتريات، بنك، نقدية. على الشاشة: Accounting → Configuration → Chart of Accounts / Journals.',en:'The Chart of Accounts lists accounts where entries post. A Journal classifies the entry: sales, purchase, bank, cash. On screen: Accounting → Configuration → Chart of Accounts / Journals.'}},
      {type:'why',title:{ar:'لماذا يهم؟',en:'Why it matters'},content:{ar:'فاتورة بلا يومية/حساب صحيح تُرحَّل في المكان الخطأ. التقارير المالية تقرأ من الحسابات لا من شاشة المبيعات فقط.',en:'An invoice with the wrong journal/account posts in the wrong place. Financial reports read accounts, not the sales screen alone.'}},
      {type:'visual',title:{ar:'قائمة الحسابات',en:'Accounts list'},content:{ar:'List: رمز الحساب، الاسم، النوع. Form: إعدادات الترحيل. لا تحذف حساباً مستخدماً — أرشف.',en:'List: code, name, type. Form: posting settings. Do not delete a used account — archive.'},image:'journal-list.svg',caption:{ar:'<strong>Journals / CoA style list</strong> — Model تقريباً account.account. ابحث بالرمز قبل New.',en:'<strong>Chart of Accounts</strong> — Model roughly account.account. Search by code before New.'}},
      {type:'concept',title:{ar:'على الشاشة والتقنية',en:'On screen and technically'},content:{ar:'1) Configuration → Chart of Accounts.\\n2) Configuration → Journals: Sales / Purchase / Bank / Cash.\\n3) عند Create Invoice تُختار يومية المبيعات غالباً تلقائياً.\\n4) بعد Confirm/Post يُنشأ account.move و account.move.line.\\n5) تقنياً: account.account، account.journal، account.move.',en:'1) Configuration → Chart of Accounts.\\n2) Configuration → Journals: Sales / Purchase / Bank / Cash.\\n3) On Create Invoice the sales journal is often automatic.\\n4) After Confirm/Post: account.move and account.move.line.\\n5) Technically: account.account, account.journal, account.move.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح Journals من الإعدادات وسمِّ نوع كل يومية ظاهرة دون تعديل الإنتاج.',en:'Open Journals from settings and name each visible journal type without production edits.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ثبّت حزمة الدليل المحاسبي لبلد الشركة عند الإنشاء بدل بناء كل حساب يدوياً.',en:'Install the country CoA package at setup instead of building every account manually.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'إنشاء حسابات مكررة بنفس المعنى بأسماء مختلفة — تتقسم التقارير.',en:'Creating duplicate accounts with the same meaning under different names — reports fragment.'}}
    ],
    knowledgeCheck:{question:{ar:'Journal في أودو يخدم؟',en:'A Journal in Odoo serves to?'},options:{ar:['BOM فقط','تصنيف القيود (مبيعات/بنك/…)','الحضور','Kanban فقط'],en:['BOM only','Classify entries (sales/bank/…)','Attendance','Kanban only']},answer:1,explanation:{ar:'اليومية تصنّف القيود.',en:'The journal classifies entries.'}}},
  {id:'accounting-07',path:'accounting',order:7,title:{ar:'الضرائب والمراكز التحليلية',en:'Taxes and Analytic Accounting'},description:{ar:'ضرائب الفاتورة والتحليل على الشاشة',en:'Invoice taxes and analytics on screen'},duration:14,xp:25,
    objectives:{ar:['أين تُعرَّف الضرائب','ظهور الضريبة على البنود','فكرة الحساب التحليلي'],en:['Where taxes are defined','Tax on lines','Analytic account idea']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الضرائب تُعرَّف من Configuration → Taxes وتُختار على المنتج أو بند الفاتورة. الحسابات التحليلية (Analytic) توزّع المبلغ على مشروع/قسم للتقارير الإدارية.',en:'Taxes are defined under Configuration → Taxes and selected on the product or invoice line. Analytic accounts allocate amounts to project/department for management reports.'}},
      {type:'concept',title:{ar:'خطوات',en:'Steps'},content:{ar:'1) Accounting → Configuration → Taxes.\\n2) على المنتج: حقل Customer Taxes / Vendor Taxes.\\n3) على بند الفاتورة راقب عمود الضريبة قبل Post.\\n4) Analytic: إن مفعّل، حقل Analytic على البند أو التوزيع.\\n5) Post بعد المراجعة لا قبلها.',en:'1) Accounting → Configuration → Taxes.\\n2) On product: Customer Taxes / Vendor Taxes.\\n3) On invoice line watch tax column before Post.\\n4) Analytic: if enabled, analytic field on line or distribution.\\n5) Post after review, not before.'}},
      {type:'visual',title:{ar:'من الأمر إلى الفاتورة',en:'From order to invoice'},content:{ar:'Create Invoice ينسخ البنود والضرائب من الأمر. راجع الشاشة قبل Confirm.',en:'Create Invoice copies lines and taxes from the order. Review the screen before Confirm.'},image:'sales-order.png',caption:{ar:'<strong>Create Invoice</strong> — راجع الضريبة على البنود قبل الترحيل.',en:'<strong>Create Invoice</strong> — review tax on lines before posting.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح ضريبة واحدة من الإعدادات واقرأ نوع الحساب المرتبط إن ظهر — دون تغيير الإنتاج.',en:'Open one tax from settings and read the linked account if shown — no production changes.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'Fiscal Position يكيّف الضرائب حسب الدولة/النوع — مهم للشركات متعددة الدول.',en:'Fiscal Position adapts taxes by country/type — important for multi-country companies.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترحيل فاتورة ثم اكتشاف ضريبة خاطئة — التصحيح بعد Post أصعب ويحتاج قيود تسوية.',en:'Posting then discovering wrong tax — correction after Post is harder and needs adjustments.'}}
    ],
    knowledgeCheck:{question:{ar:'أفضل وقت لمراجعة الضريبة؟',en:'Best time to review tax?'},options:{ar:['بعد إغلاق السنة فقط','قبل Confirm/Post على شاشة الفاتورة','لا تُراجع','في CRM فقط'],en:['Only after year end','Before Confirm/Post on the invoice screen','Never','In CRM only']},answer:1,explanation:{ar:'قبل الترحيل على الشاشة.',en:'Before posting on screen.'}}},
  {id:'accounting-08',path:'accounting',order:8,title:{ar:'التسوية والدفعات الجزئية',en:'Reconciliation and Partial Payments'},description:{ar:'Register Payment وبقاء الفاتورة مفتوحة',en:'Register Payment and open invoices'},duration:12,xp:25,
    objectives:{ar:['دفع جزئي من الشاشة','فهم Open مقابل Paid','ربط الدفعة بالفاتورة'],en:['Partial payment on screen','Open vs Paid','Link payment to invoice']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'من شاشة الفاتورة المرحّلة: Register Payment. يمكن مبلغ جزئي؛ تبقى الفاتورة غير Paid حتى اكتمال المبلغ. التسوية البنكية (Reconciliation) تربط حركات البنك بالقيود.',en:'From the posted invoice screen: Register Payment. Amount can be partial; invoice stays not Paid until fully covered. Bank reconciliation links bank lines to entries.'}},
      {type:'concept',title:{ar:'خطوات',en:'Steps'},content:{ar:'1) افتح Invoice/Bill بحالة Posted.\\n2) Register Payment → المبلغ، التاريخ، Journal (بنك/صندوق).\\n3) Validate الدفع.\\n4) راقب Residual / Amount Due.\\n5) عند الصفر: Paid.\\n6) للبنك: Accounting → Reconciliation (حسب الإصدار).',en:'1) Open Invoice/Bill in Posted.\\n2) Register Payment → amount, date, Journal (bank/cash).\\n3) Validate payment.\\n4) Watch Residual / Amount Due.\\n5) At zero: Paid.\\n6) For bank: Accounting → Reconciliation (per version).'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على فاتورة تجريبية: تخيل دفعة 40٪ ثم المتبقي — كيف تتغير الحالة على الشاشة؟',en:'On a trial invoice: imagine 40% payment then remainder — how does status change on screen?'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تسجّل دفعة في جدول خارجي دون Register Payment — التقارير لن تتطابق.',en:'Do not record payment only in an external sheet without Register Payment — reports will not match.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'دفع كامل مسجّل على فاتورة خاطئة — استخدم البحث برقم الفاتورة قبل Validate.',en:'Full payment posted to the wrong invoice — search by invoice number before Validate.'}}
    ],
    knowledgeCheck:{question:{ar:'دفعة جزئية على فاتورة Posted تجعلها غالباً؟',en:'A partial payment on a Posted invoice usually leaves it?'},options:{ar:['محذوفة','غير مكتملة الدفع حتى اكتمال المبلغ','BOM','Draft دائماً'],en:['Deleted','Not fully paid until amount is complete','BOM','Always Draft']},answer:1,explanation:{ar:'تبقى مفتوحة جزئياً حتى Paid.',en:'Stays partially open until Paid.'}}},

  {id:'technical-01',path:'technical',order:1,title:{ar:'معمارية أودو للمطور الوظيفي',en:'Odoo Architecture for Functional-Technical'},description:{ar:'Menu و Action و Model و View',en:'Menu, Action, Model and View'},duration:16,xp:30,
    objectives:{ar:['رسم سلسلة Menu→Action→Model→View','تفعيل Developer Mode','قراءة Metadata'],en:['Map Menu→Action→Model→View','Enable Developer Mode','Read Metadata']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'كل شاشة تقريباً: قائمة (ir.ui.menu) → إجراء نافذة (ir.actions.act_window) → نموذج (Model) → عروض XML (ir.ui.view). فهم السلسلة يفسّر لماذا «القائمة لا تظهر» أو «الزر لا يعمل».',en:'Almost every screen: menu (ir.ui.menu) → window action (ir.actions.act_window) → Model → XML views (ir.ui.view). This chain explains missing menus or dead buttons.'}},
      {type:'concept',title:{ar:'Developer Mode',en:'Developer Mode'},content:{ar:'1) Settings → Activate Developer Mode.\\n2) تظهر قوائم Technical.\\n3) على Form: أيقونة تصحيح → View Metadata / Edit View.\\n4) اقرأ Model واسم View.\\n5) عطّله في الإنتاج أمام المستخدمين غير التقنيين.',en:'1) Settings → Activate Developer Mode.\\n2) Technical menus appear.\\n3) On Form: debug icon → View Metadata / Edit View.\\n4) Read Model and View name.\\n5) Disable it in production for non-technical users.'}},
      {type:'visual',title:{ar:'نفس Form من زاوية تقنية',en:'Same Form, technical angle'},content:{ar:'ما تراه حقولاً هو fields على الـ Model. ما تراه أزراراً غالباً methods أو actions.',en:'What you see as fields are Model fields. Buttons are often methods or actions.'},image:'form-view.png',caption:{ar:'<strong>Form + Developer</strong> — اربط كل حقل ظاهر باسمه التقني.',en:'<strong>Form + Developer</strong> — link each visible field to its technical name.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'فعّل Developer Mode، افتح sale.order أو Contact، واكتب Model + ثلاثة أسماء حقول تقنية.',en:'Enable Developer Mode, open sale.order or Contact, and write Model + three technical field names.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'قبل طلب تخصيص من مطور: صوّر الشاشة + اسم الـ Model + ماذا يجب أن يتغيّر.',en:'Before asking a developer for a customization: screenshot + Model name + what must change.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تعديل View من الواجهة في الإنتاج بلا وحدة (module) — التعديل يضيع عند الترقية.',en:'Editing a View in production UI without a module — changes are lost on upgrade.'}}
    ],
    knowledgeCheck:{question:{ar:'سلسلة فتح شاشة قائمة صحيحة؟',en:'Correct chain to open a list screen?'},options:{ar:['View فقط','Menu → Action → Model → View','BOM → MO','User → Tax'],en:['View only','Menu → Action → Model → View','BOM → MO','User → Tax']},answer:1,explanation:{ar:'القائمة تستدعي إجراءً على نموذج بعرض.',en:'Menu calls an action on a model with a view.'}}},
  {id:'technical-02',path:'technical',order:2,title:{ar:'الحقول والعلاقات',en:'Fields and Relations'},description:{ar:'أنواع الحقول التي تبني الشاشة',en:'Field types that build the screen'},duration:14,xp:25,
    objectives:{ar:['تمييز Many2one و One2many','فهم computed و related','ربط الحقل بالعمود على List'],en:['Distinguish Many2one and One2many','Understand computed and related','Link field to List column']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'الشاشة لا تُرسم اعتباطاً: كل عمود وحقل قائمة منسدلة مربوط بنوع حقل على الـ Model.',en:'Screens are not drawn arbitrarily: every column and dropdown maps to a field type on the Model.'}},
      {type:'concept',title:{ar:'الأنواع الأساسية',en:'Core types'},content:{ar:'Many2one: قائمة منسدلة (partner_id).\\nOne2many: جدول بنود (order_line).\\nMany2many: علامات متعددة.\\nMonetary / Float / Integer / Char / Boolean / Selection / Date.\\ncomputed: تُحسب؛ related: تمرير من علاقة.\\nstore=True يخزّن للبحث والتقارير.',en:'Many2one: dropdown (partner_id).\\nOne2many: lines table (order_line).\\nMany2many: multi tags.\\nMonetary / Float / Integer / Char / Boolean / Selection / Date.\\ncomputed: calculated; related: from a relation.\\nstore=True stores for search and reports.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'sale.order.line: product_id (M2o)، product_uom_qty، price_unit، price_subtotal (غالباً محسوب).',en:'sale.order.line: product_id (M2o), product_uom_qty, price_unit, price_subtotal (often computed).'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على أي Form: حدّد حقلاً منسدلاً (M2o) وجدول بنود (O2m) واكتب اسميهما التقنيين إن ظهروا.',en:'On any Form: identify one dropdown (M2o) and one lines table (O2m) and write technical names if shown.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تخزّن نسخاً مكررة من اسم العميل على الأمر إن أمكن related/partner — مصدر واحد للحقيقة.',en:'Do not store duplicate customer name on the order if related/partner works — single source of truth.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تعديل قيمة محسوبة يدوياً ثم الاندهاش أنها ترجع بعد الحفظ.',en:'Manually editing a computed value then wondering it reverts after save.'}}
    ],
    knowledgeCheck:{question:{ar:'جدول بنود الأمر على الشاشة عادة؟',en:'Order lines table on screen is usually?'},options:{ar:['Many2one','One2many','Binary','HTML فقط'],en:['Many2one','One2many','Binary','HTML only']},answer:1,explanation:{ar:'One2many للبنود.',en:'One2many for lines.'}}},
  {id:'technical-03',path:'technical',order:3,title:{ar:'العروض XML والوراثة',en:'XML Views and Inheritance'},description:{ar:'كيف تُوسَّع الشاشة دون نسخ الملف',en:'How screens are extended without copying files'},duration:16,xp:30,
    objectives:{ar:['فكرة inherit_id','xpath لإضافة حقل','Studio مقابل الكود'],en:['Idea of inherit_id','xpath to add a field','Studio vs code']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'لا تُعدَّل ملفات أودو الأصلية مباشرة. تُنشأ View وريثة (inherit_id) وتُعدَّل بالعقد xpath: إضافة حقل، إخفاء، نقل.',en:'Core Odoo files are not edited directly. An inheriting View (inherit_id) is created and changed with xpath nodes: add, hide, move fields.'}},
      {type:'concept',title:{ar:'Studio مقابل الكود',en:'Studio vs code'},content:{ar:'Studio (Enterprise غالباً): سريع للنماذج الصغيرة.\\nالكود (XML+Python): للمشاريع، الإصدارات، Git، الترقية.\\nالقاعدة: إن تجاوز التخصيص «حقلاً إضافياً بسيطاً» خطط لوحدة module.',en:'Studio (often Enterprise): fast for small forms.\\nCode (XML+Python): for projects, versions, Git, upgrades.\\nRule: if customization exceeds a simple extra field, plan a module.'}},
      {type:'visual',title:{ar:'الشاشة نتيجة Views',en:'Screen is the result of Views'},content:{ar:'List و Form اللذان تراهما ناتج دمج العروض الأساسية والوريثة حسب الأولوية.',en:'The List and Form you see result from merging base and inherited views by priority.'},image:'form-view.png',caption:{ar:'<strong>Form</strong> — كل حقل ظاهر إما أصلي أو مُضاف بوراثة/Studio.',en:'<strong>Form</strong> — each visible field is core or added via inheritance/Studio.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'Developer Mode → Edit View: لاحظ هل توجد Inherited Views. لا تحفظ تغييراً على الإنتاج.',en:'Developer Mode → Edit View: note if Inherited Views exist. Do not save changes on production.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'سمِّ التخصيصات ووثّقها في موديول باسم شركةك — لا «إصلاح سريع» بلا اسم.',en:'Name customizations and document them in a module under your company name — no unnamed quick fixes.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'نسخ view كاملة بدل xpath — تعارضات عند الترقية وصيانة كابوس.',en:'Copying a full view instead of xpath — upgrade conflicts and maintenance nightmare.'}}
    ],
    knowledgeCheck:{question:{ar:'الطريقة الموصى بها لتوسيع Form معياري؟',en:'Recommended way to extend a standard Form?'},options:{ar:['حذف ملف أودو','View inheritance + xpath أو Studio بحذر','تعديل قاعدة البيانات مباشرة','إغلاق التطبيق'],en:['Delete Odoo file','View inheritance + xpath or careful Studio','Direct DB edit','Close the app']},answer:1,explanation:{ar:'الوراثة لا تكسر الترقية كما النسخ الكامل.',en:'Inheritance does not break upgrades like full copies.'}}},
  {id:'technical-04',path:'technical',order:4,title:{ar:'الأمان للمطوّر الوظيفي',en:'Security for Functional-Technical'},description:{ar:'CSV الصلاحيات و Record Rules',en:'ACL CSV and Record Rules'},duration:14,xp:25,
    objectives:{ar:['قراءة ir.model.access','فكرة Domain القاعدة','اختبار بمستخدم غير Admin'],en:['Read ir.model.access','Domain rule idea','Test as non-Admin']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'كل موديول جاد يضيف security/ir.model.access.csv وقواعد XML. الشاشة Users تختصر ذلك للمجموعات المعيارية.',en:'Every serious module adds security/ir.model.access.csv and XML rules. The Users screen abstracts that for standard groups.'}},
      {type:'concept',title:{ar:'ماذا تراجع؟',en:'What to review'},content:{ar:'1) Technical → Access Rights للـ Model.\\n2) Record Rules و Domain.\\n3) مجموعة المستخدم في Users.\\n4) اختبار Login حقيقي.\\n5) الحقول الحساسة: groups على مستوى الـ View.',en:'1) Technical → Access Rights for the Model.\\n2) Record Rules and Domain.\\n3) User group on Users.\\n4) Real login test.\\n5) Sensitive fields: groups at View level.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'ابحث Access Rights عن model sale.order ولاحظ الفرق بين Group المندوب والمدير إن وُجد.',en:'Search Access Rights for model sale.order and note salesman vs manager group differences if present.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'بعد أي موديول مخصص: اختبر مستخدم Sales User قبل التسليم.',en:'After any custom module: test a Sales User before go-live.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'قاعدة Global بلا فهم — قد تخفي كل السجلات عن الجميع.',en:'A global rule without understanding — may hide all records from everyone.'}}
    ],
    knowledgeCheck:{question:{ar:'اختبار الصلاحيات الصحيح؟',en:'Correct way to test rights?'},options:{ar:['Admin فقط دائماً','دخول بمستخدم الدور الفعلي','تعطيل الأمن','حذف القواعد'],en:['Admin only always','Login as the real role user','Disable security','Delete rules']},answer:1,explanation:{ar:'Admin لا يكشف قيود المندوب.',en:'Admin does not reveal salesman restrictions.'}}},
  {id:'technical-05',path:'technical',order:5,title:{ar:'ملخص المسار التقني',en:'Technical Path Summary'},description:{ar:'من الشاشة إلى الموديول',en:'From screen to module'},duration:8,xp:15,
    objectives:{ar:['تلخيص السلسلة التقنية'],en:['Summarize the technical chain']},
    sections:[
      {type:'intro',title:{ar:'الخريطة',en:'Map'},content:{ar:'واجهة → Model/Fields → Views (وراثة) → Actions/Menus → Security (ACL+Rules) → Module في Git.\\nStudio للسريع؛ الكود للجاد.\\nDeveloper Mode للقراءة لا للتعديل العشوائي على الإنتاج.',en:'UI → Model/Fields → Views (inheritance) → Actions/Menus → Security (ACL+Rules) → Module in Git.\\nStudio for speed; code for serious work.\\nDeveloper Mode for reading, not random production edits.'}},
      {type:'tip',title:{ar:'الخطوة التالية',en:'Next step'},content:{ar:' downstream: Server Actions، Automated Actions، API (XML-RPC/JSON-RPC)، و اختبارات الموديول.',en:'Next: Server Actions, Automated Actions, API (XML-RPC/JSON-RPC), and module tests.'}}
    ],
    knowledgeCheck:null}

,

  {id:'technical-quiz',path:'technical',order:6,title:{ar:'اختبار الأسس التقنية',en:'Technical Foundations Quiz'},description:{ar:'اختبر Model و View و Security',en:'Test Model, View and Security'},duration:15,xp:50,isQuiz:true,quizId:'quiz-technical',
    sections:[{type:'intro',title:{ar:'اختبار',en:'Quiz'},content:{ar:'أجب عن أسئلة معمارية أودو.',en:'Answer Odoo architecture questions.'}}],
    knowledgeCheck:null}

,

  ,
  {id:'pos-01',path:'pos',order:1,title:{ar:'نظرة عامة على نقاط البيع',en:'Point of Sale Overview'},description:{ar:'جلسة POS من الفتح إلى الإغلاق',en:'POS session from open to close'},duration:14,xp:25,
    objectives:{ar:['فتح جلسة POS','بيع سريع على الشاشة','إغلاق الجلسة'],en:['Open POS session','Quick sale on screen','Close session']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'نقطة البيع (POS) واجهة سريعة للبيع بالتجزئة: اختيار منتجات، عربة، دفع، وإيصال. خلف الشاشة تُنشأ أوامر/قيود حسب الإعداد وترتبط بالمخزون إن كان المنتج Storable.',en:'Point of Sale is a fast retail UI: products, cart, payment, receipt. Behind the screen, orders/entries are created per setup and link to stock if the product is Storable.'}},
      {type:'why',title:{ar:'لماذا POS منفصل عن Sales؟',en:'Why POS separate from Sales?'},content:{ar:'سرعة الكاشير وواجهة لمس/شبكة منتجات أهم من Form أمر البيع الكامل. نفس الشركة والمخزون، بمسار شاشة مختلف.',en:'Cashier speed and a product-grid UI matter more than a full sales order form. Same company and stock, different screen path.'}},
      {type:'visual',title:{ar:'شاشة الجلسة',en:'Session screen'},content:{ar:'افتح Point of Sale → اختر نقطة البيع → New Session. تظهر شبكة المنتجات والعربة وأزرار الدفع.',en:'Open Point of Sale → choose a POS → New Session. Product grid, cart and payment buttons appear.'},image:'pos-session.svg',caption:{ar:'<strong>POS Session</strong> — شبكة منتجات + عربة + Payment. أغلِق الجلسة في نهاية الوردية.',en:'<strong>POS Session</strong> — product grid + cart + Payment. Close the session at shift end.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Apps → Point of Sale.\\n2) New Session / Continue.\\n3) اختر المنتجات للكمية.\\n4) Payment: Cash/Card → Validate.\\n5) Receipt.\\n6) Close Session: عدّ النقد وطابق المبلغ.\\n7) راقب المخزون للمنتجات Storable بعد البيع.',en:'1) Apps → Point of Sale.\\n2) New Session / Continue.\\n3) Pick products and qty.\\n4) Payment: Cash/Card → Validate.\\n5) Receipt.\\n6) Close Session: count cash and match amount.\\n7) Watch On Hand for Storable products after sale.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'بيع Laptop نقداً: أضفه للعربة → Payment Cash → Validate → Close Session بمبلغ مطابق.',en:'Sell Laptop cash: add to cart → Payment Cash → Validate → Close Session with matching amount.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'في تجريبي: افتح POS ولاحظ شبكة المنتجات دون إغلاق جلسة إنتاج حقيقية.',en:'On trial: open POS and notice the product grid without closing a real production session.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اربط POS بمستودع واضح حتى لا يُخصم المخزون من موقع خاطئ.',en:'Link POS to a clear warehouse so stock is not deducted from the wrong location.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ترك الجلسة مفتوحة أياماً دون Close — صعوبة المطابقة والتدقيق.',en:'Leaving the session open for days without Close — hard reconciliation and audit.'}}
    ],
    knowledgeCheck:{question:{ar:'إجراء نهاية الوردية في POS؟',en:'End-of-shift action in POS?'},options:{ar:['Delete Database','Close Session','BOM','RFQ'],en:['Delete Database','Close Session','BOM','RFQ']},answer:1,explanation:{ar:'إغلاق الجلسة ومطابقة النقد.',en:'Close session and match cash.'}}},
  {id:'pos-02',path:'pos',order:2,title:{ar:'المنتجات والدفع في POS',en:'Products and Payment in POS'},description:{ar:'إعداد المنتج للدفع السريع',en:'Product setup for fast checkout'},duration:12,xp:20,
    objectives:{ar:['منتج يظهر في POS','طرق الدفع','أثر المخزون'],en:['Product visible in POS','Payment methods','Stock impact']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المنتج يجب أن يكون متاحاً لـ POS (إعداد المنتج/الفئة). طرق الدفع تُضبط في إعدادات نقطة البيع. البيع يخصم On Hand إن كان Storable بعد الإتمام.',en:'The product must be available for POS (product/category setup). Payment methods are set on the POS config. Sale decreases On Hand if Storable after completion.'}},
      {type:'concept',title:{ar:'خطوات',en:'Steps'},content:{ar:'1) Product: Available in POS / PoS category.\\n2) POS Config: Payment methods (Cash, Bank).\\n3) Session → بيع → Payment.\\n4) بعد الإغلاق راجع تقارير POS والمخزون.',en:'1) Product: Available in POS / PoS category.\\n2) POS Config: Payment methods (Cash, Bank).\\n3) Session → sell → Payment.\\n4) After close review POS reports and stock.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح بطاقة منتج وتحقق من خيارات POS إن وُجدت دون تغيير الإنتاج.',en:'Open a product form and check POS options if present without production changes.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'باركود يسرّع الكاشير — اضبط barcode على المنتج.',en:'Barcode speeds the cashier — set barcode on the product.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'منتج Service يُباع كأنه مخزني أو العكس — راجع نوع المنتج.',en:'A Service product sold as storable or the opposite — check product type.'}}
    ],
    knowledgeCheck:{question:{ar:'لكي يظهر المنتج في شاشة POS غالباً تحتاج؟',en:'For a product to appear on POS you often need?'},options:{ar:['حذف الضرائب','تفعيل Available in POS / فئة POS','إغلاق الشركة','تعطيل المخزون دائماً'],en:['Delete taxes','Enable Available in POS / POS category','Close company','Always disable stock']},answer:1,explanation:{ar:'إعداد المنتج/الفئة لنقطة البيع.',en:'Product/category POS setup.'}}},
  {id:'pos-03',path:'pos',order:3,title:{ar:'ملخص مسار POS',en:'POS Path Summary'},description:{ar:'جلسة → بيع → دفع → إغلاق',en:'Session → sale → pay → close'},duration:6,xp:10,
    sections:[
      {type:'intro',title:{ar:'الخريطة',en:'Map'},content:{ar:'Open Session → Products → Cart → Payment → Receipt → Close Session → Stock/Accounting per config.',en:'Open Session → Products → Cart → Payment → Receipt → Close Session → Stock/Accounting per config.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'درّب الكاشير على Close Session يومياً قبل المغادرة.',en:'Train cashiers to Close Session daily before leaving.'}}
    ],
    knowledgeCheck:null},

  {id:'project-01',path:'project',order:1,title:{ar:'المشاريع والمهام',en:'Projects and Tasks'},description:{ar:'شاشات المشروع والمهمة',en:'Project and task screens'},duration:14,xp:25,
    objectives:{ar:['إنشاء مشروع','إنشاء مهمة','تتبع المرحلة'],en:['Create a project','Create a task','Track stage']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'تطبيق Project ينظّم العمل: Project → Tasks بمراحل Kanban. مناسب للخدمات والتنفيذ الداخلي بجانب المبيعات.',en:'The Project app organizes work: Project → Tasks with Kanban stages. Fits services and internal delivery alongside sales.'}},
      {type:'visual',title:{ar:'مهمة على الشاشة',en:'Task on screen'},content:{ar:'Form المهمة: العنوان، المشروع، المسؤول، المرحلة، الوصف. Kanban للسحب بين المراحل.',en:'Task form: title, project, assignee, stage, description. Kanban to drag between stages.'},image:'project-task.svg',caption:{ar:'<strong>Project Task</strong> — المرحلة + المسؤول + تسجيل الوقت.',en:'<strong>Project Task</strong> — stage + assignee + time log.'}},
      {type:'concept',title:{ar:'خطوات',en:'Steps'},content:{ar:'1) Apps → Project → New Project.\\n2) Tasks → New: عنوان + Project + Assignee.\\n3) حرّك المرحلة على Kanban عند التقدم.\\n4) Chatter للتواصل.\\n5) اربط Sales Order بالخدمة إن لزم (حسب الإصدار/الإعداد).',en:'1) Apps → Project → New Project.\\n2) Tasks → New: title + Project + Assignee.\\n3) Move stage on Kanban as work progresses.\\n4) Chatter for communication.\\n5) Link Sales Order to service if needed (per version/setup).'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'أنشئ مشروعاً تجريبياً ومهمة واحدة وحرّكها مرحلة دون بيانات إنتاج.',en:'Create a trial project and one task and move its stage without production data.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'مراحل قليلة واضحة أفضل من عشرات الأعمدة الفارغة.',en:'Few clear stages beat dozens of empty columns.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'مهام بلا مسؤول — لا أحد يملك التنفيذ على الشاشة.',en:'Tasks with no assignee — no one owns execution on screen.'}}
    ],
    knowledgeCheck:{question:{ar:'عرض Kanban في المشاريع يفيد لـ؟',en:'Kanban in projects helps to?'},options:{ar:['حذف الفواتير','تتبع مراحل المهام','BOM فقط','Close POS'],en:['Delete invoices','Track task stages','BOM only','Close POS']},answer:1,explanation:{ar:'مراحل التنفيذ.',en:'Execution stages.'}}},
  {id:'project-02',path:'project',order:2,title:{ar:'الجداول الزمنية (Timesheets)',en:'Timesheets'},description:{ar:'تسجيل الساعات على المهام',en:'Log hours on tasks'},duration:12,xp:20,
    objectives:{ar:['تسجيل وقت','ربط الوقت بالمهمة','مراجعة الساعات'],en:['Log time','Link time to task','Review hours']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'Timesheets تسجّل الساعات على مهمة/مشروع للفوترة الداخلية أو للعميل. الشاشة: من المهمة Log Time أو قائمة Timesheets.',en:'Timesheets log hours on a task/project for internal or customer billing. Screen: Log Time from the task or Timesheets list.'}},
      {type:'concept',title:{ar:'خطوات',en:'Steps'},content:{ar:'1) افتح Task.\\n2) Log Time / Timesheets: التاريخ والمدة والوصف.\\n3) Save.\\n4) راجع مجموع الساعات على المشروع.\\n5) إن فوترة: من Sales/Project حسب الإعداد.',en:'1) Open Task.\\n2) Log Time / Timesheets: date, duration, description.\\n3) Save.\\n4) Review total hours on the project.\\n5) If billing: from Sales/Project per setup.'}},
      {type:'visual',title:{ar:'تسجيل الوقت',en:'Time log'},content:{ar:'نفس بطاقة المهمة: أضف سطراً زمنياً واحفظ. الرقم يظهر في تقارير المشروع.',en:'Same task form: add a time line and save. The number appears in project reports.'},image:'project-task.svg',caption:{ar:'<strong>Timesheet on Task</strong> — مدة + وصف + تاريخ.',en:'<strong>Timesheet on Task</strong> — duration + description + date.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'على مهمة تجريبية: أضف ساعة واحدة ووصفاً قصيراً.',en:'On a trial task: add one hour and a short description.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'سجّل الوقت يومياً لا أسبوعياً دفعة واحدة — دقة أعلى.',en:'Log time daily, not in a weekly batch — higher accuracy.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'ساعات بلا مهمة/مشروع — لا يمكن تحليل الربحية لاحقاً.',en:'Hours without task/project — profitability analysis becomes impossible later.'}}
    ],
    knowledgeCheck:{question:{ar:'Timesheet يُربط عادة بـ؟',en:'A timesheet is usually linked to?'},options:{ar:['Journal Bank فقط','مهمة/مشروع','Close POS فقط','ضريبة'],en:['Bank journal only','Task/project','Close POS only','Tax']},answer:1,explanation:{ar:'الوقت على العمل.',en:'Time on work.'}}},
  {id:'project-03',path:'project',order:3,title:{ar:'ملخص مسار المشاريع',en:'Project Path Summary'},description:{ar:'مشروع → مهمة → وقت',en:'Project → task → time'},duration:6,xp:10,
    sections:[
      {type:'intro',title:{ar:'الخريطة',en:'Map'},content:{ar:'Project → Tasks (Kanban stages) → Timesheets → (optional) invoice from hours.',en:'Project → Tasks (Kanban stages) → Timesheets → (optional) invoice from hours.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'اربط المشروع بأمر بيع خدمي عندما تفوتر بالساعة.',en:'Link the project to a service sales order when you bill by the hour.'}}
    ],
    knowledgeCheck:null},

  {id:'lab-01',path:'fundamentals',order:11,title:{ar:'مختبر: مستخدم وصلاحيات',en:'Lab: User and Rights'},description:{ar:'تمرين عملي على قاعدة تجريبية',en:'Hands-on on a trial database'},duration:20,xp:40,isLab:true,
    objectives:{ar:['إنشاء مستخدم','تعيين Sales User','اختبار الدخول'],en:['Create user','Assign Sales User','Test login']},
    sections:[
      {type:'intro',title:{ar:'المطلوب',en:'Goal'},content:{ar:'مختبر عملي: نفّذ على أودو تجريبي ثم علّم الخطوات منجزّة.',en:'Hands-on lab: execute on trial Odoo then mark steps done.'}},
      {type:'concept',title:{ar:'قائمة التحقق',en:'Checklist'},content:{ar:'1) Settings → Users → New.\\n2) Login + اسم.\\n3) Access Rights: Sales = User فقط.\\n4) بلا Administration.\\n5) Save.\\n6) تسجيل خروج ودخول بالمستخدم.\\n7) تأكد: Sales ظاهر، Settings غير ظاهر.\\n8) أنشئ Contact تجريبي.\\n✓ عند النجاح تكون فهمت ACL على مستوى التطبيق.',en:'1) Settings → Users → New.\\n2) Login + name.\\n3) Access Rights: Sales = User only.\\n4) No Administration.\\n5) Save.\\n6) Log out and in as the user.\\n7) Confirm: Sales visible, Settings hidden.\\n8) Create a trial Contact.\\n✓ Success means you understood app-level ACL.'}},
      {type:'practice',title:{ar:'نفّذ الآن',en:'Do it now'},content:{ar:'افتح قاعدتك التجريبية ونفّذ القائمة. لا تستخدم قاعدة الإنتاج.',en:'Open your trial database and run the checklist. Do not use production.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'صوّر الشاشة بعد الدخول بالمستخدم الجديد كإثبات تمرين.',en:'Screenshot after login as the new user as exercise proof.'}}
    ],
    knowledgeCheck:null},
  {id:'lab-02',path:'sales',order:11,title:{ar:'مختبر: من عرض إلى تأكيد',en:'Lab: Quote to Confirm'},description:{ar:'تمرين sale.order كامل',en:'Full sale.order exercise'},duration:25,xp:40,isLab:true,
    sections:[
      {type:'intro',title:{ar:'المطلوب',en:'Goal'},content:{ar:'أنشئ عميلاً و المنتج إن لزم، عرض سعر، ثم Confirm، وحدد Smart Buttons.',en:'Create customer and product if needed, quotation, then Confirm, and identify smart buttons.'}},
      {type:'concept',title:{ar:'قائمة التحقق',en:'Checklist'},content:{ar:'1) Contacts → عميل تجريبي.\\n2) Product Storable بسيط.\\n3) Sales → Quotation → New.\\n4) partner_id + سطر منتج.\\n5) Save (Draft).\\n6) Confirm.\\n7) اقرأ state على Statusbar.\\n8) سمِّ Smart Buttons الظاهرة.\\n9) لا Validate تسليم على الإنتاج.\\n✓ فهمت مسار sale.order على الشاشة.',en:'1) Contacts → trial customer.\\n2) Simple Storable product.\\n3) Sales → Quotation → New.\\n4) partner_id + product line.\\n5) Save (Draft).\\n6) Confirm.\\n7) Read state on statusbar.\\n8) Name visible smart buttons.\\n9) Do not Validate delivery on production.\\n✓ You understood sale.order on screen.'}},
      {type:'practice',title:{ar:'نفّذ الآن',en:'Do it now'},content:{ar:'نفّذ على تجريبي فقط. استخدم محاكي المبيعات في الأكاديمية للمراجعة السريعة أولاً إن أحببت.',en:'Run on trial only. Use the academy sales simulator for a quick review first if you like.'}}
    ],
    knowledgeCheck:null},
  {id:'lab-03',path:'inventory',order:11,title:{ar:'مختبر: استلام وOn Hand',en:'Lab: Receipt and On Hand'},description:{ar:'Validate وأثر الكمية',en:'Validate and qty impact'},duration:25,xp:40,isLab:true,
    sections:[
      {type:'intro',title:{ar:'المطلوب',en:'Goal'},content:{ar:'قارن On Hand قبل وبعد Validate لاستلام تجريبي.',en:'Compare On Hand before and after Validate on a trial receipt.'}},
      {type:'concept',title:{ar:'قائمة التحقق',en:'Checklist'},content:{ar:'1) سجّل On Hand لمنتج Storable.\\n2) أنشئ PO تجريبي أو Receipt.\\n3) Done = كمية.\\n4) Validate.\\n5) أعد قراءة On Hand.\\n6) اكتب الفرق.\\n✓ فهمت أن Validate هو قرار المخزون.',en:'1) Note On Hand for a Storable product.\\n2) Create trial PO or Receipt.\\n3) Done = qty.\\n4) Validate.\\n5) Re-read On Hand.\\n6) Write the difference.\\n✓ You understood Validate as the stock decision.'}},
      {type:'practice',title:{ar:'نفّذ الآن',en:'Do it now'},content:{ar:'بيئة تجريبية فقط — لا Validate على بيانات حقيقية للتدريب.',en:'Trial environment only — no Validate on real data for training.'}}
    ],
    knowledgeCheck:null}

,

  ,
  {id:'inventory-11',path:'inventory',order:12,title:{ar:'المسارات والقواعد (Routes & Rules)',en:'Routes and Rules'},description:{ar:'Buy/Make/Replenish على الشاشة',en:'Buy/Make/Replenish on screen'},duration:16,xp:30,
    objectives:{ar:['فهم Route على المنتج','ربط الشراء/التصنيع بالتجديد','قراءة المسار من الشاشة'],en:['Understand Route on product','Link buy/make to replenishment','Read route from screen']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'Routes في المخزون تحدد كيف يُلبَّى الطلب: شراء (Buy)، تصنيع (Manufacture)، أو نقل من مستودع آخر. تظهر على بطاقة المنتج وفي إعدادات Inventory. القواعد (Rules) تربط المسار بعملية (مثل إنشاء PO أو MO).',en:'Inventory Routes define how demand is fulfilled: Buy, Manufacture, or transfer from another warehouse. They appear on the product form and in Inventory settings. Rules link a route to an operation (e.g. create PO or MO).'}},
      {type:'why',title:{ar:'لماذا Routes؟',en:'Why Routes?'},content:{ar:'بدون مسار واضح يختار النظام تجديدًا خاطئًا أو لا يقترح شيئاً. على الشاشة: المنتج + Routes = سلوك التجديد عند انخفاض On Hand أو عند أمر بيع.',en:'Without a clear route the system may replenish wrongly or suggest nothing. On screen: product + Routes = replenishment behaviour when On Hand drops or a sales order is confirmed.'}},
      {type:'visual',title:{ar:'بطاقة المنتج والمسارات',en:'Product form and routes'},content:{ar:'Inventory tab على المنتج: خيارات Buy و Manufacture. فعّل ما يطابق عملك ثم احفظ.',en:'Inventory tab on the product: Buy and Manufacture options. Enable what matches your business then save.'},image:'product-catalog.png',caption:{ar:'<strong>Product → Inventory / Routes</strong> — Buy و Manufacture أشيع خيارين للبداية.',en:'<strong>Product → Inventory / Routes</strong> — Buy and Manufacture are the most common starters.'}},
      {type:'concept',title:{ar:'خطوات على الشاشة',en:'On-screen steps'},content:{ar:'1) Inventory → Configuration → Routes (أو من المنتج).\\n2) على المنتج: Inventory → فعّل Buy و/أو Manufacture.\\n3) إن Buy: اربط مورداً (Vendor) على المنتج أو استخدم Reordering Rule.\\n4) إن Manufacture: يلزم BOM.\\n5) اختبر بأمر بيع أو Run Scheduler في التجريبي.\\n6) راقب طلبات RFQ أو MO الناتجة.',en:'1) Inventory → Configuration → Routes (or from product).\\n2) On product: Inventory → enable Buy and/or Manufacture.\\n3) If Buy: link a Vendor on the product or use a Reordering Rule.\\n4) If Manufacture: a BOM is required.\\n5) Test with a sales order or Run Scheduler on trial.\\n6) Watch resulting RFQ or MO.'}},
      {type:'example',title:{ar:'مثال',en:'Example'},content:{ar:'منتج يُشترى فقط: Route Buy + Vendor. عند انخفاض تحت Min يُقترح شراء لا تصنيع.',en:'Buy-only product: Buy route + Vendor. When below Min, purchase is suggested, not manufacturing.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'افتح منتجاً تجريبياً وحدد هل Buy مفعّل. لا تغيّر إنتاجاً حياً.',en:'Open a trial product and check whether Buy is enabled. Do not change live production.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'ابدأ بمسار واحد لكل منتج قبل تفعيل مسارات متعددة المستودعات.',en:'Start with one route per product before enabling multi-warehouse routes.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تفعيل Manufacture بلا BOM — أوامر تفشل أو لا تُنشأ مكونات.',en:'Enabling Manufacture without a BOM — orders fail or components are not created.'}}
    ],
    knowledgeCheck:{question:{ar:'Route نوع Buy يعني غالباً؟',en:'A Buy route usually means?'},options:{ar:['تصنيع داخلي فقط','تجديد عبر شراء','إجازة موظف','إغلاق POS'],en:['Internal manufacturing only','Replenish via purchase','Employee time off','Close POS']},answer:1,explanation:{ar:'الشراء من مورد.',en:'Purchase from a vendor.'}}},
  {id:'inventory-12',path:'inventory',order:13,title:{ar:'مستودعات متعددة (Multi-warehouse)',en:'Multi-warehouse'},description:{ar:'مستودع ومواقع على الشاشات',en:'Warehouse and locations on screens'},duration:14,xp:25,
    objectives:{ar:['الفرق مستودع/موقع','تحويل بين مستودعات','اختيار المستودع على العملية'],en:['Warehouse vs location','Transfer between warehouses','Pick warehouse on the operation']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'المستودع (Warehouse) كيان تشغيلي أعلى المواقع (Locations). Multi-warehouse يعني أكثر من مستودع لكل منها مواقع داخلية. التحويل بينها عبر Internal Transfer أو مسارات بين المستودعات.',en:'A Warehouse is an operational entity above Locations. Multi-warehouse means more than one warehouse, each with internal locations. Moves between them use Internal Transfer or inter-warehouse routes.'}},
      {type:'concept',title:{ar:'على الشاشة',en:'On screen'},content:{ar:'1) Inventory → Configuration → Warehouses.\\n2) كل مستودع له مواقع افتراضية (Stock, Input, Output…).\\n3) على Receipt/Delivery تحقق من Warehouse في الرأس.\\n4) Internal Transfer: مصدر ووجهة قد يكونان مستودعين مختلفين.\\n5) On Hand يمكن تجميعه حسب المستودع/الموقع.',en:'1) Inventory → Configuration → Warehouses.\\n2) Each warehouse has default locations (Stock, Input, Output…).\\n3) On Receipt/Delivery check Warehouse in the header.\\n4) Internal Transfer: source and destination may be different warehouses.\\n5) On Hand can be grouped by warehouse/location.'}},
      {type:'visual',title:{ar:'قائمة العمليات',en:'Operations list'},content:{ar:'عند تعدد المستودعات يظهر عمود/فلتر المستودع في List. لا Validate قبل التأكد من المستودع الصحيح.',en:'With multiple warehouses a warehouse column/filter appears on the List. Do not Validate before the correct warehouse is set.'},image:'list-view.png',caption:{ar:'<strong>Transfers List</strong> — راجع المستودع قبل Validate.',en:'<strong>Transfers List</strong> — check warehouse before Validate.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من الإعدادات افتح Warehouses في تجريبي واقرأ المواقع الافتراضية لمستودع واحد.',en:'From settings open Warehouses on trial and read default locations for one warehouse.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'لا تنشئ مستودعاً ثانياً «للتجربة» على الإنتاج دون خطة مواقع ومسارات.',en:'Do not create a second warehouse “for testing” on production without a location and route plan.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'استلام على مستودع A بينما البيع من B — نقص وهمي في B وفائض في A.',en:'Receiving into warehouse A while selling from B — phantom shortage in B and surplus in A.'}}
    ],
    knowledgeCheck:{question:{ar:'الفرق الأساسي؟',en:'Main difference?'},options:{ar:['المستودع تحت الموقع دائماً','المستودع أعلى والمواقع داخله','لا فرق','POS فقط'],en:['Warehouse always under location','Warehouse is higher; locations are inside it','No difference','POS only']},answer:1,explanation:{ar:'هيكل هرمي: Warehouse → Locations.',en:'Hierarchy: Warehouse → Locations.'}}},
  {id:'integrations-01',path:'integrations',order:1,title:{ar:'التكاملات ونظرة API',en:'Integrations and API Overview'},description:{ar:'متى نربط أودو بأنظمة خارجية',en:'When to connect Odoo to external systems'},duration:14,xp:25,
    objectives:{ar:['أنواع التكامل','فكرة XML-RPC/JSON-RPC','حدود التكامل الآمن'],en:['Integration types','XML-RPC/JSON-RPC idea','Safe integration limits']},
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'أودو يتكامل مع بوابات دفع، شحن، متاجر، وERP أخرى. وظيفياً: حدد أي وثيقة تُصدَّر/تُستورد. تقنياً: External API (XML-RPC أو JSON-2 في الإصدارات الحديثة)، Webhooks، أو موصلات جاهزة.',en:'Odoo integrates with payment gateways, carriers, stores and other ERPs. Functionally: decide which documents are exported/imported. Technically: external API (XML-RPC or JSON-2 in newer versions), webhooks, or ready connectors.'}},
      {type:'why',title:{ar:'لماذا بحذر؟',en:'Why carefully?'},content:{ar:'تكامل خاطئ يكرّر العملاء أو الأوامر أو يكسر المخزون. ابدأ بعملية واحدة (مثل إنشاء Contact) على تجريبي.',en:'A wrong integration duplicates customers or orders or breaks stock. Start with one process (e.g. create Contact) on trial.'}},
      {type:'concept',title:{ar:'خريطة عملية',en:'Practical map'},content:{ar:'1) حدّد السيناريو: مثلاً طلبات من متجر → sale.order.\\n2) مستخدم API بصلاحيات أقل ما يمكن.\\n3) جرب على Staging.\\n4) سجّل الأخطاء (Logging).\\n5) لا تكتب مباشرة في SQL.\\n6) راقب التكرار عبر External ID / barcode / SKU.',en:'1) Define the scenario: e.g. store orders → sale.order.\\n2) API user with least privilege.\\n3) Test on staging.\\n4) Log errors.\\n5) Do not write SQL directly.\\n6) Prevent duplicates via External ID / barcode / SKU.'}},
      {type:'visual',title:{ar:'نفس النماذج عبر API',en:'Same models via API'},content:{ar:'API يقرأ/يكتب نفس Models التي تراها على الشاشة: res.partner، sale.order… الصلاحيات نفسها تُطبَّق.',en:'The API reads/writes the same Models you see on screen: res.partner, sale.order… The same access rights apply.'},image:'form-view.png',caption:{ar:'<strong>Form = Model</strong> — ما تحميه Groups على الشاشة يُحمى على API أيضاً.',en:'<strong>Form = Model</strong> — what Groups protect on screen is also protected on the API.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'اكتب سيناريو تكامل واحد لشركتك: المصدر → Model في أودو → تكرار الحقول الحرجة.',en:'Write one integration scenario for your company: source → Odoo Model → critical fields to match.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'فضّل الموصل الرسمي أو وحدة معروفة قبل بناء تكامل مخصص كامل.',en:'Prefer an official connector or known module before building a full custom integration.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'مفتاح Admin في تطبيق خارجي — خطر أمني. أنشئ مستخدم تكامل محدود.',en:'Admin key in an external app — security risk. Create a limited integration user.'}}
    ],
    knowledgeCheck:{question:{ar:'أفضل ممارسة لمستخدم API؟',en:'Best practice for an API user?'},options:{ar:['Admin كامل دائماً','أقل صلاحية كافية','حذف كل القواعد','مشاركة كلمة مرور المدير'],en:['Full Admin always','Least privilege sufficient','Delete all rules','Share manager password']},answer:1,explanation:{ar:'Least privilege.',en:'Least privilege.'}}},
  {id:'integrations-02',path:'integrations',order:2,title:{ar:'الملف والدفع والشحن',en:'Export, Payment and Shipping'},description:{ar:'تكاملات شائعة من الشاشة',en:'Common integrations from the UI'},duration:12,xp:20,
    sections:[
      {type:'intro',title:{ar:'مقدمة',en:'Introduction'},content:{ar:'من الشاشة: تصدير Excel/CSV من List، بوابات الدفع على الفاتورة/المتجر، شركات الشحن على التسليم. كل منها يغيّر أو يقرأ حقولاً على نفس المستندات.',en:'From the UI: Excel/CSV export from List, payment acquirers on invoice/shop, carriers on delivery. Each changes or reads fields on the same documents.'}},
      {type:'concept',title:{ar:'خطوات وعي',en:'Awareness steps'},content:{ar:'1) List → Action → Export: اختر الحقول بما فيها التقنية إن لزم.\\n2) Payment providers: من Accounting/Website حسب الإصدار.\\n3) Shipping connectors: على Delivery method.\\n4) اختبر في تجريبي بمبلغ صغير.\\n5) راجع القيود بعد الدفع التجريبي.',en:'1) List → Action → Export: choose fields including technical if needed.\\n2) Payment providers: from Accounting/Website per version.\\n3) Shipping connectors: on delivery method.\\n4) Test on trial with a small amount.\\n5) Review entries after a test payment.'}},
      {type:'practice',title:{ar:'جرّب الآن',en:'Try now'},content:{ar:'من أي List: افتح Export واختر حقلين فقط — لا تصدّر بيانات حساسة لبريد شخصي.',en:'From any List: open Export and pick only two fields — do not export sensitive data to a personal mailbox.'}},
      {type:'tip',title:{ar:'نصيحة',en:'Tip'},content:{ar:'وثّق كل موصل: من يملك المفتاح، أين يُخزَّن، ماذا يحدث عند الفشل.',en:'Document every connector: who owns the key, where it is stored, what happens on failure.'}},
      {type:'mistake',title:{ar:'خطأ شائع',en:'Common Mistake'},content:{ar:'تفعيل دفع حي على قاعدة تجريبية أو العكس.',en:'Enabling live payment on a trial database or the opposite.'}}
    ],
    knowledgeCheck:{question:{ar:'تصدير List يفيد لـ؟',en:'List export is useful for?'},options:{ar:['حذف الشركة','تحليل خارجي ونسخ احتياطي جزئي','إغلاق الجلسة فقط','BOM'],en:['Deleting the company','External analysis and partial backup','Closing session only','BOM']},answer:1,explanation:{ar:'بيانات للتحليل مع الحذر.',en:'Data for analysis, carefully.'}}},
  {id:'integrations-03',path:'integrations',order:3,title:{ar:'ملخص التكاملات',en:'Integrations Summary'},description:{ar:'مبادئ قبل الربط',en:'Principles before connecting'},duration:6,xp:10,
    sections:[
      {type:'intro',title:{ar:'الخريطة',en:'Map'},content:{ar:'سيناريو واضح → Model معروف → مستخدم محدود → Staging → Logging → مراقبة التكرار. الشاشة والـ API نفس الأمان.',en:'Clear scenario → known Model → limited user → Staging → Logging → duplicate control. UI and API share the same security.'}},
      {type:'tip',title:{ar:'الخطوة التالية',en:'Next step'},content:{ar:'بعد ذلك: webhooks، طوابير، و Odoo.sh branches للتجربة الآمنة.',en:'Next: webhooks, queues, and Odoo.sh branches for safe experiments.'}}
    ],
    knowledgeCheck:null}

];
